local config = {
  ui_story_5083_50830100_1_dialog_content = "¿Cuál es la razón detrás de las pesadillas? Para ser honesto... tampoco lo sé realmente.",
  ui_story_5083_50830100_2_dialog_content = "Pero definitivamente están conectados con tus recuerdos.",
  ui_story_5083_50830100_3_dialog_content = "Tal vez sea un pasado que no puedes aceptar, o arrepentimientos de los que no puedes soltarte—",
  ui_story_5083_50830100_4_dialog_content = "No tiene sentido para mí, así que déjalo. Confío en ti, así que solo haz lo que tengas que hacer.",
  ui_story_5083_50830100_5_dialog_content = "Está bien, entonces solo acuéstate y relájate... Mientras intento resonar con tu mente...",
  ui_story_5083_50830100_6_dialog_content = "Hombre, me estoy poniendo bastante somnoliento... ¿Significa esto que voy a tener ese mismo sueño otra vez...?",
  ui_story_5083_50830100_7_dialog_content = "Ah, olvídalo... Estoy seguro de que estaré bien con tú alrededor...",
  ui_story_5083_50830100_8_dialog_content = "Solo duerme... Y prepárate para enfrentarlo...",
  ui_story_5083_50830100_9_dialog_content = "<color=#e8d9bb>Un silbato agudo atraviesa el aire.</color>",
  ui_story_5083_50830100_10_dialog_content = "\"¡No sé lo que me han dicho!\"",
  ui_story_5083_50830100_11_dialog_content = "\"¡Matar a los Eclipsites nunca pasa de moda!\"",
  ui_story_5083_50830100_12_dialog_content = "¿Es este...?",
  ui_story_5083_50830100_13_dialog_content = "\"¡Marzo!\"",
  ui_story_5083_50830100_14_dialog_content = "\"March!\"",
  ui_story_5083_50830100_15_dialog_content = "¿Campo de entrenamiento, huh? Esa también es una vieja canción de entrenamiento...",
  ui_story_5083_50830100_16_dialog_content = "¿Qué pasa, Barton?! ¡No te detengas justo en medio de la pista!",
  ui_story_5083_50830100_17_dialog_content = "¿Perrito... eres tú...?",
  ui_story_5083_50830100_18_dialog_content = "¿Todavía medio dormido? Ese es tu problema, amigo.",
  ui_story_5083_50830100_19_dialog_content = "¡¿Dogg realmente logró pasar Barton?!",
  ui_story_5083_50830100_20_dialog_content = "Nah, es porque Barton se detuvo de repente... Esto va a ser bueno.",
  ui_story_5083_50830100_21_dialog_content = "Barton, ¡eres un imbécil! Este es un campo de entrenamiento, no un campo de ensueño!",
  ui_story_5083_50830100_22_dialog_content = "¿Qué pasó para convertirte en el soldado más ejemplar de la legión? Si quieres avergonzar a mi legión por holgazanear, ¡entonces simplemente lárgate de aquí!",
  ui_story_5083_50830100_23_dialog_content = "¡El resto de ustedes, sigan corriendo!",
  ui_story_5083_50830100_24_dialog_content = "Comandante Pango, humph... ¿Quién dijo que estaba holgazaneando?!",
  ui_story_5083_50830100_25_dialog_content = "¡Solo trata de seguir mi ritmo!",
  ui_story_5083_50830100_26_dialog_content = "\"¡Armas presentes!\"",
  ui_story_5083_50830100_27_dialog_content = "¡Toma esto—¡Arghhh!",
  ui_story_5083_50830100_28_dialog_content = "¡No dejes que él arruine tu cadencia, soldados! Repitan después de mí: \"¡Amo mi arma, sí lo hago!\"",
  ui_story_5083_50830100_29_dialog_content = "\"¡Amo mi arma, sí lo hago!\"",
  ui_story_5083_50830100_30_dialog_content = "\"Tengo un montón de munición lista para ti—\"",
  ui_story_5083_50830100_31_dialog_content = "<size=45>¡Ooooooh!</size>",
  ui_story_5083_50830100_32_dialog_content = "Je, finalmente me alcanzaste, Barton.",
  ui_story_5083_50830100_33_dialog_content = "Huff—Huff—¡Eso no fue nada!",
  ui_story_5083_50830100_34_dialog_content = "¿Estás seguro de eso? A juzgar por lo agotado que pareces, estoy bastante seguro de que estoy ganando esta última vuelta.",
  ui_story_5083_50830100_35_dialog_content = "Je... Veamos... solo sobre eso!",
  ui_story_5083_50830100_36_dialog_content = "Esos dos idiotas...",
  ui_story_5083_50830100_37_dialog_content = "<color=#e8d9bb>Los dos soldados luchan desesperadamente por la delantera, dejando al resto de la 2da Legión muy atrás.</color>",
  ui_story_5083_50830100_38_dialog_content = "<color=#e8d9bb>No dispuestos a admitir la derrota, ponen todo su corazón y fuerza en tomar el primer lugar.</color>",
  ui_story_5083_50830100_39_dialog_content = "<color=#e8d9bb>Más y más rápido, se esfuerzan hasta que—</color>",
  ui_story_5083_50830100_40_dialog_content = "<size=45>¡¡¡Hraaaaahhhh!!!</size>",
  ui_story_5083_50830100_41_dialog_content = "<color=#e8d9bb>Usando lo último de su energía, los dos saltan a través de la línea de meta y caen de bruces.</color>",
  ui_story_5083_50830100_42_dialog_content = "*uf... uf...* ¿B-Bueno? ¿Tú estás convencido ya?",
  ui_story_5083_50830100_43_dialog_content = "Incluso después de darte una ventaja, aún te alcancé.",
  ui_story_5083_50830100_44_dialog_content = "Hmph... Solo estaba conservando mi energía antes... Además, en realidad no ganaste, ¿verdad?",
  ui_story_5083_50830100_45_dialog_content = "<color=#e8d9bb>Mientras el resto de los soldados cruzan la línea de meta uno por uno, el silbato suena de nuevo—</color>",
  ui_story_5083_50830100_46_dialog_content = "El entrenamiento de hoy ha terminado, ¿por qué todavía están ustedes holgazaneando? ¡Por lo general, a estas horas ya están llenándose la cara en el comedor!",
  ui_story_5083_50830100_47_dialog_content = "¿Qué pasa? No puedes levantarte, ¿verdad?",
  ui_story_5083_50830100_48_dialog_content = "Tú deseas. ¡Vamos!",
  ui_story_5083_50830100_49_dialog_content = "Me pregunto qué hay de almuerzo hoy...",
  ui_story_5083_50830100_50_dialog_content = "¡Cualquier cosa menos otra barra de energía en mi avena! Ya he tenido suficiente de eso.",
  ui_story_5083_50830100_51_dialog_content = "Mira, Barton... Revisa tu 9 en punto.",
  ui_story_5083_50830100_52_dialog_content = "El comedor está lleno hoy... No, espera, ¿qué está pasando allí?",
  ui_story_5083_50830100_53_dialog_content = "¡Teniente Reinhardt! ¡Eres tan fuerte! ¿Cómo puedo entrenar para ser tan duro como tú?",
  ui_story_5083_50830100_54_dialog_content = "Entrena duro, supongo.",
  ui_story_5083_50830100_55_dialog_content = "¿Está bien si entreno contigo la próxima vez, teniente?",
  ui_story_5083_50830100_56_dialog_content = "Seguro, siempre y cuando puedas seguir el ritmo. Mi entrenamiento puede ser un poco duro a veces.",
  ui_story_5083_50830100_57_dialog_content = "¿Podrías mirar hacia aquí, Teniente? Sonríe a la cámara—",
  ui_story_5083_50830100_58_dialog_content = "¡Jajaja, queso!",
  ui_story_5083_50830100_59_dialog_content = "¿De qué se trata esto?",
  ui_story_5083_50830100_60_dialog_content = "Escucho que se graduó dos años antes, igual que tú. Aparentemente tenemos otro <color=#FFB400>súper cadete</color> entre nosotros.",
  ui_story_5083_50830100_61_dialog_content = "Pero a diferencia de ti, ella siempre está rodeada de una multitud. Quizás significa que tu personalidad podría necesitar algo de trabajo, ¿eh, Barton?",
  ui_story_5083_50830100_62_dialog_content = "... Aún así, es difícil imaginar que alguien como ella esté al mismo nivel que tú.",
  ui_story_5083_50830100_63_dialog_content = "Un oponente digno...",
  ui_story_5083_50830100_64_dialog_content = "¿Oh? Alguien interesante acaba de aparecer...",
  ui_story_5083_50830100_65_dialog_content = "¿Lo siento?",
  ui_story_5083_50830100_66_dialog_content = "No es nada. Ahora, ¿podrías hacer un lado por favor? Tengo bastante hambre.",
  ui_story_5083_50830100_67_dialog_content = "P-Por favor, déjame sentarme contigo—",
  ui_story_5083_50830100_68_dialog_content = "Evidentemente, solo es una nueva recluta sin logros reales de los que hablar. Por lo que he oído, solo recibe este tipo de atención porque el comité la está apoyando.",
  ui_story_5083_50830100_69_dialog_content = "Humph, solo otra pieza de exhibición para los de arriba. Ella no es rival para ti... ¡Y mucho menos para mí!",
  ui_story_5083_50830100_70_dialog_content = "Esa luz...",
  ui_story_5083_50830100_71_dialog_content = "¿Qué?",
  ui_story_5083_50830100_72_dialog_content = "Interesante... Ella emite una luz innegable, una que me dificulta apartar la mirada.",
  ui_story_5083_50830100_73_dialog_content = "Algo me dice que uno de nosotros va a ser el Gran Mariscal en el futuro.",
  ui_story_5083_50830100_74_dialog_content = "Se necesita mucho más para decidir sobre un nuevo Gran Mariscal... Espera, no me digas que también estás cegado por la luz de ese farsante?",
  ui_story_5083_50830100_75_dialog_content = "... ¡Oh, no! ¡Estos idiotas van a comer todo lo bueno si no entramos allí ahora mismo!",
  ui_story_5083_50830100_76_dialog_content = "¡Oye, espérame!",
  ui_story_5083_50830100_77_dialog_content = "Tuvimos que luchar con uñas y dientes por un par de latas de fruta. Nuestras comidas eran a veces incluso más aterradoras que nuestras sesiones de entrenamiento.",
  ui_story_5083_50830100_78_dialog_content = "Quiero uno de manzana. ¿Y tú?",
  ui_story_5083_50830100_79_dialog_content = "No me importa, solo dame lo que quede... ¡Oye!",
  ui_story_5083_50830100_80_dialog_content = "¡Ups!",
  ui_story_5083_50830100_81_dialog_content = "Mira, ¡es la chica que te aplastó en la última competencia! Escuché que ya se convirtió en Oficial de Tecnología.",
  ui_story_5083_50830100_82_dialog_content = "Nadie pidió una introducción, ¡ahora devuélveme esa lata!",
  ui_story_5083_50830100_83_dialog_content = "¡Oh sí, tú eres ese tipo... Uh... ¡Ah, lo que sea! ¡Buen juego, compañero soldado!",
  ui_story_5083_50830100_84_dialog_content = "¡Es Barton! Ni siquiera intentaste recordar mi nombre, ¿verdad?!",
  ui_story_5083_50830100_85_dialog_content = "Lo siento, es solo que te eliminé tan fácilmente, junto con un montón de otras personas.",
  ui_story_5083_50830100_86_dialog_content = "Tch... Decidiremos al verdadero ganador la próxima vez, Gronru! ¡Marca mis palabras!",
  ui_story_5083_50830100_87_dialog_content = "¡Solo espera... Ganaré todo de vuelta y más!",
  ui_story_5083_50830100_88_dialog_content = "No creo que haya visto nunca a un soldado lavar platos con tanta furia, Barton. ¡Debo decir que estoy impresionado!",
  ui_story_5083_50830100_89_dialog_content = "... ¡C-Comandante!",
  ui_story_5083_50830100_90_dialog_content = "El sol debe haber salido sobre la ciudad subterránea esta mañana. Normalmente solo enjuagas los platos antes de dejarlos a un lado, pero ahora los estás lavando como si tu vida dependiera de ello.",
  ui_story_5083_50830100_91_dialog_content = "Dime, ¿te golpeaste la cabeza o algo así?",
  ui_story_5083_50830100_92_dialog_content = "¡En absoluto, señor!",
  ui_story_5083_50830100_93_dialog_content = "Entonces dime qué está pasando por ello ahora mismo.",
  ui_story_5083_50830100_94_dialog_content = "No lo sé, señor. ¡Creo que necesito un día libre para resolver las cosas!",
  ui_story_5083_50830100_95_dialog_content = "¿Problemas para equilibrar el trabajo y el descanso? ¿O tal vez esa batalla tuvo demasiado impacto en ti? ¿Todavía sientes miedo, verdad?",
  ui_story_5083_50830100_96_dialog_content = "¡No, señor. Eso no es!",
  ui_story_5083_50830100_97_dialog_content = "Entonces, contrólate, soldado! Pero de nuevo, eres mucho más productivo así—",
  ui_story_5083_50830100_98_dialog_content = "¡Wow!",
  ui_story_5083_50830100_99_dialog_content = "¡Pero todavía eres débil y lleno de aperturas! ¿Realmente crees que puedes ser la estrella brillante de la 2ª Legión?",
  ui_story_5083_50830100_100_dialog_content = "¡Señor, no esperaba un ataque furtivo de alguien en quien confío!",
  ui_story_5083_50830100_101_dialog_content = "Te enseñé a mantener siempre la guardia alta y tus armas listas. Si hubieras hecho como te instruí, nunca habría podido sorprenderte tan fácilmente.",
  ui_story_5083_50830100_102_dialog_content = "No pareces convencido, ¡pero cualquier estrategia que conduzca a la victoria es correcta! No todos los problemas requieren un enfoque directo, y en la guerra, los resultados son lo único que importa.",
  ui_story_5083_50830100_103_dialog_content = "Parece que todavía necesitas algo de templado antes de que puedas ser utilizado en la batalla.",
  ui_story_5083_50830100_104_dialog_content = "¡Regresa al campo de entrenamiento y dame veinte vueltas más a tu velocidad habitual!",
  ui_story_5083_50830100_105_dialog_content = "... ¡Sí, señor!",
  ui_story_5083_50830100_106_dialog_content = "Terriblemente silencioso aquí, ¿no es así? ¿Cómo se supone que debo saber si realmente estás corriendo, soldado?! ¡Déjame oírte cantar en voz alta!",
  ui_story_5083_50830100_107_dialog_content = "¡Sí señor!",
  ui_story_5083_50830100_108_dialog_content = "\"I don't know what I've been told!\"",
  ui_story_5083_50830100_109_dialog_content = "¡Más alto!",
  ui_story_5083_50830100_110_dialog_content = "<size=45>\"¡Matar a los Eclipsites nunca pasa de moda!\"</size>",
  ui_story_5083_50830100_111_dialog_content = "¿Qué demonios... está haciendo Barton entrenamiento extra por su cuenta?",
  ui_story_5083_50830100_112_dialog_content = "¡No te vas a adelantar a mí de esa manera!",
  ui_story_5083_50830100_113_dialog_content = "¡Oye Barton! ¡Te alcancé de nuevo!",
  ui_story_5083_50830100_114_dialog_content = "No es una carrera, idiota.",
  ui_story_5083_50830100_115_dialog_content = "¡Es ahora que estoy aquí, y no vas a tomar el primer lugar en mi reloj!",
  ui_story_5083_50830100_116_dialog_content = "¡Argh—Regresa aquí, idiota!",
  ui_story_5083_50830100_117_dialog_content = "¡Eres el idiota!",
  ui_story_5083_50830100_118_dialog_content = "Jajajaja—",
  ui_story_5083_50830100_119_dialog_content = "Teniente Reinhardt?",
  ui_story_5083_50830100_120_dialog_content = "Esos dos... son interesantes.",
  ui_story_5083_50830200_1_dialog_content = "<color=#e8d9bb>A shrill whistle pierces the air.</color>",
  ui_story_5083_50830200_2_dialog_content = "¡Vístete y coge tu equipo!",
  ui_story_5083_50830200_3_dialog_content = "¡Al doble, gruñidos!",
  ui_story_5083_50830200_4_dialog_content = "Aaaaaahhh—",
  ui_story_5083_50830200_5_dialog_content = "¿Hnng...?",
  ui_story_5083_50830200_6_dialog_content = "¡Tres dos uno!",
  ui_story_5083_50830200_7_dialog_content = "<color=#e8d9bb>Un cubo de agua helada empapa a Barton, enfriándolo hasta los huesos y despertándolo de golpe.</color>",
  ui_story_5083_50830200_8_dialog_content = "<size=45>¡¡¡Aaaahhhh!!!</size>",
  ui_story_5083_50830200_9_dialog_content = "¡Vamos, vagos inútiles! ¡Sin dolor, no hay ganancia!",
  ui_story_5083_50830200_10_dialog_content = "Si no puedes despertarte y estar listo para el combate en menos de cinco segundos, ¿cómo esperas sobrevivir en el frente de batalla?",
  ui_story_5083_50830200_11_dialog_content = "¡Necesitas ser tan rápido y letal como una bala! Tienes diez segundos para llegar al campo de entrenamiento; ¡doble entrenamiento para cualquiera que llegue tarde!",
  ui_story_5083_50830200_12_dialog_content = "Y Barton, tú tienes que llevar este cubo en tu cabeza!",
  ui_story_5083_50830200_13_dialog_content = "Si no has alcanzado para cuando Dogg llegue a su segunda vuelta, te daré una vuelta extra por cada segundo que tardes!",
  ui_story_5083_50830200_14_dialog_content = "Mierda, estoy frío y empapado... ¡No puedo ponerme el cinturón! ¿¡Por qué tiene que ser yo?!",
  ui_story_5083_50830200_15_dialog_content = "¡Bien hecho! Si me hubieras escuchado, permanecido vigilante y siempre hubieras mantenido tus armas listas, ¡no estarías en tal lío!",
  ui_story_5083_50830200_16_dialog_content = "¿Crees que los Eclipsites van a esperarte a que te duches y disfrutes de un buen desayuno? Pueden atacar desde cualquier lugar en cualquier momento, ¡así que siempre debemos estar alerta!",
  ui_story_5083_50830200_17_dialog_content = "¿Cómo se supone que debo protegerme del agua mientras duermo?!",
  ui_story_5083_50830200_18_dialog_content = "¡Ese es tu problema, no el mío! Si no puedes mantenerte seco, puedes olvidarte de dar ejemplo a alguien!",
  ui_story_5083_50830200_19_dialog_content = "Esto es completamente irrazonable... Estaré bien mientras tenga un arma—",
  ui_story_5083_50830200_20_dialog_content = "Las armas no deberían ser lo primero que buscas, ¡idiota! ¡Ahora deja de manosear tu cinturón y ponte en marcha!",
  ui_story_5083_50830200_21_dialog_content = "¡Dogg también corre lo más rápido que puede! ¡Ni siquiera está intentando ayudarme!",
  ui_story_5083_50830200_22_dialog_content = "¡Je! Ahora muéstrame cómo planeas alcanzarlos.",
  ui_story_5083_50830200_23_dialog_content = "¡No me estoy rindiendo! <size=45>¡Mira esto!</size>",
  ui_story_5083_50830200_24_dialog_content = "<color=#e8d9bb>Barton ruge mientras lanza el cubo a un lado y rasga sus pantalones en shorts, luego corre desesperadamente hacia el resto de su grupo.</color>",
  ui_story_5083_50830200_25_dialog_content = "Incluso Barton tiene comienzos lentos a veces, ¿eh? Eso no es típico de él en absoluto...",
  ui_story_5083_50830200_26_dialog_content = "<size=45>¡Voy a por ti, Perrito!!!</size>",
  ui_story_5083_50830200_27_dialog_content = "Aquí estás, ¿qué diablos pasa con esa mirada?!",
  ui_story_5083_50830200_28_dialog_content = "Tu ropa está toda retorcida y desgarrada... ¿Qué eres, un payaso?! ¡Deja de intentar deshonrar a la 2da legión!",
  ui_story_5083_50830200_29_dialog_content = "¡Cállate! Mis pantalones solo me impedían alcanzarte, ¿cuál es tu excusa para dejarme?!",
  ui_story_5083_50830200_30_dialog_content = "¡Te ves tan ridículo que tuve que reducir la velocidad y regañarte!",
  ui_story_5083_50830200_31_dialog_content = "¡Jah! Claramente estabas asustado justo ahora—",
  ui_story_5083_50830200_32_dialog_content = "<color=#e8d9bb>De repente, una persona pasa corriendo por delante de los dos, poniendo fin a sus mezquinas disputas.</color>",
  ui_story_5083_50830200_33_dialog_content = "Arriba, dos, tres, cuatro...",
  ui_story_5083_50830200_34_dialog_content = "...",
  ui_story_5083_50830200_35_dialog_content = "<color=#e8d9bb>Quedando mudos, Barton y Dogg hacen todo lo posible para seguir el ritmo de su más reciente desafiante.</color>",
  ui_story_5083_50830200_36_dialog_content = "Hup, two, three, four...",
  ui_story_5083_50830200_37_dialog_content = "<color=#e8d9bb>Más y más rápido, los tres van... Con el resto de los soldados observándolos atentamente, terminan múltiples vueltas a un ritmo vertiginoso, y corren directamente más allá de la línea de meta.</color>",
  ui_story_5083_50830200_38_dialog_content = "No perderé—",
  ui_story_5083_50830200_39_dialog_content = "<color=#e8d9bb>Los tres cruzan la línea de meta al mismo tiempo. Completamente exhaustos, Barton y Dogg se detienen gradualmente. Sin embargo—</color>",
  ui_story_5083_50830200_40_dialog_content = "Hup, two, three, four...",
  ui_story_5083_50830200_41_dialog_content = "<color=#e8d9bb>Reinhardt continúa corriendo, aunque a un ritmo un poco más lento.</color>",
  ui_story_5083_50830200_42_dialog_content = "De ninguna manera...",
  ui_story_5083_50830200_43_dialog_content = "Ella está llevándolo demasiado lejos.",
  ui_story_5083_50830200_44_dialog_content = "No podemos dejar que nos provoque así. ¿Todavía puedes correr?",
  ui_story_5083_50830200_45_dialog_content = "¡Por supuesto que puedo! Vamos-",
  ui_story_5083_50830200_46_dialog_content = "<color=#e8d9bb>El silbato suena, y cada soldado se agrupa alrededor del comandante.</color>",
  ui_story_5083_50830200_47_dialog_content = "Tch, vamos a unirnos a los demás.",
  ui_story_5083_50830200_48_dialog_content = "Ella está con la 1ra legión, ¿verdad? Tiene bastante valor, interrumpiendo el entrenamiento de la 2da legión y burlándose de nosotros así...",
  ui_story_5083_50830200_49_dialog_content = "Lo que sea. ¿Cuál es el punto de quedarnos si ni siquiera podemos seguir el ritmo del novato más reciente de la 1ra Legión?",
  ui_story_5083_50830200_50_dialog_content = "No—",
  ui_story_5083_50830200_51_dialog_content = "Si no puedes vencerme, ¿qué te hace pensar que alguna vez alcanzarás a Reinhardt?",
  ui_story_5083_50830200_52_dialog_content = "No tú otra vez... Hmph, no seas tan arrogante. Solo tengo que seguir creciendo y volviéndome más fuerte.",
  ui_story_5083_50830200_53_dialog_content = "¿Oh? ¿Entonces no estás negando que te vencí?",
  ui_story_5083_50830200_54_dialog_content = "Así es. No tiene sentido negarlo cuando claramente perdí—",
  ui_story_5083_50830200_55_dialog_content = "Pero la verdadera pregunta es... ¿Por qué estás pasando el rato en la sombra durante el entrenamiento?!",
  ui_story_5083_50830200_56_dialog_content = "¡Quiero que sepas que como Oficial de Tecnología, estoy haciendo mucho trabajo serio ahora mismo!",
  ui_story_5083_50830200_57_dialog_content = "Trabajo serio, mi pie... ¿Y qué pasa con ese artilugio?",
  ui_story_5083_50830200_58_dialog_content = "Deja de hacer tonterías por aquí, Barton. Se supone que debemos agruparnos con los demás.",
  ui_story_5083_50830200_59_dialog_content = "No te preocupes, ese viejo puede esperar unos segundos más—",
  ui_story_5083_50830200_60_dialog_content = "¡No subestimes mi última invención! Tiene el potencial de cambiar la vida de cada soldado en Illumina—",
  ui_story_5083_50830200_61_dialog_content = "¡Presentamos el dron asistente inteligente de próxima generación! Una vez que estos entren en producción, serán la retaguardia óptima de cada soldado.",
  ui_story_5083_50830200_62_dialog_content = "¡Vaya! ¿Esto significa que te has vuelto aún más fuerte desde la última Copa del Emperador?",
  ui_story_5083_50830200_63_dialog_content = "¡Ahora estás empezando a entenderlo! ¿Ves? ¡No tienes idea de cuánto tiempo pasé en este diseño!",
  ui_story_5083_50830200_64_dialog_content = "Barton!",
  ui_story_5083_50830200_65_dialog_content = "¡¿Qué?!",
  ui_story_5083_50830200_66_dialog_content = "¡Barton! ¡Dogg! ¿Qué creen que están haciendo, holgazanes?!",
  ui_story_5083_50830200_67_dialog_content = "¡Cámbiate a tu uniforme y arrastra tus lamentables traseros a la Torre Central! ¡Vas a estar bajo su luz el resto del día, sin excepciones!!!",
  ui_story_5083_50830200_68_dialog_content = "¡¿Q-Qué?!?",
  ui_story_5083_50830200_69_dialog_content = "<color=#e8d9bb>La Torre Central. Este bullicioso y bien iluminado centro de transporte sirve como el corazón de la ciudad de Gannon—</color>",
  ui_story_5083_50830200_70_dialog_content = "<color=#e8d9bb>También es un lugar muy conspicuo para castigar a los soldados más rebeldes de Illumina.</color>",
  ui_story_5083_50830200_71_dialog_content = "...",
  ui_story_5083_50830200_72_dialog_content = "...",
  ui_story_5083_50830200_73_dialog_content = "... Lo siento.",
  ui_story_5083_50830200_74_dialog_content = "¿Ah?",
  ui_story_5083_50830200_75_dialog_content = "Soy la razón por la que tú también conseguiste...",
  ui_story_5083_50830200_76_dialog_content = "Has estado actuando muy extraño los últimos días, Barton.",
  ui_story_5083_50830200_77_dialog_content = "¿Es por esa batalla?",
  ui_story_5083_50830200_78_dialog_content = "Te dije que no pensaras demasiado en las cosas, hombre. No eras completamente culpable de eso.",
  ui_story_5083_50830200_79_dialog_content = "Las cosas simplemente no salieron a tu favor, eso es todo... Así que deja de enfurruñarte ya. De lo contrario, no se sentirá bien una vez que finalmente te venza.",
  ui_story_5083_50830200_80_dialog_content = "Después de todo... El Comandante Pango una vez dijo que eras el más prometedor de sus nuevos reclutas.",
  ui_story_5083_50830200_81_dialog_content = "¿Eh? ¿Realmente me felicitó?",
  ui_story_5083_50830200_82_dialog_content = "Realmente eres un idiota a veces—",
  ui_story_5083_50830200_83_dialog_content = "Gracias, Dogg.",
  ui_story_5083_50830200_84_dialog_content = "¡¿?!",
  ui_story_5083_50830200_85_dialog_content = "Casi olvido, pero no tuve la oportunidad de agradecerte adecuadamente por la última vez.",
  ui_story_5083_50830200_86_dialog_content = "Así que gracias por venir a rescatarme en el último momento.",
  ui_story_5083_50830200_87_dialog_content = "... Solo estaba siguiendo las órdenes del Comandante Pango, así que no lo menciones.",
  ui_story_5083_50830200_88_dialog_content = "Ugh... Hace tanto calor—",
  ui_story_5083_50830200_89_dialog_content = "<color=#e8d9bb>Bajo la luz abrasadora de la Torre Central, los dos soldados pasan todo el día sudando y parados en atención.</color>",
  ui_story_5083_50830200_90_dialog_content = "<color=#e8d9bb>Al final del día, su despiadado comandante finalmente aparece y los libera de su castigo—</color>",
  ui_story_5083_50830200_91_dialog_content = "Finalmente... Otro minuto y la luz de Illumina me habría cocinado hasta secarme.",
  ui_story_5083_50830200_92_dialog_content = "Estoy asombrado de que Dogg todavía tenga suficiente energía para ir al comedor... Supongo que iré a ducharme primero...",
  ui_story_5083_50830200_93_dialog_content = "Beep—Barton avistado.",
  ui_story_5083_50830200_94_dialog_content = "¿Eh? Es un dron... ¿Y sabe quién soy?",
  ui_story_5083_50830200_95_dialog_content = "Espera, ¿eres el dron de Gronru de más temprano hoy?",
  ui_story_5083_50830200_96_dialog_content = "No, Barton... Soy tu Navegante.",
  ui_story_5083_50830200_97_dialog_content = "¿Eh? ¿Qué se supone que significa eso?",
  ui_story_5083_50830200_98_dialog_content = "Estoy aquí para guiarte...",
  ui_story_5083_50830200_99_dialog_content = "Eso no aclara exactamente las cosas... Sabes, a pesar de tu apariencia anticuada, te encuentro bastante atractivo.",
  ui_story_5083_50830200_100_dialog_content = "... ¿Esto significa que los drones son ahora equipo estándar?",
  ui_story_5083_50830200_101_dialog_content = "¡No me importaría en absoluto! Bueno, si estás aquí para guiarme, ¡entonces dirige el camino!",
  ui_story_5083_50830200_102_dialog_content = "Entendido.",
  ui_story_5083_50830200_103_dialog_content = "Beep—Barton, yo...",
  ui_story_5083_50830200_104_dialog_content = "Te guiaré fuera de esto...",
  ui_story_5083_50830301_1_dialog_content = "Bip—Barton... Mis sensores indican que necesitas una ducha...",
  ui_story_5083_50830301_2_dialog_content = "Las duchas del dormitorio están actualmente llenas. Buscando opciones alternativas... He localizado una casa de baños públicos en el sector residencial. Ahora redirigiendo... Por favor, sígueme.",
  ui_story_5083_50830301_3_dialog_content = "¡Oye, no está mal en absoluto! ¡Eres mucho más inteligente que cualquier otro modelo que he visto!",
  ui_story_5083_50830301_4_dialog_content = "¿Quizás debería abrirte y echar un vistazo a lo que hay dentro?",
  ui_story_5083_50830301_5_dialog_content = "Bip—Bip—Por favor, no—",
  ui_story_5083_50830301_6_dialog_content = "Solo bromeando, pequeño. Desmantelar un modelo nunca antes visto como tú probablemente me metería en cantidades indescriptibles de problemas.",
  ui_story_5083_50830301_7_dialog_content = "Bip—Nuestro destino está a 300 metros de distancia. En la próxima intersección, por favor toma el ascensor hasta el segundo piso.",
  ui_story_5083_50830301_8_dialog_content = "Realmente eres útil, pequeño! La ciudad de Gannon puede ser realmente difícil de navegar a veces.",
  ui_story_5083_50830301_9_dialog_content = "¡Solo deseo que pudiéramos usarte en las otras Subciudades!",
  ui_story_5083_50830301_10_dialog_content = "Ubicación actual: Sector Residencial, Callejón 9, Piso Superior... Próxima ubicación: Monumento Central—",
  ui_story_5083_50830301_11_dialog_content = "Espera.",
  ui_story_5083_50830301_12_dialog_content = "Bip—Sí, Barton...?",
  ui_story_5083_50830301_13_dialog_content = "Ese memorial...",
  ui_story_5083_50830301_14_dialog_content = "Incluso desde aquí, todavía puedo verlo claramente.",
  ui_story_5083_50830301_15_dialog_content = "Me pregunto... ¿si ya se han añadido sus nombres?",
  ui_story_5083_50830301_16_dialog_content = "<color=#e8d9bb>Esa batalla, que tuvo lugar hace poco, fue la primera vez que Barton experimentó el combate en vivo.</color>",
  ui_story_5083_50830301_17_dialog_content = "<color=#e8d9bb>Fue un día oscuro y nublado. La lluvia caía como innumerables e interminables hilos desde el cielo.</color>",
  ui_story_5083_50830301_18_dialog_content = "¡Rápido! ¡Mueve esas bolsas de arena a nuestra línea más avanzada!",
  ui_story_5083_50830301_19_dialog_content = "¡La segunda trinchera en nuestro flanco derecho ha sido inundada con Eclipsites! ¡Envía soldados para despejarla de inmediato!",
  ui_story_5083_50830301_20_dialog_content = "¡No tenemos suficientes sacos de arena, señora!",
  ui_story_5083_50830301_21_dialog_content = "O nuestros soldados, para el caso... Ya no podemos asegurar todas nuestras posiciones.",
  ui_story_5083_50830301_22_dialog_content = "¿La gente ya terminó de evacuar?",
  ui_story_5083_50830301_23_dialog_content = "No, señora... El daño al núcleo de energía de Entrañas ha bloqueado la mayoría de nuestros sistemas de transporte, haciendo la evacuación mucho más lenta.",
  ui_story_5083_50830301_24_dialog_content = "¿Qué hacemos ahora?",
  ui_story_5083_50830301_25_dialog_content = "Encuentra lo que puedas para reforzar nuestras defensas de primera línea y divide el resto del trabajo entre nuestras fuerzas restantes. No hay otra elección.",
  ui_story_5083_50830301_26_dialog_content = "¿Dónde está el teniente Barton? No puedo tomar todas las decisiones aquí, así que lo dejaré evaluar la situación.",
  ui_story_5083_50830301_27_dialog_content = "Acaba de regresar de las líneas del frente y está descansando en la retaguardia.",
  ui_story_5083_50830301_28_dialog_content = "¡Exploradores! ¿Cuánto tiempo más hasta que esos monstruos lancen otro ataque?",
  ui_story_5083_50830301_29_dialog_content = "¡No mucho tiempo, señora! ¡Están reponiendo sus fuerzas mientras hablamos!",
  ui_story_5083_50830301_30_dialog_content = "¿Dónde está el Oficial de comunicaciones? ¿Hemos terminado de reparar la carretera ya? ¿Cuánto tiempo hasta que el Comandante Pango y sus soldados lleguen aquí?!",
  ui_story_5083_50830301_31_dialog_content = "Lo siento, señora, pero todo el equipo de comunicaciones se ha ido ahora.",
  ui_story_5083_50830301_32_dialog_content = "¿Cuáles son sus órdenes, señora?",
  ui_story_5083_50830301_33_dialog_content = "El Comandante Pango y sus fuerzas definitivamente vendrán. Solo tenemos que resistir hasta entonces.",
  ui_story_5083_50830301_34_dialog_content = "Seis de nuestras Subciudades están bajo ataque en este momento, y hay personas allá afuera que necesitan refuerzos más que nosotros.",
  ui_story_5083_50830301_35_dialog_content = "Si el comandante se queda atrapado en el frente...",
  ui_story_5083_50830301_36_dialog_content = "Entonces también debemos resistir por esas personas.",
  ui_story_5083_50830301_37_dialog_content = "¿Cómo podemos... Todavía tengo familia en casa...",
  ui_story_5083_50830301_38_dialog_content = "Lo siento... Pero no puedo prometerte nada ahora mismo.",
  ui_story_5083_50830301_39_dialog_content = "Nuestro deber es proteger este lugar con nuestras vidas. No podemos permitir que ningún Eclipsite nos pase.",
  ui_story_5083_50830301_40_dialog_content = "Nuestros camaradas de Illumina cuentan con nosotros para protegerlos...",
  ui_story_5083_50830301_41_dialog_content = "Si debemos morir, morimos con honor en el campo de batalla.",
  ui_story_5083_50830301_42_dialog_content = "Tengo miedo... Mi mamá me dio una bufanda completamente nueva antes de irme, pero ahora... Ni siquiera recuerdo cuándo se quemó así...",
  ui_story_5083_50830301_43_dialog_content = "...",
  ui_story_5083_50830301_44_dialog_content = "... Sé que está mal que haga esto, pero que alguien despierte al teniente Barton ahora mismo.",
  ui_story_5083_50830301_45_dialog_content = "Tal vez él sepa qué hacer.",
  ui_story_5083_50830301_46_dialog_content = "Teniente Barton—Teniente—",
  ui_story_5083_50830301_47_dialog_content = "¿Qué es eso? Siento como si acabara de quedarme dormido... Pero está bien. Descansa también; no se sabe cuándo volverán a atacar.",
  ui_story_5083_50830301_48_dialog_content = "¡Señor! Nuestro escuadrón de comunicaciones ha sido eliminado y no tenemos forma de comunicarnos con el resto de la Legión.",
  ui_story_5083_50830301_49_dialog_content = "El Comandante del Batallón y el Oficial de Disciplina... también se perdieron mientras cubrían nuestra última retirada.",
  ui_story_5083_50830301_50_dialog_content = "Entendido... Según la cadena de mando, debería estar a cargo ahora, ¿no?",
  ui_story_5083_50830301_51_dialog_content = "Entrégame el mapa.",
  ui_story_5083_50830301_52_dialog_content = "Nuestros exploradores informan que los Eclipsites se están concentrando en las tierras altas del norte. No tenemos forma de atacarlos a distancia en este momento.",
  ui_story_5083_50830301_53_dialog_content = "La mayoría de las funciones de la Subciudad fueron deshabilitadas después de la primera ola de ataques.",
  ui_story_5083_50830301_54_dialog_content = "En este momento, no tenemos forma de saber si o cuándo llegará el comandante con refuerzos.",
  ui_story_5083_50830301_55_dialog_content = "Además... Algunos de los soldados creen que deberíamos abandonar esta posición y evacuar junto con los civiles.",
  ui_story_5083_50830301_56_dialog_content = "¡Pero eso significaría abandonar toda Entrañas, señor!",
  ui_story_5083_50830301_57_dialog_content = "¿Cuántas personas nos quedan?",
  ui_story_5083_50830301_58_dialog_content = "Menos de trescientos... Simplemente no tenemos los números para defender esta Subciudad ya.",
  ui_story_5083_50830301_59_dialog_content = "... Esto es mucho más difícil que cualquier simulación militar, eso es seguro.",
  ui_story_5083_50830301_60_dialog_content = "No puedo creer que ese viejo pensara que podríamos defender una ciudad entera por nosotros mismos... Si no hubiéramos arriesgado nuestras vidas para abrirnos camino, probablemente habríamos muerto allí.",
  ui_story_5083_50830301_61_dialog_content = "Parece que solo nos queda una opción...",
  ui_story_5083_50830301_62_dialog_content = "¡Teniente Barton! <size=45>¡Ha llegado un mensajero!</size>",
  ui_story_5083_50830301_63_dialog_content = "Adelante. Por favor dime si tienes buenas noticias para nosotros.",
  ui_story_5083_50830301_64_dialog_content = "¡Sí, señor! La ofensiva sorpresa del Comandante Pango fue un gran éxito, ¡y se han salvado tres subciudades! Están en camino a esta posición mientras hablamos!",
  ui_story_5083_50830301_65_dialog_content = "¡Tus órdenes son resistir hasta que lleguen!",
  ui_story_5083_50830301_66_dialog_content = "¿Pensé que dijiste que eran buenas noticias? ¿Has visto el estado en el que estamos ahora mismo?!",
  ui_story_5083_50830301_67_dialog_content = "Lo siento, señor... El Comandante Pango sabe lo difícil que debe ser, pero tres subciudades no se habrían salvado si no fuera por la valentía y los sacrificios de sus soldados.",
  ui_story_5083_50830301_68_dialog_content = "Así que por favor confía en él. La ayuda llegará pronto, señor.",
  ui_story_5083_50830301_69_dialog_content = "Los Eclipsites están en movimiento, Teniente Barton. ¿Cuáles son tus órdenes?",
  ui_story_5083_50830301_70_dialog_content = "Si nos retiramos a la Subciudad antes de que se complete la evacuación, no hay garantía de que los Eclipsites simplemente no nos rodeen...",
  ui_story_5083_50830301_71_dialog_content = "Pero esta posición ya está en ruinas... No será fácil evitar que sea invadida—",
  ui_story_5083_50830301_72_dialog_content = "Así que entramos a la carga.",
  ui_story_5083_50830301_73_dialog_content = "I'm sorry?",
  ui_story_5083_50830301_74_dialog_content = "Como oficial al mando, ¡ordeno a todos los soldados que se preparen para cargar contra el enemigo!",
  ui_story_5083_50830301_75_dialog_content = "¡No podemos dejar que esos monstruos se salgan con la suya!",
  ui_story_5083_50830301_76_dialog_content = "¡Piensa en la gente que cuenta con nosotros! Piensa en tus padres en Gannon City... ¿Estás dispuesto a rendirte y morir como un cobarde en este lugar?",
  ui_story_5083_50830301_77_dialog_content = "¡P-Por favor, cálmate, Teniente! Las órdenes del Comandante Pango eran mantener esta posición!",
  ui_story_5083_50830301_78_dialog_content = "¿Cómo puedes decir eso? Hemos estado luchando sin parar durante diez días seguidos. ¿Estás sugiriendo seriamente que nos atrincheremos aquí y esperemos lo inevitable?",
  ui_story_5083_50830301_79_dialog_content = "¿No puedes oler el miedo en sus corazones? Porque yo sí, ¡y me niego a dejarlos morir aquí!",
  ui_story_5083_50830301_80_dialog_content = "¡Los soldados de la 2da Legión nunca se echan atrás y nunca se rinden!",
  ui_story_5083_50830301_81_dialog_content = "¡Si todos vamos a morir, al menos saldremos en un estallido de gloria!",
  ui_story_5083_50830301_82_dialog_content = "Barton... Tú...",
  ui_story_5083_50830301_83_dialog_content = "¡Estamos cargando directamente hacia el enemigo, y no pararemos hasta obligarlos a retroceder!",
  ui_story_5083_50830301_84_dialog_content = "<size=45>Todas las fuerzas, agarren sus armas y acerquen su resolución—</size>",
  ui_story_5083_50830301_85_dialog_content = "<size=45>¡¡¡CARGAAA!!!</size>",
  ui_story_5083_50830302_1_dialog_content = "<color=#e8d9bb>El llamado a las armas de Barton resuena en la desolación de la luz del amanecer. Mientras las llamas amenazan con engullir la Subciudad, se desarrolla una lucha brutal.</color>",
  ui_story_5083_50830302_2_dialog_content = "¡Sigue disparando! ¡No te rindas!",
  ui_story_5083_50830302_3_dialog_content = "¡Los sorprendimos desprevenidos! Ahora es nuestra oportunidad—",
  ui_story_5083_50830302_4_dialog_content = "¡Rugido!",
  ui_story_5083_50830302_5_dialog_content = "¡No pares! Nuestro objetivo es recuperar el terreno elevado y dar a nuestras fuerzas la oportunidad de transportar nuestra artillería pesada allí arriba!",
  ui_story_5083_50830302_6_dialog_content = "<color=#e8d9bb>El clarín continúa señalando su avance, y los valientes soldados de Illumina presionan más adentro de las filas enemigas.</color>",
  ui_story_5083_50830302_7_dialog_content = "Graaaaah!",
  ui_story_5083_50830302_8_dialog_content = "¡Sigue adelante!",
  ui_story_5083_50830302_9_dialog_content = "<color=#e8d9bb>Siempre que el soldado que sostiene el clarín cae, otro toma rápidamente su lugar.</color>",
  ui_story_5083_50830302_10_dialog_content = "¿Dónde están los artilleros? ¡No te quedes atrás todavía!",
  ui_story_5083_50830302_11_dialog_content = "<color=#e8d9bb>En este campo de batalla que es una picadora de carne, la cara de Barton ya está cubierta de sangre y sudor. Aun así, sigue liderando la carga con la bandera de Illumina en alto.</color>",
  ui_story_5083_50830302_12_dialog_content = "Te cubriré, ¡ahora ve!",
  ui_story_5083_50830302_13_dialog_content = "<color=#e8d9bb>Con una bandera en una mano y el arma de fuego de su camarada en la otra, abre fuego contra los Eclipsites mientras se derraman por la pendiente—</color>",
  ui_story_5083_50830302_14_dialog_content = "¡¡¡No me vas a quitar esto!!!",
  ui_story_5083_50830302_15_dialog_content = "<color=#e8d9bb>Con un solo empuje poderoso, Barton atraviesa al Eclipsite con su estandarte y lo planta firmemente en la cima de la colina. Pronto, la luz de Illumina brilla en los ojos de cada soldado presente—</color>",
  ui_story_5083_50830302_16_dialog_content = "¡Vengan a buscarme, monstruos sucios!",
  ui_story_5083_50830302_17_dialog_content = "Barton—!",
  ui_story_5083_50830302_18_dialog_content = "Esa voz... ¿Dogg?!",
  ui_story_5083_50830302_19_dialog_content = "<color=#e8d9bb>Al amanecer, Barton finalmente ve el campo de batalla a través de su visión manchada de sangre. A lo lejos, aparece un batallón entero de soldados.</color>",
  ui_story_5083_50830302_20_dialog_content = "¡Idiota... No puedo creer que corriste directamente al vientre de la bestia!",
  ui_story_5083_50830302_21_dialog_content = "Supongo que ya no hay vuelta atrás... ¡Todas las fuerzas, prepárense para cargar contra el enemigo!",
  ui_story_5083_50830302_22_dialog_content = "¡Protege el terreno elevado a toda costa, para que el Teniente Barton pueda continuar disparando para suprimir al enemigo!",
  ui_story_5083_50830302_23_dialog_content = "¡Sí señor!",
  ui_story_5083_50830302_24_dialog_content = "¡Jajaja! Mi respaldo finalmente está aquí, Eclipsites—¡ahora muere!",
  ui_story_5083_50830302_25_dialog_content = "<color=#e8d9bb>La corneta señala carga tras carga sangrienta. Los valientes soldados de Illumina continúan su asalto implacable, y pronto, la marea oscura retrocede bajo la luz del amanecer.</color>",
  ui_story_5083_50830302_26_dialog_content = "<color=#e8d9bb>Mientras el sol brilla sobre el campo de batalla, se ven los cuerpos de innumerables soldados formando una barricada alrededor de la Subciudad. Incluso en la muerte, continúan defendiendo su hogar.</color>",
  ui_story_5083_50830302_27_dialog_content = "Oye Barton... ¿Todavía estás vivo?",
  ui_story_5083_50830302_28_dialog_content = "Urgh... Creo que sí... No puedo ver a través de toda esta sangre en mi cara, pero no parece que me falten partes importantes.",
  ui_story_5083_50830302_29_dialog_content = "¡Idiota...!",
  ui_story_5083_50830302_30_dialog_content = "Estabas a punto de morir en este lugar, ¿lo sabías? Qué pesadilla...",
  ui_story_5083_50830302_31_dialog_content = "¡Shh! ¿Oyes eso?",
  ui_story_5083_50830302_32_dialog_content = "<color=#e8d9bb>A medida que el sol se vuelve más brillante, un poderoso cuerno suena sin parar—</color>",
  ui_story_5083_50830302_33_dialog_content = "Es nuestra fuerza principal... Finalmente está aquí el anciano...",
  ui_story_5083_50830302_34_dialog_content = "En serio... Aparecieron cuando dijeron que lo harían... Maldita sea...",
  ui_story_5083_50830302_35_dialog_content = "¡Dogg! Barton!",
  ui_story_5083_50830302_36_dialog_content = "... ¿Dónde diablos están esos dos tontos?!",
  ui_story_5083_50830302_37_dialog_content = "<color=#e8d9bb>Al ver las pilas de cuerpos esparcidos por el campo de batalla, el comandante de sangre de hierro de la 2ª Legión murmura con un tono tembloroso.</color>",
  ui_story_5083_50830302_38_dialog_content = "Todos esos niños... No...",
  ui_story_5083_50830302_39_dialog_content = "¡Dogg! ¡Barton! Tú... ¡Tú malditos tontos!!! No me digas...",
  ui_story_5083_50830302_40_dialog_content = "Tú...",
  ui_story_5083_50830302_41_dialog_content = "¡Idiotas, todavía están vivos!",
  ui_story_5083_50830302_42_dialog_content = "Comandante... Nuestra misión... está completa, señor.",
  ui_story_5083_50830302_43_dialog_content = "Lo siento anciano... No renunciamos a ninguna parte de la Subciudad... pero... algunas cosas podrían haberse golpeado durante la pelea...",
  ui_story_5083_50830302_44_dialog_content = "Así es... Al repeler a los Eclipsites, protegiste esta Subciudad e impediste que las otras dos fueran invadidas... Ganaste, chicos.",
  ui_story_5083_50830302_45_dialog_content = "Barton... ¿esta es tu primera vez liderando tropas y la proporción de bajas ya es casi de uno a diez?!",
  ui_story_5083_50830302_46_dialog_content = "<size=45>¡Cómo te atreves!!!</size> ¡Debería hacerte un consejo de guerra por desobedecer órdenes y jugar al héroe!!!",
  ui_story_5083_50830302_47_dialog_content = "Hacerte matar es una cosa, ¡pero casi logras que maten a Dogg también!",
  ui_story_5083_50830302_48_dialog_content = "Pero seguimos vivos, ¿verdad?",
  ui_story_5083_50830302_49_dialog_content = "¡Nada de esto habría sucedido si tan solo me hubieras escuchado!",
  ui_story_5083_50830302_50_dialog_content = "¡Registraré este incidente en el informe y consideraré tu primera vez al mando un fracaso total!",
  ui_story_5083_50830302_51_dialog_content = "¿¡Qué?! ¡Pero nos diste una misión imposible! Si no hubiéramos llevado la lucha a los Eclipsites, nos habrían superado hace mucho tiempo!",
  ui_story_5083_50830302_52_dialog_content = "¡Oye! ¡Vuelve aquí, anciano apestoso! ¡Exijo una mejor explicación que esa!!",
  ui_story_5083_50830302_53_dialog_content = "Maldita sea... No vio lo malo que estaba aquí, y aún me está dando problemas... ¡Casi nos quedamos atrapados en este agujero infernal!",
  ui_story_5083_50830302_54_dialog_content = "Dale un respiro, Barton. El comandante solo está preocupado por ti.",
  ui_story_5083_50830302_55_dialog_content = "Solo te está regañando porque casi mueres, eso es todo.",
  ui_story_5083_50830302_56_dialog_content = "Tan pronto como se dio cuenta de que nuestras comunicaciones estaban caídas, nos envió a mí y a mi equipo por delante para proporcionar refuerzos.",
  ui_story_5083_50830302_57_dialog_content = "...",
  ui_story_5083_50830302_58_dialog_content = "Ahora levántate. Es hora de que volvamos...",
  ui_story_5083_50830302_59_dialog_content = "¿Ganamos? ¡Ganamos! Realmente sobreviví...",
  ui_story_5083_50830302_60_dialog_content = "Pero el líder del pelotón y los demás...",
  ui_story_5083_50830302_61_dialog_content = "Casi todos ellos cayeron en la batalla...",
  ui_story_5083_50830302_62_dialog_content = "Un batallón entero de soldados... así como los refuerzos...",
  ui_story_5083_50830302_63_dialog_content = "... Cuando me levanté hace un momento, me di cuenta de que el comandante había estado buscando nuestros cuerpos todo el tiempo... ¿Es por eso que su voz temblaba antes?",
  ui_story_5083_50830302_64_dialog_content = "¿Tomé la decisión equivocada, Dogg?",
  ui_story_5083_50830302_65_dialog_content = "No sirve de nada preocuparse por eso ahora.",
  ui_story_5083_50830302_66_dialog_content = "Había más Eclipsites de los que nuestros exploradores informaron originalmente.",
  ui_story_5083_50830302_67_dialog_content = "Independientemente de lo que sucedió, lograste completar la misión.",
  ui_story_5083_50830302_68_dialog_content = "No solo defendiste esta Subciudad, también mataste a un gran número de Eclipsites.",
  ui_story_5083_50830302_69_dialog_content = "... Los valientes hombres y mujeres que lucharon a tu lado murieron honorablemente y sin arrepentimientos. Estoy seguro de ello.",
  ui_story_5083_50830302_70_dialog_content = "Si... Si no hubiera dado la orden de atacar...",
  ui_story_5083_50830302_71_dialog_content = "¿Habría más de ellos de pie ahora mismo?",
  ui_story_5083_50830302_72_dialog_content = "No lo pienses.",
  ui_story_5083_50830302_73_dialog_content = "Esta es la guerra, Barton. A diferencia de nuestras simulaciones militares, nada está garantizado aquí.",
  ui_story_5083_50830302_74_dialog_content = "Incluso los más grandes comandantes no tienen forma de saber si una batalla se desarrollará según sus órdenes.",
  ui_story_5083_50830302_75_dialog_content = "Los mapas y modelos nunca pueden reflejar cada parte de la batalla, o el espíritu valiente de los soldados de Illumina.",
  ui_story_5083_50830302_76_dialog_content = "Tu contraofensiva fue exitosa y saliste victorioso. Esos son los resultados de tu primera vez al mando.",
  ui_story_5083_50830302_77_dialog_content = "Victorioso, eh...",
  ui_story_5083_50830302_78_dialog_content = "En cuanto a dónde mejorar y cómo salvar aún más vidas la próxima vez... Eso es algo en lo que debes pensar mientras seguimos avanzando.",
  ui_story_5083_50830302_79_dialog_content = "Quizás tomes una decisión diferente la próxima vez. De cualquier manera, el resultado de esta batalla ya está decidido.",
  ui_story_5083_50830302_80_dialog_content = "Y como sobrevivientes, tenemos que cargar con todo. No solo lo bueno, sino también lo malo.",
  ui_story_5083_50830302_81_dialog_content = "Aceptando el resultado de la batalla, y compartiendo nuestra victoria con el resto...",
  ui_story_5083_50830302_82_dialog_content = "Eso es todo lo que podemos hacer como comandantes ahora mismo.",
  ui_story_5083_50830400_1_dialog_content = "Beep—Tú tienes un nuevo mensaje, Barton.",
  ui_story_5083_50830400_2_dialog_content = "El siguiente mensaje es del Comandante Pango de la 2ª Legión, y no refleja mis puntos de vista personales—",
  ui_story_5083_50830400_3_dialog_content = "¡Oye, punk! ¿Todavía estás holgazaneando en la cama, verdad?!",
  ui_story_5083_50830400_4_dialog_content = "¡Solo porque no sea día de entrenamiento no significa que puedas tomártelo con calma!",
  ui_story_5083_50830400_5_dialog_content = "¡Lleva tu lamentable trasero al sector residencial! ¡Tengo un trabajo solo para ti!",
  ui_story_5083_50830400_6_dialog_content = "Y ese trabajo es, uh... Ejem, asegurarnos de que nadie esté vendiendo suministros bajo la mesa allá afuera.",
  ui_story_5083_50830400_7_dialog_content = "¡Tienes un día para terminar la misión! No importa si lo logras o no, siempre y cuando pases todo el día en el sector residencial! ¡Y ni siquiera pienses en regresar temprano, entendido?! ¡Despedido!",
  ui_story_5083_50830400_8_dialog_content = "¡Dulce!",
  ui_story_5083_50830400_9_dialog_content = "Bip—¿Por qué estás tan feliz? El comandante estaba gritándote.",
  ui_story_5083_50830400_10_dialog_content = "Ja, tú no sabes eso, ¿verdad? Pasamos por el piso superior del sector residencial todo el tiempo, pero está prohibido pasar el rato allí.",
  ui_story_5083_50830400_11_dialog_content = "Siempre están construyendo nuevos edificios allí abajo, ¡así que siempre he querido ir a verlo por mí mismo!",
  ui_story_5083_50830400_12_dialog_content = "Bip—Por favor, deja de sacudirme...",
  ui_story_5083_50830400_13_dialog_content = "<size=45>¡Woo-hoo! ¡Hora de divertirse!!!</size>",
  ui_story_5083_50830400_14_dialog_content = "Te ves bastante elegante, Barton. ¿Escuché que te diriges al sector residencial hoy?",
  ui_story_5083_50830400_15_dialog_content = "¡Así es! ¿Alguien necesita algo del centro de distribución? Voy para allá, así que solo entrégame tus cupones y conseguiré tus cosas.",
  ui_story_5083_50830400_16_dialog_content = "¡H-Hey! Uno a la vez, o los vales se convertirán en un desastre. Además, ¡solo puedo llevar tanto!",
  ui_story_5083_50830400_17_dialog_content = "El comandante dijo que te dio una misión, pero parece que solo quiere darte un día libre.",
  ui_story_5083_50830400_18_dialog_content = "¿Es eso cierto? Supongo que sus habilidades sociales no son mucho mejores que las tuyas, ¿eh?",
  ui_story_5083_50830400_19_dialog_content = "... ¡Simplemente piérdete ya, idiota!",
  ui_story_5083_50830400_20_dialog_content = "¡Echa un vistazo! Es la nueva área de asignación que colocaron justo al lado del sector residencial!",
  ui_story_5083_50830400_21_dialog_content = "Bip—Debe haber una palabra mejor que plopped, Barton...",
  ui_story_5083_50830400_22_dialog_content = "No tengo idea de lo que estás hablando. Ahora indícame el lugar más cercano para divertirme; ¡Todavía tengo muchas compras por hacer!",
  ui_story_5083_50830400_23_dialog_content = "... ¿Qué pasa con tu misión?",
  ui_story_5083_50830400_24_dialog_content = "Ah, no te preocupes por eso. Incluso Dogg piensa que estoy aquí para un descanso, así que simplemente confiemos en él.",
  ui_story_5083_50830400_25_dialog_content = "El Comandante Pango prácticamente lo crió. No creo que nadie conozca mejor al anciano que él.",
  ui_story_5083_50830400_26_dialog_content = "¡Ahora, vamos a divertirnos! ¡Guía el camino!",
  ui_story_5083_50830400_27_dialog_content = "Bip—Sí, Barton... Descubrí un lugar conocido como el Arcade Oculto a 60 metros de distancia, en el callejón a nuestra derecha.",
  ui_story_5083_50830400_28_dialog_content = "Un salón de juegos, eh... ¿Realmente tienen ese tipo de cosas en el área de asignación? Todavía estamos en guerra, después de todo... Vamos a echar un vistazo.",
  ui_story_5083_50830400_29_dialog_content = "¿¿S-Seriamente?! Estos deben ser los videojuegos de los que oí en la academia—",
  ui_story_5083_50830400_30_dialog_content = "Bienvenido al Arcade Oculto. Aunque todavía estamos en guerra, espero sinceramente que encuentres algo de paz y disfrute aquí.",
  ui_story_5083_50830400_31_dialog_content = "Todos nuestros juegos fueron diseñados y desarrollados por el jefe de la sala de juegos. ¡Los nuevos clientes tienen derecho a una ronda de juego gratis!",
  ui_story_5083_50830400_32_dialog_content = "¡Si logras una puntuación alta en Naval King, puedes elegir un premio que corresponda a tu puntuación!",
  ui_story_5083_50830400_33_dialog_content = "Si fallas en tu intento, simplemente cambia tus vales por fichas y sigue jugando para obtener una puntuación aún más alta!",
  ui_story_5083_50830400_34_dialog_content = "¡Tu jefe me parece un verdadero ganador! Mira esto, ¡venceré todo el nivel de una vez!",
  ui_story_5083_50830400_35_dialog_content = "¡Juego terminado! Puntuación: 5.",
  ui_story_5083_50830400_36_dialog_content = "Lo siento señor, pero necesita una puntuación de 500 para una camiseta de Naval King o una puntuación de 1,000 para el juego en sí. ¿Le gustaría cambiar sus cupones por algunas fichas?",
  ui_story_5083_50830400_37_dialog_content = "¡Maldita sea, sí! Aquí tienes.",
  ui_story_5083_50830400_38_dialog_content = "¡Ahora mira esto—!",
  ui_story_5083_50830400_39_dialog_content = "¡Juego terminado! Puntaje: 40.",
  ui_story_5083_50830400_40_dialog_content = "Oye, ¿cuántos cupones cuesta comprar esa camiseta de Naval King?",
  ui_story_5083_50830400_41_dialog_content = "Jeje... Dado que has gastado lo suficiente para obtener el estatus VIP, ahora tienes el privilegio de comprarlo por un vale de 100 puntos. ¿Te gustaría comprarlo?",
  ui_story_5083_50830400_42_dialog_content = "Vaya Barton, no pensé que te gustaría tanto esa camiseta.",
  ui_story_5083_50830400_43_dialog_content = "¿Qu-Qué estás haciendo aquí?!",
  ui_story_5083_50830400_44_dialog_content = "Resulta que soy el desarrollador detrás de todos estos juegos. Bueno, yo y el negador.",
  ui_story_5083_50830400_45_dialog_content = "Apenas. Tú eres el que hizo todo el trabajo ya que realmente no me importan estas cosas.",
  ui_story_5083_50830400_46_dialog_content = "¡Por cierto, Denier es mi condiscípulo menor!",
  ui_story_5083_50830400_47_dialog_content = "He oído hablar de ti, Barton... No es una mala puntuación la que tienes ahí.",
  ui_story_5083_50830400_48_dialog_content = "Uh, hola... Escucha Gronru, tus máquinas de juego se tragaron un montón de mis vales.",
  ui_story_5083_50830400_49_dialog_content = "Se suponía que debía usar algunos de ellos para comprar cosas para mis compañeros de escuadrón, entonces, ¿podrías...?",
  ui_story_5083_50830400_50_dialog_content = "Jajaja, ¡no esperaba que fueras tan malo en los videojuegos! Aún así, estoy agradecido de que los hayas disfrutado tanto.",
  ui_story_5083_50830400_51_dialog_content = "¡Ahora sé que será un gran éxito con todos!",
  ui_story_5083_50830400_52_dialog_content = "Parece que probarlos aquí fue la decisión correcta después de todo. ¡Incluso recuperé algo del dinero que invertí en estos juegos!",
  ui_story_5083_50830400_53_dialog_content = "... Espera, ¿así que estás dirigiendo un negocio privado para obtener beneficios aquí?",
  ui_story_5083_50830400_54_dialog_content = "Quiero decir, sí ofrecemos pruebas gratuitas... Así que eso no debería ser un problema, ¿verdad?",
  ui_story_5083_50830400_55_dialog_content = "Suspiro, es un gran problema, Gronru. Cuando te arresten, intenta no arrastrarme contigo.",
  ui_story_5083_50830400_56_dialog_content = "¡Como si! ¡Les diré que me ayudaste a construir todas estas máquinas de juego!",
  ui_story_5083_50830400_57_dialog_content = "¿¡Qué?! ¡Solo ayudé porque me ordenaste hacerlo, Oficial de Tecnología!",
  ui_story_5083_50830400_58_dialog_content = "Sí, pero lo disfrutaste, ¿no es así?",
  ui_story_5083_50830400_59_dialog_content = "En cuanto a la investigación... Supongo que fue bastante divertido.",
  ui_story_5083_50830400_60_dialog_content = "¿Ves? Y puedo decir que también estás interesado en estos juegos, Barton. ¿Crees que puedes dejarme libre esta vez?",
  ui_story_5083_50830400_61_dialog_content = "Bueno, disfruto jugueteando con nuevos aparatos tanto como el siguiente. Te diré qué, devuélveme los vales y fingiré que esto nunca sucedió.",
  ui_story_5083_50830400_62_dialog_content = "¡Oh, no seas así! ¿Qué tiene de malo patrocinar un poco nuestro establecimiento?",
  ui_story_5083_50830400_63_dialog_content = "Después de todo, cada nueva pieza de tecnología que desarrollo está diseñada para ayudar a soldados de primera línea como tú.",
  ui_story_5083_50830400_64_dialog_content = "Ayudar, huh... ¡Espera, eso me recuerda! ¿Reconoces este dron?",
  ui_story_5083_50830400_65_dialog_content = "¿Eh? ¿Adónde fue?",
  ui_story_5083_50830400_66_dialog_content = "¿Qué dron?",
  ui_story_5083_50830400_67_dialog_content = "Es este dron de aspecto antiguo que vino a mí más temprano hoy. ¡Se llama a sí mismo mi Navegante!",
  ui_story_5083_50830400_68_dialog_content = "He estado siguiéndolo y charlando con él todo el día.",
  ui_story_5083_50830400_69_dialog_content = "Wow, eso suena bastante tecnológico, ¿no es así, Negador?",
  ui_story_5083_50830400_70_dialog_content = "De acuerdo. No creo que Illumina tenga ese tipo de tecnología inteligente todavía, y que tú digas que parece \"antigua\" tiene aún menos sentido...",
  ui_story_5083_50830400_71_dialog_content = "¿En serio? Porque pensé que lo habías hecho tú. Me pregunto a dónde se fue el pequeño... Bueno, estoy seguro de que no puede perderse ya que es un dron de navegación y todo.",
  ui_story_5083_50830400_72_dialog_content = "Te lo mostraré la próxima vez que tenga la oportunidad.",
  ui_story_5083_50830400_73_dialog_content = "También me gustaría echarle un vistazo... Cualquier cosa que conduzca a un futuro más fuerte siempre me interesará.",
  ui_story_5083_50830400_74_dialog_content = "Aquí están tus vales, Barton. No olvides mantener este lugar como nuestro pequeño secreto, ¿de acuerdo?",
  ui_story_5083_50830400_75_dialog_content = "Lo haré, ¡y gracias! Rara vez tengo la oportunidad de ver esta parte de la ciudad, así que aún no estoy listo para volver. ¿Qué tal si invito a los dos a una buena comida?",
  ui_story_5083_50830400_76_dialog_content = "¡Cuenta conmigo! Sabía que eras un buen tipo, Barton!",
  ui_story_5083_50830400_77_dialog_content = "También he tenido suficiente con la comida del laboratorio, así que gracias... Y si es realmente buena, me gustaría recomendársela a mi hermana.",
  ui_story_5083_50830400_78_dialog_content = "¡Oh sí! Oye Barton, ¿sabías que su hermana mayor no es otra que la gran Reinhardt?",
  ui_story_5083_50830400_79_dialog_content = "No lo pongas así, Gronru. Es vergonzoso.",
  ui_story_5083_50830400_80_dialog_content = "¿En serio? No podía decirlo en absoluto, ya que tu hermana brilla más que nadie.",
  ui_story_5083_50830400_81_dialog_content = "... Algún día la alcanzaré.",
  ui_story_5083_50830400_82_dialog_content = "¿Es eso cierto? Porque creo que ya lo estás haciendo bien, ¡Ahora vamos a comer!",
  ui_story_5083_50830400_83_dialog_content = "Eso no estuvo nada mal. Supongo que puedo recomendarlo a... Ella.",
  ui_story_5083_50830400_84_dialog_content = "Hmm... Ustedes dos realmente son muy diferentes el uno del otro.",
  ui_story_5083_50830400_85_dialog_content = "Sé que ya has visto a Reinhardt en acción, pero aún no has tenido la oportunidad de ver brillar al negador, Barton.",
  ui_story_5083_50830400_86_dialog_content = "¿Te gustan las simulaciones militares, verdad? Quizás ustedes dos podrían jugar un partido.",
  ui_story_5083_50830400_87_dialog_content = "Estaría bien con cualquier otra competencia, ¿pero una prueba de estrategias de combate contra un investigador? ¡Claro, adelante!",
  ui_story_5083_50830400_88_dialog_content = "No te pedí que me causaras problemas, Gronru... Pero está bien. Acepto tu desafío, Teniente Barton. Pero te advierto: no me subestimaría si fuera tú.",
  ui_story_5083_50830400_89_dialog_content = "<color=#e8d9bb>El grupo regresa a la tienda oculta de Gronru, donde Barton y el negador participan en una batalla simulada en una mesa de arena.</color>",
  ui_story_5083_50830400_90_dialog_content = "<color=#e8d9bb>Para sorpresa de Barton, las tácticas de Denier son mucho más viciosas e implacables de lo que esperaba de un investigador.</color>",
  ui_story_5083_50830400_91_dialog_content = "<color=#e8d9bb>Al sacrificar peón tras peón, ella se adentra más en el territorio de Barton, lo que lo toma desprevenido. Cuando se da cuenta de lo precaria que es su situación, ya está a momentos de la derrota.</color>",
  ui_story_5083_50830400_92_dialog_content = "(¡Esto no es bueno! Ya perdí contra Gronru; ¡No puedo permitirme perder también contra su amiga!)",
  ui_story_5083_50830400_93_dialog_content = "<color=#e8d9bb>Ruborizado de vergüenza, Barton de repente coloca su próxima pieza en posición, dañando el lado del tablero de Denier.</color>",
  ui_story_5083_50830400_94_dialog_content = "<color=#e8d9bb>Mientras ella se apresura a reorganizar sus piezas, Barton presiona su ventaja y lanza una serie de ataques.</color>",
  ui_story_5083_50830400_95_dialog_content = "Eso fue un movimiento sucio, Barton... ¿Ves? El negador está a punto de llorar...",
  ui_story_5083_50830400_96_dialog_content = "La moral no significa nada en el campo de batalla; ¡lo único que importa es ganar o perder! Mi oficial al mando me enseñó a ganar a cualquier precio, ¡y eso es exactamente lo que voy a hacer!",
  ui_story_5083_50830400_97_dialog_content = "<color=#e8d9bb>A pesar de sus duras palabras, la brecha ya era demasiado difícil de superar. Después de colocar sus piezas de nuevo en el tablero de arena, Negador recupera su compostura con temblor.</color>",
  ui_story_5083_50830400_98_dialog_content = "<color=#e8d9bb>Cebo, flanqueo y aplastamiento de su oponente sacrificando constantemente sus piezas... Así es como Denier emergió victoriosa en su batalla.</color>",
  ui_story_5083_50830400_99_dialog_content = "¡Jajajaja! Parece que ella te ha superado tanto en estrategia como en modales, Barton!",
  ui_story_5083_50830400_100_dialog_content = "¿Te llamas teniente con esas tácticas encubiertas? Solo espera hasta que yo cuente...",
  ui_story_5083_50830400_101_dialog_content = "Eh... ¡E-Espera un minuto, ustedes dos! ¡No pueden contarle a nadie más sobre lo que pasó aquí hoy! ¡Por favor!",
  ui_story_5083_50830400_102_dialog_content = "Si se corre la voz, ¡nunca lo superaré! <size=45>¡Por favor! ¡Haré cualquier cosa!!!</size>",
  ui_story_5083_50830500_1_dialog_content = "<color=#e8d9bb>Un Barton de aspecto sombrío reaparece en las puertas del campamento cargando varias bolsas de diferentes tamaños. Tengo que ir a advertirle—</color>",
  ui_story_5083_50830500_2_dialog_content = "¿Dónde fuiste? Desapareciste durante medio día, ¿sabes...?",
  ui_story_5083_50830500_3_dialog_content = "¡Bip—Peligro, Barton—",
  ui_story_5083_50830500_4_dialog_content = "¿Qué peligro? Estamos en el campamento... ¿Eh?",
  ui_story_5083_50830500_5_dialog_content = "<color=#e8d9bb>Reinhardt se encuentra en el centro del campo de entrenamiento de la 2ª Legión, con una lanza en la mano. Parece que ha estado esperando durante mucho tiempo.</color>",
  ui_story_5083_50830500_6_dialog_content = "Parece que está lista para matar a alguien. ¿Me pregunto quién la habrá enfadado?",
  ui_story_5083_50830500_7_dialog_content = "...",
  ui_story_5083_50830500_8_dialog_content = "<size=45>Barton—!</size>",
  ui_story_5083_50830500_9_dialog_content = "¡Cómo te atreves a usar trucos baratos contra mi hermana! ¡Voy a enseñarte una lección que nunca olvidarás!",
  ui_story_5083_50830500_10_dialog_content = "¿Qué es ella, una niña pequeña? ¿Cómo podría delatarme a su hermana?!",
  ui_story_5083_50830500_11_dialog_content = "¡Bip—Curso de acción sugerido: ¡CORRE!",
  ui_story_5083_50830500_12_dialog_content = "¡Aquí están tus cosas, todos! Lo siento, pero tengo que irme—",
  ui_story_5083_50830500_13_dialog_content = "¡Regresa aquí, cobarde!!!",
  ui_story_5083_50830500_14_dialog_content = "<color=#e8d9bb>Reinhardt persigue sin piedad a Barton, su lanza ardiente corta a través de la oscuridad de la noche todo el tiempo.</color>",
  ui_story_5083_50830500_15_dialog_content = "¡Oye, córtalo ya! Voy a contraatacar si esto continúa.",
  ui_story_5083_50830500_16_dialog_content = "¿Crees que puedes intimidarme de la misma manera que intimidaste a mi hermana? ¡Adelante entonces!",
  ui_story_5083_50830500_17_dialog_content = "¡Deja de mover eso cuando estás hablando! ¡Es peligroso!",
  ui_story_5083_50830500_18_dialog_content = "<color=#e8d9bb>Barton sigue huyendo de Reinhardt, quien se niega a dejarlo ir. En poco tiempo, los dos recorren la longitud de tres calles enteras—</color>",
  ui_story_5083_50830500_19_dialog_content = "¡Muy bien, eso lo hace! ¡Toma esto!",
  ui_story_5083_50830500_20_dialog_content = "¿Arena? ¿En serio? Eres despreciable.",
  ui_story_5083_50830500_21_dialog_content = "¡Lo que sea necesario para ganar! ¡Ahora toma esto!",
  ui_story_5083_50830500_22_dialog_content = "<color=#FFB400>¡Lanza perforadora de estrellas</color>!",
  ui_story_5083_50830500_23_dialog_content = "<color=#e8d9bb>Los dos luchan de un lado a otro en la calle, causando no poca cantidad de pánico. Los soldados corren hacia la escena, pero no están seguros de cómo detener la salvaje pelea.</color>",
  ui_story_5083_50830500_24_dialog_content = "¡Espero que estés listo para mi estilo de pipa de agua!",
  ui_story_5083_50830500_25_dialog_content = "¡Toma esto!",
  ui_story_5083_50830500_26_dialog_content = "¡Jaja, no está mal! ¡Avanza!",
  ui_story_5083_50830500_27_dialog_content = "<size=45>¡Ya basta, bufones!</size>",
  ui_story_5083_50830500_28_dialog_content = "Peleando entre ustedes como un montón de niños... Si se sienten tan inquietos, ¡entonces regresen al campo de entrenamiento y denme cien vueltas cada uno!!!",
  ui_story_5083_50830500_29_dialog_content = "Ugh, todo es tu culpa. Ahora también tengo que correr cien vueltas.",
  ui_story_5083_50830500_30_dialog_content = "¿Crees que no te mereces eso después de intimidar a tus subordinados?",
  ui_story_5083_50830500_31_dialog_content = "Hablas como si tu hermana no hubiera usado las tácticas más inhumanas para vencerme... No estoy seguro de que ella necesite que la defiendas así en absoluto.",
  ui_story_5083_50830500_32_dialog_content = "¡Dejen de pelear y aceleren el paso, idiotas!",
  ui_story_5083_50830500_33_dialog_content = "¡Siéntete libre de pelear de nuevo una vez que termines tus cien vueltas, asumiendo que aún puedas mantenerte en pie después!",
  ui_story_5083_50830500_34_dialog_content = "Huff, huff...",
  ui_story_5083_50830500_35_dialog_content = "¡Vaya, no te estás tomando esto en serio, verdad? Je... ¡Ahora sí que estoy entusiasmado! ¡Vamos!",
  ui_story_5083_50830500_36_dialog_content = "¡Solo trata de seguirme! ¡Todavía voy a golpearte incluso si no puedes mantenerte de pie!",
  ui_story_5083_50830500_37_dialog_content = "<color=#e8d9bb>Los dos jóvenes soldados corrieron alrededor de la pista con todas sus fuerzas. A medida que aumentaba el número de vueltas, sus pasos también se volvían cada vez más fatigados.</color>",
  ui_story_5083_50830500_38_dialog_content = "Me sorprende que hayas podido ponerte al día... ¡Pero aún no he terminado!",
  ui_story_5083_50830500_39_dialog_content = "<color=#e8d9bb>Sesenta vueltas, setenta vueltas... Sus pasos se volvieron lentos y erráticos, como si sus piernas estuvieran llenas de plomo.</color>",
  ui_story_5083_50830500_40_dialog_content = "Este castigo podría ser un poco excesivo, Comandante Pango...",
  ui_story_5083_50830500_41_dialog_content = "¿Pedí tu opinión? ¡La gente todavía está limpiando el desastre que dejaron, sabes!",
  ui_story_5083_50830500_42_dialog_content = "Dado que a esos punk arrogantes les encanta tanto pelear, pensé que les haría sufrir un poco más hoy.",
  ui_story_5083_50830500_43_dialog_content = "<color=#e8d9bb>Ochenta vueltas, noventa vueltas... Los dos comienzan a tambalearse de un lado a otro, pero continúan animándose mutuamente hasta el final.</color>",
  ui_story_5083_50830500_44_dialog_content = "Oye... ¿Todavía te queda algo de lucha en ti?",
  ui_story_5083_50830500_45_dialog_content = "¿Tienes... que preguntar? Todo lo que puedo pensar... es cómo voy a lidiar con esa lanza tuya.",
  ui_story_5083_50830500_46_dialog_content = "<color=#e8d9bb>Noventa y nueve, cien—El silbato del comandante señala el fin de su agotador castigo, y los dos se desploman inmediatamente al suelo.</color>",
  ui_story_5083_50830500_47_dialog_content = "¿Estás... todavía vivo... allí?",
  ui_story_5083_50830500_48_dialog_content = "Sí... aún respirando...!",
  ui_story_5083_50830500_49_dialog_content = "¿Todavía quieres... pelear? Estoy listo... cuando tú lo estés...",
  ui_story_5083_50830500_50_dialog_content = "Je... No pelearé contigo... Si ni siquiera puedes ponerte de pie, pero no te preocupes, aceptaré cualquier desafío tuyo cualquier día.",
  ui_story_5083_50830500_51_dialog_content = "¿Oh sí...? Qué noble de tu parte... Jajaja—tos, tos—",
  ui_story_5083_50830500_52_dialog_content = "<color=#e8d9bb>Reinhardt ríe a carcajadas, pero un ataque de tos rápidamente lo detiene. Sin embargo, logra ponerse de pie y extiende su mano.</color>",
  ui_story_5083_50830500_53_dialog_content = "Tos, considérate mi rival. Te lo has ganado.",
  ui_story_5083_50830500_54_dialog_content = "Tu comandante tiene un buen punto. Todos somos soldados de Illumina, una pequeña competencia es saludable, pero no deberíamos pelear entre nosotros.",
  ui_story_5083_50830500_55_dialog_content = "Según la etiqueta de Illumina, deberíamos estrechar las manos y hacer las paces.",
  ui_story_5083_50830500_56_dialog_content = "Tienes todas las cualidades que busco en una persona, y estoy seguro de que necesitaré tu ayuda en el futuro.",
  ui_story_5083_50830500_57_dialog_content = "Increíble... Eres incluso más engreído de lo que pensaba, y aún eres solo un nuevo recluta.",
  ui_story_5083_50830500_58_dialog_content = "No me hará daño decírtelo, pero tengo este pequeño sueño de convertirme en Gran Mariscal algún día.",
  ui_story_5083_50830500_59_dialog_content = "¿Llamas a eso un \"pequeño sueño\"? Interesante...",
  ui_story_5083_50830500_60_dialog_content = "Está bien, ¡creo en ti! No hay forma de fingir el tipo de presencia que emanas, eso es seguro.",
  ui_story_5083_50830500_61_dialog_content = "Estamos empatados por ahora, ¡pero no te pongas arrogante! Tendremos muchas oportunidades para competir en el futuro.",
  ui_story_5083_50830500_62_dialog_content = "Esperándolo.",
  ui_story_5083_50830500_63_dialog_content = "Esa mirada en sus ojos me dijo que estaba completamente seria. Su luz brilla incluso más brillante que la del comandante.",
  ui_story_5083_50830500_64_dialog_content = "Hmph, Illumina estará mucho mejor con alguien así a cargo... ¡No puedo esperar para ver a dónde va!",
  ui_story_5083_50830500_65_dialog_content = "¿De qué estás murmurando, Barton? ¡Ven aquí!",
  ui_story_5083_50830500_66_dialog_content = "Nuestra Legión finalmente está completamente dotada de personal nuevamente, por lo que es hora de nuestra foto grupal habitual.",
  ui_story_5083_50830500_67_dialog_content = "El comandante Pango se quedó porque quería esperarte. ¡No es de extrañar que estuviera tan enfadado cuando te vio peleando con Reinhardt en su lugar! ¡Ahora apúrate y ven aquí!",
  ui_story_5083_50830500_68_dialog_content = "¡Una foto de grupo... Claro!",
  ui_story_5083_50830500_69_dialog_content = "Aquí, te hemos reservado un lugar justo al lado del Comandante Pango.",
  ui_story_5083_50830500_70_dialog_content = "¡Gracias!",
  ui_story_5083_50830500_71_dialog_content = "Hmph, ¿todavía caminando, eh? Supongo que mi entrenamiento no fue completamente desperdiciado en ti después de todo.",
  ui_story_5083_50830500_72_dialog_content = "Todavía soy joven y lleno de vida, a diferencia de un cierto comandante—",
  ui_story_5083_50830500_73_dialog_content = "Ya es suficiente, ustedes dos... Es hora de su discurso, Comandante.",
  ui_story_5083_50830500_74_dialog_content = "¡Hmph!",
  ui_story_5083_50830500_75_dialog_content = "¡Hmph!",
  ui_story_5083_50830500_76_dialog_content = "... ¡Soldados de la 2ª Legión! ¡Nos hemos reunido aquí hoy para celebrar su graduación del campamento de entrenamiento! ¡Felicidades por sobrevivir al programa de entrenamiento de este anciano!",
  ui_story_5083_50830500_77_dialog_content = "Estoy orgulloso de decir que he moldeado a cada uno de ustedes en los mejores guerreros de Illumina. Pero no se equivoquen: ¡los Eclipsites a los que se enfrentarán en el futuro son cien veces más brutales!",
  ui_story_5083_50830500_78_dialog_content = "¡Pero como soldados de la 2ª Legión, nunca nos echaremos atrás ni nos rendiremos! Ahora, terminemos con esta foto, para que puedas ir a casa y disfrutar de tus tres días libres bien merecidos!",
  ui_story_5083_50830500_79_dialog_content = "¡Tres hurras para el Comandante Pango!",
  ui_story_5083_50830500_80_dialog_content = "¡No me agradezcas todavía! El futuro no será fácil para ninguno de ustedes; una vez que regresen del frente, ¡esperen más entrenamiento de su querido viejo comandante! ¡Eso es todo!",
  ui_story_5083_50830500_81_dialog_content = "¡Bien, ahora todos sonríen a lo grande — ¡Esplendor Illumina!",
  ui_story_5083_50830500_82_dialog_content = "<size=45>¡Esplendor Illumina!</size>",
  ui_story_5083_50830600_1_dialog_content = "El tiempo de vacaciones casi se acaba, ¡así que no me dejes verte holgazaneando!",
  ui_story_5083_50830600_2_dialog_content = "¡Me aseguraré de trabajar duro en mi puntería, Comandante!",
  ui_story_5083_50830600_3_dialog_content = "Si disparas a un Eclipsite hasta matarlo y cae sobre ti, los que están detrás de él saltarán sobre ti de inmediato. ¿Cómo esperas mantener un tiro claro bajo esas circunstancias?",
  ui_story_5083_50830600_4_dialog_content = "Además, hay Eclipsites allí que son impermeables a las armas de fuego. Lo que necesitas hacer es entrenar tu esgrima, Barton!",
  ui_story_5083_50830600_5_dialog_content = "¡Un buen arma cuerpo a cuerpo nunca te fallará! Siempre que recuerdes eso cuando saques tu espada, ¡nunca te encontrarás atrapado por el enemigo!",
  ui_story_5083_50830600_6_dialog_content = "...",
  ui_story_5083_50830600_7_dialog_content = "¡Un soldado de Illumina no teme a la muerte! Todos los días, luchamos con nuestras vidas para liberar a Astra de la plaga Eclipsite! Sin embargo, lo que sí tememos es morir una muerte sin sentido!",
  ui_story_5083_50830600_8_dialog_content = "¡Por eso mantenerse vivo debe ser tu primera prioridad en la batalla! ¿Me hago entender?!",
  ui_story_5083_50830600_9_dialog_content = "¡Sí señor!",
  ui_story_5083_50830600_10_dialog_content = "¡Entonces ponte a trabajar, soldado! ¡No malgastes tu tiempo como lo hiciste estos últimos dos días!",
  ui_story_5083_50830600_11_dialog_content = "... Como soldados veteranos, no hay forma de que podamos seguir perdiendo ante los nuevos reclutas de la 1ra Legión.",
  ui_story_5083_50830600_12_dialog_content = "¡Entendido, Comandante!",
  ui_story_5083_50830600_13_dialog_content = "Al igual que Dogg, al Comandante Pango le cuesta decir lo que piensa.",
  ui_story_5083_50830600_14_dialog_content = "Podrías pensar que una persona mayor sería más directa sobre las cosas... Realmente debe querer que ponga a Reinhardt en su lugar, ¿eh?",
  ui_story_5083_50830600_15_dialog_content = "Bip—No estoy seguro de que eso sea completamente correcto, Barton.",
  ui_story_5083_50830600_16_dialog_content = "¡Jajaja! Eres bastante tímido para un dron, ¿sabes? Siempre pareces desaparecer cuando otras personas aparecen. De todos modos, se supone que debes ser mi Navegador, ¿verdad?",
  ui_story_5083_50830600_17_dialog_content = "... ¿Necesitas direcciones?",
  ui_story_5083_50830600_18_dialog_content = "Nah, pero hay un lugar que quiero ver hoy. Vamos.",
  ui_story_5083_50830600_19_dialog_content = "Beep—¿Quieres pasar tu último día libre en un museo, Barton?",
  ui_story_5083_50830600_20_dialog_content = "Así es como es con nosotros los soldados; si no estamos luchando, estamos entrenando para una pelea. Además, cada lugar es básicamente el mismo cuando vives bajo tierra.",
  ui_story_5083_50830600_21_dialog_content = "... Aún así, sería agradable tener una de las máquinas de juegos de Gronru en casa para pasar el tiempo.",
  ui_story_5083_50830600_22_dialog_content = "Si no estuviéramos en guerra, siento que podría jugar juegos por el resto de mi vida.",
  ui_story_5083_50830600_23_dialog_content = "Eso o establecer un equipo de exploración para navegar por los mares.",
  ui_story_5083_50830600_24_dialog_content = "<color=#FFB400>Paz</color>... ¡Jaja! Solo pensar en ello es suficiente para mí.",
  ui_story_5083_50830600_25_dialog_content = "Bip—Activando el modo de guía del Museo Illumina.",
  ui_story_5083_50830600_26_dialog_content = "<color=#FFB400>Entrañas 80</color>, originalmente el sector más cercano a la Zona Oscura.",
  ui_story_5083_50830600_27_dialog_content = "Durante la Guerra de la Zona Oscura, esta Subciudad contribuyó con servicios de transporte esenciales para el esfuerzo de guerra de Illumina.",
  ui_story_5083_50830600_28_dialog_content = "El Comandante Pango también lo mencionó antes... Según él, la batalla que tuvo lugar allí fue especialmente brutal, y la 2da Legión fue casi completamente aniquilada.",
  ui_story_5083_50830600_29_dialog_content = "Como niños, pasábamos mucho tiempo aprendiendo sobre el pasado en estos museos. Solíamos estar tan celosos de estas leyendas... Eran lo más cool.",
  ui_story_5083_50830600_30_dialog_content = "Pero ahora conozco los tipos de sacrificios que se hicieron para crear estas leyendas... Y eso no es algo que quiera ver más.",
  ui_story_5083_50830600_31_dialog_content = "Continuando... Se cree que la Crisis de Darkover, que continúa hasta el día de hoy, comenzó con el ataque a Eraveil hace dos años... Hasta donde sabemos, los Celestitas estaban completamente...",
  ui_story_5083_50830600_32_dialog_content = "¿Eh? ¿Por qué te detuviste de repente...?",
  ui_story_5083_50830600_33_dialog_content = "Oye, Barton.",
  ui_story_5083_50830600_34_dialog_content = "¿Qué estás haciendo acá?",
  ui_story_5083_50830600_35_dialog_content = "Repasando mi historia, por supuesto. La historia de Illumina, la historia de la guerra, ese tipo de cosas.",
  ui_story_5083_50830600_36_dialog_content = "... ¿Qué crees que será Illumina en el futuro, Barton?",
  ui_story_5083_50830600_37_dialog_content = "¿Por qué preguntas?",
  ui_story_5083_50830600_38_dialog_content = "Los misteriosos Caelestites fueron aniquilados por un solo ataque sorpresa. Debido a eso, nosotros, los Aurorianos, nunca volveremos a recibir su orientación.",
  ui_story_5083_50830600_39_dialog_content = "La <color=#FFB400>Crisis de Darkover</color> aún no ha terminado, y seguimos perdiendo más y más soldados. Mira por la ventana, puedes ver el memorial a los caídos desde aquí, ¿no es así?",
  ui_story_5083_50830600_40_dialog_content = "Los nombres de cada hermano y hermana que perdimos en la guerra están grabados allí... Pero aún puedo escuchar sus voces resonando en mi cabeza.",
  ui_story_5083_50830600_41_dialog_content = "Todos nosotros comenzamos a aprender historia desde una temprana edad... Y cuanto más viejo me hago, más cerca me siento de las cosas que se conservan aquí.",
  ui_story_5083_50830600_42_dialog_content = "Después de ver a mis amigos dar sus vidas en batalla, solo para que sus sacrificios se conviertan en lecciones de historia para las generaciones futuras... Empecé a sentirme confundido, Barton.",
  ui_story_5083_50830600_43_dialog_content = "¿Confundido?",
  ui_story_5083_50830600_44_dialog_content = "Astra está en peligro mortal, y aunque estoy dispuesto a dar mi vida por su bien, simplemente no puedo ver su futuro...",
  ui_story_5083_50830600_45_dialog_content = "Sabes que la gente de Lumopolis está peleando entre sí ahora, ¿verdad? Su promesa de ayudarnos nunca se materializó, y ya hemos dejado de intercambiar recursos con ellos.",
  ui_story_5083_50830600_46_dialog_content = "Todo Astra está en ruinas ahora mismo. Ya no estoy seguro de por qué estoy luchando, o si incluso podemos ganar.",
  ui_story_5083_50830600_47_dialog_content = "... ¿Tienes miedo?",
  ui_story_5083_50830600_48_dialog_content = "Por supuesto que tengo miedo... La suerte fue la única razón por la que sobrevivimos cuando el resto de nuestros camaradas no lo hizo.",
  ui_story_5083_50830600_49_dialog_content = "Me dijiste que esto era algo que teníamos que soportar por el resto de nuestras vidas. Estoy haciendo lo mejor que puedo para vivir con ello...",
  ui_story_5083_50830600_50_dialog_content = "¿Sabías que el Comité ha estado interfiriendo con los planes del Gran Mariscal? Todavía no pueden decidir cuál es la mejor manera de proceder con la guerra. Bastante tranquilizador, ¿eh?",
  ui_story_5083_50830600_51_dialog_content = "Aun así, apuesto a que mi miedo no se compara con el de los soldados que regresaron de la Guerra de la Zona Oscura.",
  ui_story_5083_50830600_52_dialog_content = "Tal como está, Illumina no tiene un capitán claro al mando. ¿No te asusta eso, Barton?",
  ui_story_5083_50830600_53_dialog_content = "Si ese es el caso, entonces lo haremos.",
  ui_story_5083_50830600_54_dialog_content = "¡Tú, yo, y esa Reinhardt mujer de la 1ra legión!",
  ui_story_5083_50830600_55_dialog_content = "Tenemos derecho a opinar sobre las cosas, ¿verdad?",
  ui_story_5083_50830600_56_dialog_content = "Después de todo, ¡de eso estamos hablando del futuro! ¿Quién mejor para enfrentar los desafíos en el camino que la próxima generación de líderes?",
  ui_story_5083_50830600_57_dialog_content = "No importa lo que piense nadie, nunca me rendiré. ¡No dejaré que Illumina se hunda solo porque nadie puede descifrar cómo dirigirla!",
  ui_story_5083_50830600_58_dialog_content = "¡Así que si no estás seguro de qué hacer, simplemente pon tu vida en mis manos y yo guiaré el camino!",
  ui_story_5083_50830600_59_dialog_content = "Je... Hablas mucho para un tipo que absolutamente no tiene piernas de mar.",
  ui_story_5083_50830600_60_dialog_content = "*Suspiros* Solo... No sé cómo puedes estar tan seguro mientras yo sigo atrapado dentro de mi propia cabeza.",
  ui_story_5083_50830600_61_dialog_content = "También soy un hijo de Illumina, Barton. No se puede decir quién estará a cargo de este barco en el futuro.",
  ui_story_5083_50830600_62_dialog_content = "Pero una cosa es segura: ¡Voy a demostrarle al Comandante Pango que soy el soldado de élite que ha estado esperando todo este tiempo!",
  ui_story_5083_50830600_63_dialog_content = "Haz lo que quieras, Dogg. No es como si estuviera tratando de impresionar a ese anciano o algo así.",
  ui_story_5083_50830600_64_dialog_content = "De hecho, hice una solicitud antes de venir aquí hoy, quiero formar una unidad de comando para la 2ª Legión.",
  ui_story_5083_50830600_65_dialog_content = "Después de lo que pasó la última vez, me di cuenta de que nuestras defensas se desmoronan bastante rápido cuando nos enfrentamos a los Eclipsites.",
  ui_story_5083_50830600_66_dialog_content = "Por eso quiero establecer una <color=#FFB400>rama de asalto</color> y entrenar a los soldados para llevar la lucha a los Eclipsites. Estoy seguro de que necesitaremos luchadores así en el futuro.",
  ui_story_5083_50830600_67_dialog_content = "Si solo Lumopolis hubiera decidido trabajar con nosotros... Podrían habernos ayudado a entrenar a los soldados montados.",
  ui_story_5083_50830600_68_dialog_content = "Sé que la tecnología va a decidir muchas batallas para nosotros en el futuro... Pero no se puede negar la importancia de las unidades terrestres también.",
  ui_story_5083_50830600_69_dialog_content = "Y dado que nuestros niveles de producción aún están rezagados, solo podemos confiar en el acero frío para abrir un camino y mantener al enemigo a raya.",
  ui_story_5083_50830600_70_dialog_content = "Esa es una perspectiva impresionante, Dogg... La verdad es que no he pensado tanto en las cosas, para ser honesto.",
  ui_story_5083_50830600_71_dialog_content = "Pero si ese es tu plan, ¿por qué quieres la aprobación del comandante tan desesperadamente? ¿Por qué sientes que tienes que demostrar tu valía?",
  ui_story_5083_50830600_72_dialog_content = "Él es nuestro comandante, y nos entrenó hasta el máximo de sus habilidades. ¿No es esa razón suficiente?",
  ui_story_5083_50830600_73_dialog_content = "Lo es, pero estoy seguro de que esa no es la única razón.",
  ui_story_5083_50830600_74_dialog_content = "Je... A pesar de ser un idiota musculoso, a veces puedes ser bastante perspicaz.",
  ui_story_5083_50830600_75_dialog_content = "... Mi anciano era buenos amigos con el Comandante Pango en aquellos días. Así es como terminó cuidándome.",
  ui_story_5083_50830600_76_dialog_content = "Me crió y cuidó de mí como si fuera su propio hijo. Para mí, el Comandante Pango no es diferente a mi padre.",
  ui_story_5083_50830600_77_dialog_content = "Su hijo era mi hermano mayor, y su esposa era mi mamá.",
  ui_story_5083_50830600_78_dialog_content = "No sabía que el comandante tenía una familia... ¿Les pasó algo...?",
  ui_story_5083_50830600_79_dialog_content = "Hace seis años, la Subciudad donde vivíamos fue atacada.",
  ui_story_5083_50830600_80_dialog_content = "Pero siendo el soldado que es, el Comandante Pango estaba luchando en el frente en ese momento.",
  ui_story_5083_50830600_81_dialog_content = "Sacrificó a su esposa para evacuarme a mí y a los demás no combatientes.",
  ui_story_5083_50830600_82_dialog_content = "El comandante nunca habló de ello, pero inmediatamente solicitó ser transferido lejos del frente. Desde entonces, se ha negado a liderar cualquier operación defensiva en las Subciudades.",
  ui_story_5083_50830600_83_dialog_content = "... Estoy seguro de que todavía se culpa a sí mismo por lo que pasó.",
  ui_story_5083_50830600_84_dialog_content = "¿Es por eso que el anciano... Nunca se queda en el campamento por mucho tiempo?",
  ui_story_5083_50830600_85_dialog_content = "Nada de eso fue su culpa, solo desearía poder hacerle ver eso.",
  ui_story_5083_50830600_86_dialog_content = "Casi tengo la misma edad que mi hermano tenía en aquel entonces, también... Quiero que el Comandante Pango sepa que uno de sus hijos todavía está vivo.",
  ui_story_5083_50830600_87_dialog_content = "Pero no importa cuánto lo intente, sus ojos... Siempre están en ti.",
  ui_story_5083_50830600_88_dialog_content = "A veces me pongo celoso de ti, Barton. ¿Es porque no soy lo suficientemente fuerte?",
  ui_story_5083_50830600_89_dialog_content = "Al final del día... Solo quiero tomar el lugar de mi hermano y llenar el vacío en el corazón del comandante.",
  ui_story_5083_50830600_90_dialog_content = "Dogg... En lo que a mí respecta, ya eres más que suficiente. No hay razón para que te conviertas en alguien más.",
  ui_story_5083_50830600_91_dialog_content = "Por mucho que puedas ser un dolor, ¡no hay nadie más en todo Astra como tú! ¡No tienes que vivir en la sombra de nadie!",
  ui_story_5083_50830600_92_dialog_content = "Estoy seguro de que el anciano también está de acuerdo conmigo. ¿Por qué otra razón sería tan duro contigo también?",
  ui_story_5083_50830600_93_dialog_content = "Y gracias a ti, finalmente entiendo lo indirecto que puede ser el chico. Probablemente nunca se abrirá contigo sobre esas cosas.",
  ui_story_5083_50830600_94_dialog_content = "Además, dijiste que tú también eres su <color=#FFB400>niño</color>, ¿verdad? No puedo pensar en alguien que quiera ver a uno de sus niños intentando reemplazar a otro.",
  ui_story_5083_50830600_95_dialog_content = "Barton... You...",
  ui_story_5083_50830600_96_dialog_content = "Je—¡Jajajaja! Hombre, no tenía idea de que tuvieras algo más que músculos en tu cerebro!",
  ui_story_5083_50830600_97_dialog_content = "Estas palabras realmente no te quedan bien, Barton. Después de la escena que causaste ayer, eres la última persona que debería darme consejos, ¡jajaja!",
  ui_story_5083_50830600_98_dialog_content = "No estoy bromeando, Dogg.",
  ui_story_5083_50830600_99_dialog_content = "Lo sé. Gracias, Barton; me has dado mucho en qué pensar.",
  ui_story_5083_50830600_100_dialog_content = "No lo menciones. Solo intenta ser un poco más directo de ahora en adelante... Dogg.",
  ui_story_5083_50830700_1_dialog_content = "<color=#e8d9bb>Poco después, se estableció oficialmente la División de Comandos de la 2ª Legión, y Dogg fue elegido como su comandante tras su promoción a Mayor. Barton, por otro lado, fue promovido a Capitán y nombrado vicecomandante del Batallón de Infantería Mecanizada.</color>",
  ui_story_5083_50830700_2_dialog_content = "<color=#e8d9bb>Pero las preocupaciones de Dogg resultaron ser correctas, y pronto, la severidad de la Crisis de Darkover alcanzó terribles nuevas alturas.</color>",
  ui_story_5083_50830700_3_dialog_content = "<color=#e8d9bb>Los Eclipsites rompieron la línea defensiva de Illumina y comenzaron a rodear las Subciudades 13 y 19, las instalaciones defensivas más importantes de la Federación.</color>",
  ui_story_5083_50830700_4_dialog_content = "<color=#e8d9bb>Las comunicaciones se desactivaron al principio de la lucha. Para cuando un mensajero logró salir y llegó a la ciudad de Gannon, las dos Subciudades ya habían estado bajo asedio durante varios días.</color>",
  ui_story_5083_50830700_5_dialog_content = "<color=#e8d9bb>Se convocó una emergencia entre los líderes de la ciudad de Gannon, pero incluso después de horas de deliberación, no se pudo tomar una decisión—</color>",
  ui_story_5083_50830700_6_dialog_content = "¡No podemos esperar más! Con cada minuto que perdemos parloteando aquí, ¿quién sabe cuántas vidas se están perdiendo?!",
  ui_story_5083_50830700_7_dialog_content = "La 2ª Legión está lista para desplegarse, Gran Mariscal. Solo dé la orden y estaremos en camino.",
  ui_story_5083_50830700_8_dialog_content = "Según el mensajero, Subciudad 13 solo estaba equipada para sobrevivir un día más de asedio. En este punto, no hay esperanza para ellos.",
  ui_story_5083_50830700_9_dialog_content = "Y mientras la situación de Subciudad 19 parecía menos grave, es muy posible que nuestras fuerzas solo encuentren una ciudad muerta llena de Eclipsites una vez que lleguen.",
  ui_story_5083_50830700_10_dialog_content = "El comandante de defensa de Subciudad 13 es un viejo amigo tuyo de tiempos de guerra, Pango. Deberías saberlo mejor que nadie—",
  ui_story_5083_50830700_11_dialog_content = "¡Soldados honorables como él y sus subordinados preferirían volar toda la Subciudad antes que dejarla caer en manos enemigas!",
  ui_story_5083_50830700_12_dialog_content = "¡De esa manera, podrían evitar que los Eclipsites aprovechen nuestros recursos y mantener a Gannon City segura!",
  ui_story_5083_50830700_13_dialog_content = "¡Tienes toda la razón! Conozco a esos tontos obstinados mejor que la mayoría, y eso es exactamente lo que harían—",
  ui_story_5083_50830700_14_dialog_content = "¡Pero también sé lo poderosos y tenaces que son!",
  ui_story_5083_50830700_15_dialog_content = "¡Todavía hay muchos civiles y recursos atrapados en esas ciudades, y esos soldados están dispuestos a arriesgar sus vidas por ellos!",
  ui_story_5083_50830700_16_dialog_content = "¡No abandonarán sus ciudades hasta el amargo final! ¡Es por eso que sé que están esperando que los salvemos!",
  ui_story_5083_50830700_17_dialog_content = "La mitad de mi legión todavía está luchando en la Zona Oscura, y tú acabas de reponer tu legión con nuevos reclutas.",
  ui_story_5083_50830700_18_dialog_content = "Y con la 1ra Legión demasiado ocupada fortaleciendo nuestras defensas... ¿A quién nos queda para desplegar?",
  ui_story_5083_50830700_19_dialog_content = "Incluso con todas nuestras fuerzas presentes, defender Gannon City de los Eclipsites no sería fácil. ¿Realmente crees que podemos permitirnos prescindir de algún soldado?",
  ui_story_5083_50830700_20_dialog_content = "Y considerando lo lejos que están esas dos subciudades de nosotros, no podríamos usar trenes para enviar refuerzos. Tendríamos que enviarlos a pie.",
  ui_story_5083_50830700_21_dialog_content = "Con las comunicaciones caídas, no sabemos qué nos espera allá afuera. ¿Y si nuestras tropas son emboscadas en el camino? ¡Estarían en grave peligro!",
  ui_story_5083_50830700_22_dialog_content = "¿¡¿No crees que esas dos Subciudades están en grave peligro en este momento?!?",
  ui_story_5083_50830700_23_dialog_content = "¡¿Cómo puedes ser tan despiadado, Motor?!",
  ui_story_5083_50830700_24_dialog_content = "¡Retira eso, Pango! ¿Tienes alguna idea de cuántos soldados he perdido en la Zona Oscura?! ¡No eres el único que tiene que preocuparse por la vida de las personas!",
  ui_story_5083_50830700_25_dialog_content = "Estoy harto de escuchar esta basura...",
  ui_story_5083_50830700_26_dialog_content = "Barton!",
  ui_story_5083_50830700_27_dialog_content = "Esas personas nos tratan como sus escudos, y sin embargo, nos arrojan al suelo tan pronto como las cosas se ponen difíciles.",
  ui_story_5083_50830700_28_dialog_content = "No tienes libertad para expresar tu opinión aquí, soldado.",
  ui_story_5083_50830700_29_dialog_content = "Oh lo siento, me iré entonces—Además, estar cerca de ustedes me enferma.",
  ui_story_5083_50830700_30_dialog_content = "¿Quién te crees que eres, hablando así?!",
  ui_story_5083_50830700_31_dialog_content = "Lo siento por eso, señor. Estoy bastante seguro de que su boca no está completamente conectada a su cerebro.",
  ui_story_5083_50830700_32_dialog_content = "¿Qué crees que estás haciendo, Dogg?! ¡No hables así sobre tu compañero soldado!",
  ui_story_5083_50830700_33_dialog_content = "¿Ya terminaron, hombres?",
  ui_story_5083_50830700_34_dialog_content = "Estoy seguro de que sus disputas son muy importantes, pero la 1ra Legión todavía está luchando por sus vidas allí afuera.",
  ui_story_5083_50830700_35_dialog_content = "Dime, jóvenes oficiales: ¿apoyan la decisión de su comandante?",
  ui_story_5083_50830700_36_dialog_content = "Por supuesto, Gran Mariscal.",
  ui_story_5083_50830700_37_dialog_content = "... En realidad, creo que el comandante de la 3ra Legión tiene un punto.",
  ui_story_5083_50830700_38_dialog_content = "¿Qué? ¡¿Has perdido la cabeza, Dogg?!",
  ui_story_5083_50830700_39_dialog_content = "Te lo dije, todavía puedo escuchar las voces de mis camaradas caídos en mi cabeza... No podemos permitirnos ser descuidados, o sus sacrificios habrán sido en vano.",
  ui_story_5083_50830700_40_dialog_content = "... Estás despedido por ahora.",
  ui_story_5083_50830700_41_dialog_content = "¡Entendido, Comandante Pango! Solo pido que tú y el Capitán Barton consideren cuidadosamente los riesgos antes de tomar cualquier decisión.",
  ui_story_5083_50830700_42_dialog_content = "¡Los niños de Illumina crecen bajo el esplendor de la Torre Central! ¡Conocen muy bien la justicia de nuestra causa!",
  ui_story_5083_50830700_43_dialog_content = "Antes de que nuestros soldados sean enviados a las diferentes Subciudades, se les informa de esta posibilidad con mucha anticipación.",
  ui_story_5083_50830700_44_dialog_content = "El tiempo para discutir ha terminado, Pango. Necesitamos trabajar juntos para defender Gannon City.",
  ui_story_5083_50830700_45_dialog_content = "Si están dispuestos a dar sus vidas por Illumina, entonces nos corresponde a nosotros asegurarnos de que sus sacrificios no sean en vano.",
  ui_story_5083_50830700_46_dialog_content = "¡Si tú no vas, entonces mis soldados y yo iremos!",
  ui_story_5083_50830700_47_dialog_content = "No, Pango.",
  ui_story_5083_50830700_48_dialog_content = "Motor tiene razón: casi no tenemos conocimiento de la situación allí afuera, y no podemos permitirnos más pérdidas. En cualquier caso, la 1ra Legión no enviará a ningún soldado para esto.",
  ui_story_5083_50830700_49_dialog_content = "Se supone que debemos ayudarnos mutuamente a través de esta prueba. Ahora no es el momento para las peleas internas.",
  ui_story_5083_50830700_50_dialog_content = "Si nuestros soldados ven esto, su moral se desplomará.",
  ui_story_5083_50830700_51_dialog_content = "Grr... Nos vamos, Barton!",
  ui_story_5083_50830700_52_dialog_content = "¡Mantén tu posición y no tomes acciones no autorizadas, Comandante! ¡Esa es una orden!",
  ui_story_5083_50830700_53_dialog_content = "Oye, ustedes dos. ¿Supongo que las cosas no salieron muy bien allí?",
  ui_story_5083_50830700_54_dialog_content = "¿Con ese cobarde a cargo de la 1ra Legión? ¡Por supuesto que no!",
  ui_story_5083_50830700_55_dialog_content = "¡No te vayas aún! Estoy aquí para entregar nuevas <color=#FFB400>órdenes</color>.",
  ui_story_5083_50830700_56_dialog_content = "\"Inmediatamente, la 2.ª Legión debe desplegarse en las Subciudades 13 y 19 para proporcionar refuerzos, con el Teniente Reinhardt y una parte de la 1ra Legión también brindando apoyo...\"",
  ui_story_5083_50830700_57_dialog_content = "Esa es más o menos la esencia de esto. ¿Cómo suena?",
  ui_story_5083_50830700_58_dialog_content = "¿Estás pensando seriamente en falsificar órdenes militares?",
  ui_story_5083_50830700_59_dialog_content = "Si no estás dispuesto a ayudar, entonces lo manejaremos por nuestra cuenta.",
  ui_story_5083_50830700_60_dialog_content = "Puedo enviar a algunos escuadrones de la 1ra Legión; el resto de ellos son más que capaces de defender Gannon City junto con la 3ra Legión.",
  ui_story_5083_50830700_61_dialog_content = "Es posible que no tengamos mucho impacto aquí, pero nuestra presencia en esas Subciudades podría marcar la diferencia entre la vida y la muerte.",
  ui_story_5083_50830700_62_dialog_content = "Desafortunadamente, no tengo suficientes soldados para esta misión. Por eso quería pedir ayuda a la 2da Legión.",
  ui_story_5083_50830700_63_dialog_content = "Sabes lo que te sucederá si seguimos adelante con esto, ¿no?",
  ui_story_5083_50830700_64_dialog_content = "Aprecio su preocupación, Comandante... Pero salvar vidas sigue siendo más importante para mí.",
  ui_story_5083_50830700_65_dialog_content = "... Eres solo un teniente de bajo rango. ¿Qué te dio la confianza para acercarte a nosotros con una hazaña como esta?",
  ui_story_5083_50830700_66_dialog_content = "Mi creencia es que ninguno de ustedes abandonaría jamás a sus camaradas.",
  ui_story_5083_50830700_67_dialog_content = "¿Todavía no te has decidido, Comandante Pango? Porque de cualquier manera, yo voy con ella.",
  ui_story_5083_50830700_68_dialog_content = "Primero desobedeciste las órdenes y ahora las estás falsificando? Tienes una audacia seria, Reinhardt.",
  ui_story_5083_50830700_69_dialog_content = "¿Eso es todo lo que tienes que decir después de seguirme todo este camino?",
  ui_story_5083_50830700_70_dialog_content = "¡Ja! ¿Crees que simplemente voy a quedarme parado y dejarte hacer lo que quieras?",
  ui_story_5083_50830700_71_dialog_content = "Interesante... Parece que no somos los únicos hartos de los de arriba, ¿verdad? ¡Bien! Ya es hora de que tomemos las decisiones por aquí!",
  ui_story_5083_50830700_72_dialog_content = "Hmph. Entrañas 13 es la más peligrosa, así que déjame esa a mí.",
  ui_story_5083_50830700_73_dialog_content = "Sé mi invitado, Wrath. ¿Cuántos soldados necesitas?",
  ui_story_5083_50830700_74_dialog_content = "Dado que las tropas escasean por aquí, solo tomaré un solo pelotón.",
  ui_story_5083_50830700_75_dialog_content = "¿Cómo esperas lograr esto con solo un pelotón? ¡Olvídalo, voy contigo y traigo más soldados conmigo!",
  ui_story_5083_50830700_76_dialog_content = "¡Espera!",
  ui_story_5083_50830700_77_dialog_content = "Por mucho que Motor pueda enfurecer, su Departamento de Inteligencia casi nunca se equivoca.",
  ui_story_5083_50830700_78_dialog_content = "La situación de la Subciudad 13 está lejos de ser optimista... Desde una perspectiva puramente temporal, es cierto que la ciudad está más allá de la salvación.",
  ui_story_5083_50830700_79_dialog_content = "Si enviamos demasiadas de nuestras fuerzas, hay una buena posibilidad de que queden atrapadas en la batalla sin salida.",
  ui_story_5083_50830700_80_dialog_content = "Entendido... Entonces solo serás tú y un pequeño equipo, Wrath.",
  ui_story_5083_50830700_81_dialog_content = "No pierdas la cabeza en la batalla. Prioriza la evacuación y el rescate sobre cualquier otra cosa, ¿entendido?",
  ui_story_5083_50830700_82_dialog_content = "Como si necesitara que me dieras órdenes—Solo espera, Reinhardt. ¡Voy a traer a todos de vuelta!",
  ui_story_5083_50830700_83_dialog_content = "¡Espera, iré contigo! Como vicecomandante, tengo muchos soldados que me seguirán a la batalla.",
  ui_story_5083_50830700_84_dialog_content = "Déjala manejar esto, Barton. He visto su fuerza por mí mismo, y ella es la mejor persona para este tipo de pelea.",
  ui_story_5083_50830700_85_dialog_content = "Subciudad 19 es mucho más grande, lo que significa que tienen una mejor oportunidad de sobrevivir más tiempo.",
  ui_story_5083_50830700_86_dialog_content = "Pero si Subciudad 13 ya ha caído, es casi seguro que el enemigo concentrará sus ataques en Subciudad 19 a continuación.",
  ui_story_5083_50830700_87_dialog_content = "Barton! Puedes ser un idiota, pero te he moldeado en una de las armas más poderosas de Illumina.",
  ui_story_5083_50830700_88_dialog_content = "Una batalla a gran escala como esa te conviene perfectamente a ti y a nuestra División de Infantería Mecanizada.",
  ui_story_5083_50830700_89_dialog_content = "Desafortunadamente, los guardias encargados del almacén de equipo solo toman órdenes del mando más alto, lo que significa que las órdenes falsificadas son completamente inútiles. Tendrás que aprovechar el cambio de turno y hacer que tus soldados roben todo lo que puedan.",
  ui_story_5083_50830700_90_dialog_content = "Espera, ¿estás diciendo que quieres que vayamos primero y aseguremos Subciudad 19 como lo hicimos la última vez?",
  ui_story_5083_50830700_91_dialog_content = "Solo escucha el plan del Comandante Pango, Barton. Liderar a toda la 2.ª Legión fuera de la Ciudad de Gannon no es algo que podamos hacer por nuestra cuenta.",
  ui_story_5083_50830700_92_dialog_content = "¡Ahora apúrate, antes de que tengan la oportunidad de notarlo! Ahorra algo de tiempo usando el ascensor principal para subir!",
  ui_story_5083_50830700_93_dialog_content = "... Solo no dejes que el Comité te atrape antes de que vengas a rescatarnos, anciano.",
  ui_story_5083_50830700_94_dialog_content = "¡Espera! ¿Todos ustedes hablan en serio sobre hacer esto?",
  ui_story_5083_50830700_95_dialog_content = "Comandante, tú y Barton serán marcados como traidores si se van así—¿Realmente estás dispuesto a hacer eso a Illumina? ¿A las personas que te importan?!",
  ui_story_5083_50830700_96_dialog_content = "Insubordinación, falsificación de órdenes y traición abierta... El Gran Mariscal no pasará por alto estos crímenes tan fácilmente.",
  ui_story_5083_50830700_97_dialog_content = "...",
  ui_story_5083_50830700_98_dialog_content = "No me importa nada de eso, Dogg. Solo tengo una pregunta para ti: ¿Vienes o no?",
  ui_story_5083_50830700_99_dialog_content = "Después de todo lo que me dijiste en el museo, ¿me estás diciendo en serio que no quieres salvarlos?",
  ui_story_5083_50830700_100_dialog_content = "¡Por supuesto que quiero salvarlos! Pero...",
  ui_story_5083_50830700_101_dialog_content = "¿Tal vez aún podamos persuadir al Gran Mariscal para que nos ayude? Si solo le cuento todo...",
  ui_story_5083_50830700_102_dialog_content = "¡Detente ahí mismo, Dogg! ¿Quién eres tú para discutir con el Gran Mariscal?",
  ui_story_5083_50830700_103_dialog_content = "Pero sin su aprobación, no podemos actuar sobre esto...",
  ui_story_5083_50830700_104_dialog_content = "Permíteme repetir la pregunta de Barton: ¿Vienes o no?",
  ui_story_5083_50830700_105_dialog_content = "Estaríamos desobedeciendo órdenes sin su consentimiento... Me niego a cometer un crimen tan atroz contra Illumina... Y dejarme a merced del Comité...",
  ui_story_5083_50830700_106_dialog_content = "¡Los verdaderos traidores aquí son el Gran Mariscal y los demás! ¿Cómo podrían simplemente cerrar los ojos mientras nuestros aliados—",
  ui_story_5083_50830700_107_dialog_content = "¡Eso es suficiente, teniente Reinhardt! Soy perfectamente capaz de educar a mis propios subordinados, ¡muchas gracias!",
  ui_story_5083_50830700_108_dialog_content = "Perrito... Entiendo tu dilema, así que solo vuelve al campamento.",
  ui_story_5083_50830700_109_dialog_content = "Una bala mal dirigida no tiene poder de detención, así que no necesitas venir con nosotros. Si aún te sientes culpable por esto, siéntete libre de denunciarnos.",
  ui_story_5083_50830700_110_dialog_content = "¡N-No, Comandante Pango... Tú tienes que ser el que me dé la orden! Iré a cualquier lugar siempre que tú me lo digas—",
  ui_story_5083_50830700_111_dialog_content = "¡No voy a obligarte!",
  ui_story_5083_50830700_112_dialog_content = "No tienes que tener tanto miedo, Dogg; no has hecho nada malo. Pero las cosas no siempre son tan blancas y negras como las leyes de Illumina.",
  ui_story_5083_50830700_113_dialog_content = "Barton. Teniente Reinhardt. Es hora de moverse.",
  ui_story_5083_50830700_114_dialog_content = "Ven si eso es lo que quieres, pero si no puedes tomar esa decisión, simplemente quédate aquí y cubre nuestra ruta de regreso.",
  ui_story_5083_50830700_115_dialog_content = "De cualquier manera, contaremos contigo.",
  ui_story_5083_50830700_116_dialog_content = "Barton, eres un idiota... Intenta no morir antes de que den la orden...",
  ui_story_5083_50830700_117_dialog_content = "<color=#e8d9bb>Reinhardt y Barton aprovechan el cambio de guardia y lideran a su grupo hacia el depósito de equipos, tomando todo lo que pueden antes de que alguien se dé cuenta.</color>",
  ui_story_5083_50830700_118_dialog_content = "<color=#e8d9bb>Cuando los guardias finalmente descubren las acciones de los rebeldes, Barton se ve obligado a cubrir la retaguardia y escoltar el último coche blindado a través de una tormenta de disparos.</color>",
  ui_story_5083_50830700_119_dialog_content = "¡Apúrate! Hemos interrumpido sus comunicaciones. ¡Ahora carga todo en el elevador principal antes de que corten la energía!",
  ui_story_5083_50830700_120_dialog_content = "Uf—Eso estuvo cerca. Definitivamente estaban disparando para matar justo ahora...",
  ui_story_5083_50830700_121_dialog_content = "*Pitido* Bueno, tú sí cometiste el acto más alto de traición, Barton...",
  ui_story_5083_50830700_122_dialog_content = "¿Eh? ¿Cuándo llegaste aquí?",
  ui_story_5083_50830700_123_dialog_content = "Lo siento pequeño, pero acabas de subir a un barco lleno de piratas. Todavía hay tiempo para saltar antes de que el ascensor suba más, ¿sabes?",
  ui_story_5083_50830700_124_dialog_content = "Bip—Barton...",
  ui_story_5083_50830700_125_dialog_content = "Tu Navegante nunca te abandonaría—",
  ui_story_5083_50830801_1_dialog_content = "<color=#e8d9bb>En la noche sin luna, un mar de Eclipsites converge amenazadoramente en la entrada a Subciudad 19.</color>",
  ui_story_5083_50830801_2_dialog_content = "<color=#e8d9bb>Después de días de estar bajo asedio, todos los cañones de corto alcance de la ciudad están sin munición o completamente destruidos. La gente dentro no puede hacer nada más que esperar el final en un silencio impotente.</color>",
  ui_story_5083_50830801_3_dialog_content = "<color=#e8d9bb>En la única entrada a la Subciudad, los soldados de Illumina luchan con uñas y dientes para mantener a los Eclipsites a raya. Sin municiones, recurren a sus espadas; sin espadas, recurren a sus puños.</color>",
  ui_story_5083_50830801_4_dialog_content = "<color=#e8d9bb>Aferrándose a la creencia de que son los escudos de la Federación, luchan sin otro pensamiento en sus mentes salvo el más tenue destello de esperanza.</color>",
  ui_story_5083_50830801_5_dialog_content = "<color=#e8d9bb>\"El mensajero logró salir. La ciudad de Gannon enviará refuerzos pronto.\"</color>",
  ui_story_5083_50830801_6_dialog_content = "<color=#e8d9bb>Después de diez días, ese tenue resplandor había comenzado a tambalearse. Pero justo antes de que pudiera extinguirse, los firmes soldados ven la respuesta a sus oraciones más allá de un mar de sangre y huesos—</color>",
  ui_story_5083_50830801_7_dialog_content = "<size=45>¡Envíalos volando!</size>",
  ui_story_5083_50830801_8_dialog_content = "¡Ahí está nuestra oportunidad! ¡Envía a nuestros luchadores para fortificar esa posición!",
  ui_story_5083_50830801_9_dialog_content = "¡Reponga la munición de todos antes de inspeccionar las defensas de la ciudad! Use cualquier cañón de corto alcance que aún esté operativo y reutilice el resto en cañones de un solo uso!",
  ui_story_5083_50830801_10_dialog_content = "¡Reinhardt! Ve a verificar el estado de la ciudad mientras nosotros mantenemos la entrada!",
  ui_story_5083_50830801_11_dialog_content = "¡Colonia! ¡Trae ese vehículo blindado de transporte aquí!",
  ui_story_5083_50830801_12_dialog_content = "¡Estoy con los refuerzos enviados desde la ciudad de Gannon! ¿Quién está a cargo de esta ciudad ahora mismo?",
  ui_story_5083_50830801_13_dialog_content = "¡Nuestro oficial al mando murió en batalla—Tú puedes transmitirme cualquier información!",
  ui_story_5083_50830801_14_dialog_content = "La División de Infantería Mecanizada estabilizará la situación en la superficie. ¡Toma el resto de tus soldados y comienza a fortificar tus defensas!",
  ui_story_5083_50830801_15_dialog_content = "En cuanto a los civiles que aún están atrapados aquí, carguen cualquier recurso valioso en nuestro vehículo blindado y úsenlo para evacuar de inmediato—",
  ui_story_5083_50830801_16_dialog_content = "¿Pero qué pasa contigo y tus tropas?",
  ui_story_5083_50830801_17_dialog_content = "¡Vamos a quedarnos y defender este lugar hasta que se restablezca la paz!",
  ui_story_5083_50830801_18_dialog_content = "Solo somos el equipo de avanzada, pero no te preocupes; el resto de nuestras fuerzas estarán aquí lo suficientemente pronto.",
  ui_story_5083_50830801_19_dialog_content = "¡Manténganse juntos y no se rindan! ¡Vamos a proteger esta ciudad!",
  ui_story_5083_50830801_20_dialog_content = "<color=#e8d9bb>Mientras la ola de oscuridad continúa su implacable asalto, Barton lidera su batallón de una docena de tanques directamente hacia las fuerzas enemigas, decidido imprudentemente a cambiar las mareas de la batalla.</color>",
  ui_story_5083_50830801_21_dialog_content = "<color=#e8d9bb>Pero frente a números tan abrumadores, su fuerza está lejos de ser suficiente—</color>",
  ui_story_5083_50830801_22_dialog_content = "Maldición, las orugas de nuestro tanque están destrozadas y hay un gigantesco Eclipsite acercándose a nosotros! Lo siento, Vice-comandante Barton—Fue un honor luchar a tu lado, señor!",
  ui_story_5083_50830801_23_dialog_content = "No esperes, estaré allí enseguida—",
  ui_story_5083_50830801_24_dialog_content = "¡Esplendor Illumina!",
  ui_story_5083_50830801_25_dialog_content = "<color=#e8d9bb>El tanque inmovilizado enciende el resto de su munición, resultando en una explosión ardiente que envuelve a todos los Eclipsites en las cercanías.</color>",
  ui_story_5083_50830801_26_dialog_content = "<size=45>¡Come plomo, tú monstruos sucios!!!</size>",
  ui_story_5083_50830801_27_dialog_content = "¡Pon en funcionamiento esas armas de corto alcance y no escatimes en tus disparos! ¡Elimina a tantos como puedas!",
  ui_story_5083_50830801_28_dialog_content = "¡Necesitamos hacerlos retroceder antes de que puedan hacer lo mismo con nosotros!",
  ui_story_5083_50830801_29_dialog_content = "<size=45>¡¡¡Sí, señor!!!</size>",
  ui_story_5083_50830801_30_dialog_content = "¡Informando! Los sistemas de defensa de Subciudad 13 han sido completamente desactivados. Dada la situación actual, estimamos que los Eclipsites violarán el refugio en aproximadamente veinte minutos.",
  ui_story_5083_50830801_31_dialog_content = "Las comunicaciones aún están caídas y nuestro equipo de guerrilla no pudo llegar a los pisos superiores para reparar las líneas. El <color=#FFB400>enorme Eclipsite</color> que nos atacó antes se ha ido, pero la ciudad está llena de Eclipsites más pequeños.",
  ui_story_5083_50830801_32_dialog_content = "Con nuestra estación de energía completamente destruida, lo único que aún funciona es el sistema de autodestrucción oculto de la ciudad...",
  ui_story_5083_50830801_33_dialog_content = "Como soldados, estamos preparados para caer con la ciudad, pero aún hay tantos civiles y recursos dentro del refugio...",
  ui_story_5083_50830801_34_dialog_content = "<color=#e8d9bb>El coronel mira en silencio hacia las alturas de la Subciudad. La oscuridad de arriba solo es interrumpida por las llamas parpadeantes de la destrucción.</color>",
  ui_story_5083_50830801_35_dialog_content = "Los chicos que están llevando a cabo nuestras operaciones de guerrilla no tienen más de diecisiete años... No merecen morir aquí abajo con el resto de nosotros, viejos perros.",
  ui_story_5083_50830801_36_dialog_content = "Este lugar pronto será un nido de Eclipsites... Gannon City no vendrá a salvarnos, pero eso no significa que podamos causarles más problemas. Estoy seguro de que entiendes, señor.",
  ui_story_5083_50830801_37_dialog_content = "... Esperaremos dieciocho minutos más. Si realmente logran violar el refugio, detonaremos toda la ciudad. Al menos, nuestra gente no morirá a manos de los Eclipsites.",
  ui_story_5083_50830801_38_dialog_content = "Las personas allí dentro deben estar aterradas por los sonidos que vienen del otro lado de esa puerta... ¿Realmente estás dispuesto a hacerles pasar dieciocho minutos más de ese sufrimiento?",
  ui_story_5083_50830801_39_dialog_content = "No, les estoy dando dieciocho minutos más de esperanza! Estoy seguro de que algunos de ellos... Todavía piensan que seremos nosotros los que abriremos esa puerta.",
  ui_story_5083_50830801_40_dialog_content = "Qué cruel... Lo siento, señor, pero simplemente no puedo aceptar eso. Como defensores de primera línea de la Ciudad Gannon, estamos destinados a sacrificarnos por el bien de toda Illumina—",
  ui_story_5083_50830801_41_dialog_content = "No quiero que nadie venga a salvarnos si eso significa ponerse en peligro... Pero... ¿Está tan mal creer...",
  ui_story_5083_50830801_42_dialog_content = "¿Que la luz de la esperanza pueda permanecer encendida en nuestra ciudad?",
  ui_story_5083_50830801_43_dialog_content = "¿Alguien copia? Repito, ¿alguien copia?",
  ui_story_5083_50830801_44_dialog_content = "Mi nombre es Teniente Segundo Wrath, y estoy aquí con un equipo de refuerzos de la Ciudad Gannon. Logramos infiltrarnos en los niveles superiores de Subciudad 13 y restaurar las comunicaciones. ¿Hay algún superviviente allí abajo?",
  ui_story_5083_50830801_45_dialog_content = "¡...!",
  ui_story_5083_50830801_46_dialog_content = "¡No, no le respondas! La ciudad está invadida por Eclipsites; ¡nunca saldrán si bajan aquí!",
  ui_story_5083_50830801_47_dialog_content = "¡Sé mejor que nadie que esta ciudad está más allá de la salvación! Antes de mucho tiempo, la Torre Central iba a colapsar, comenzando por la estación de energía; ninguno de nosotros tenía alguna esperanza de escape!",
  ui_story_5083_50830801_48_dialog_content = "¡No dejes que bajen aquí! ¡Activa la secuencia de autodestrucción antes de que este lugar caiga en la oscuridad! Es la única forma de que tengamos alguna esperanza de reconstruir—",
  ui_story_5083_50830801_49_dialog_content = "Puedo escuchar disparos; todavía estás luchando allí abajo, lo que significa que debe haber sobrevivientes en algún lugar. ¿Están en el refugio? ¿Por qué no estás respondiendo?",
  ui_story_5083_50830801_50_dialog_content = "¿Podría ser... Que estás preocupado por que bajemos allí?",
  ui_story_5083_50830801_51_dialog_content = "¿Todavía no hay respuesta, eh? Un montón de viejos tercos... Parece que tendremos que darles una señal.",
  ui_story_5083_50830801_52_dialog_content = "Reinhardt me pidió que viniera contigo para evitar que hagas algo imprudente—¿Te das cuenta de que un movimiento en falso traerá una ciudad entera de Eclipsites sobre nuestras cabezas, verdad?",
  ui_story_5083_50830801_53_dialog_content = "Si la justicia permanece en silencio, la oscuridad nunca puede ser expulsada.",
  ui_story_5083_50830801_54_dialog_content = "¿No puedes sentir su desesperación? ¡Esto es exactamente lo que Reinhardt haría si estuviera aquí!",
  ui_story_5083_50830801_55_dialog_content = "<color=#e8d9bb>Subciudad 13 está condenada—Nadie duda de que esta es una misión sin esperanza.</color>",
  ui_story_5083_50830801_56_dialog_content = "<color=#e8d9bb>Pero en la oscuridad y la desesperación, de repente aparece un faro: un rayo de la ciudad de Gannon que destroza todos los miedos y dudas.</color>",
  ui_story_5083_50830801_57_dialog_content = "<color=#e8d9bb>Wrath frota sus guantes vigorosamente para producir una poderosa explosión de luz y sonido, atrayendo la atención de todos los Eclipsites hacia ella.</color>",
  ui_story_5083_50830801_58_dialog_content = "¿Quién dice que esta ciudad está más allá de la salvación?! ¡Somos su último rayo de esperanza! ¡Su salvación final!",
  ui_story_5083_50830801_59_dialog_content = "¡Ahora escucha! Mi equipo y yo vamos directo al piso inferior, ¡y vamos a eliminar todo lo que se interponga en nuestro camino! ¡Prepara a todos los civiles para evacuar antes de eso!",
  ui_story_5083_50830801_60_dialog_content = "... ¿Quién diablos eres tú? ¿Por qué irías tan lejos por nosotros? ¡No hay forma de que el Gran Mariscal haya aprobado esto!",
  ui_story_5083_50830801_61_dialog_content = "Ya te lo dije, mi nombre es Wrath—¡El futuro Gran Mariscal de Illumina! No dejaré que nadie me impida llevar a cabo mi marca de justicia!",
  ui_story_5083_50830801_62_dialog_content = "<color=#e8d9bb>Wrath lidera la carga contra los Eclipsites que avanzan por la escalera, su espada danzante corta un sangriento camino a través de sus filas. Finalmente, llega al piso inferior de la Subciudad.</color>",
  ui_story_5083_50830801_63_dialog_content = "¿Todos vieron eso? Ese soldado es el futuro de Illumina... El fruto de nuestra dedicación y entrenamiento...",
  ui_story_5083_50830801_64_dialog_content = "Ella es el \"Phospherus\" con el que todos hemos soñado... Su luz... Es absolutamente deslumbrante...",
  ui_story_5083_50830801_65_dialog_content = "Nuestro sueño brilla ante nosotros ahora... ¿Cómo podemos permitir que se apague?",
  ui_story_5083_50830801_66_dialog_content = "... Me aseguraré de que la ruta de evacuación del refugio esté despejada en los próximos diez minutos, incluso si me cuesta la vida.",
  ui_story_5083_50830801_67_dialog_content = "Y yo lideraré un equipo para encontrarme con ella. El resto depende de ti.",
  ui_story_5083_50830801_68_dialog_content = "<color=#FFB400>La luz de Phospherus</color>... No importa lo que pase, tengo que dejar que todos la vean-",
  ui_story_5083_50830801_69_dialog_content = "<color=#e8d9bb>En las afueras de la Subciudad, las llamas de la guerra ardiendo durante tres días seguidos sin señales de refuerzos a la vista.</color>",
  ui_story_5083_50830801_70_dialog_content = "<color=#e8d9bb>Con las municiones agotadas una vez más, los soldados recurrieron nuevamente al combate cuerpo a cuerpo.</color>",
  ui_story_5083_50830801_71_dialog_content = "¡Mantengan la línea! Tenemos que mantener esta posición, ¡o bloquearán la entrada!",
  ui_story_5083_50830801_72_dialog_content = "Rugido-!",
  ui_story_5083_50830801_73_dialog_content = "¡No en mi reloj!",
  ui_story_5083_50830801_74_dialog_content = "Je, el anciano... quiero decir, el Comandante Pango tenía razón! Ser capaz de cambiar instintivamente a un arma cuerpo a cuerpo contra varios Eclipsites es la mejor opción.",
  ui_story_5083_50830801_75_dialog_content = "¿Estás teniendo un momento de realización allí, Barton?",
  ui_story_5083_50830801_76_dialog_content = "No realmente; el viejo comandante me inculcó un cierto reflejo, y solo lo estoy viendo en acción por primera vez. Je, estoy empezando a sentirme como en casa en este tipo de batallas.",
  ui_story_5083_50830801_77_dialog_content = "No podremos mantener esta posición por mucho más tiempo. Te sugiero que tomes un equipo e intentes abrir una ruta de escape a través del enemigo. Es nuestra mejor oportunidad para llevar a estas personas de regreso a Gannon City.",
  ui_story_5083_50830801_78_dialog_content = "¿Y tú? No me digas que te vas a quedar aquí?",
  ui_story_5083_50830801_79_dialog_content = "Les dije que lucharía con ellos hasta el final... Si no podemos defender la Subciudad, la volaremos y nos aseguraremos de que los Eclipsites no puedan usarla de ninguna manera.",
  ui_story_5083_50830801_80_dialog_content = "Eso no va a suceder, Reinhardt! El Comandante Pango dio su palabra de que vendría, ¡y nunca retrocede en su palabra!",
  ui_story_5083_50830801_81_dialog_content = "... No tenemos forma de comunicarnos con nadie fuera de la ciudad, y ninguno de nuestros mensajeros ha regresado. ¿Realmente confías tanto en él, Barton?",
  ui_story_5083_50830801_82_dialog_content = "Puede que sea un idiota, pero el anciano nunca me ha mentido antes... ¡Así que por supuesto que sí! Confío en él igual que confío en ti para cubrirme la espalda!",
  ui_story_5083_50830801_83_dialog_content = "¡Entonces tampoco tengo razón para dudar de él!",
  ui_story_5083_50830801_84_dialog_content = "Hmph. Por el bien de Illumina y todos nuestros camaradas caídos... Me niego a rendirme a estos Eclipsites o huir en desgracia.",
  ui_story_5083_50830801_85_dialog_content = "¡Entonces nos respaldaremos y lucharemos hasta el momento en que toda esperanza se pierda!",
  ui_story_5083_50830801_86_dialog_content = "Se acerca un gran Eclipsite, Reinhardt! ¡C-Creo que podría ser su líder!",
  ui_story_5083_50830801_87_dialog_content = "¡Insignificantes soldados de Illumina, arrodíllense ante mí, el imparable Duskcaller!",
  ui_story_5083_50830801_88_dialog_content = "¿Un Eclipsite capaz de hablar? No se ve eso todos los días... Lo siento amigo, pero mis piernas realmente no se arrodillan. Si eso es un problema, puedes discutirlo con mi espada.",
  ui_story_5083_50830801_89_dialog_content = "No somos del tipo que se rinde, así que ahorra tus palabras. ¡Dejaré que mi Lanza Perforadora de Estrellas te muestre la verdadera luz de Illumina!",
  ui_story_5083_50830801_90_dialog_content = "He visto a Mamá cazando las estrellas del cielo nocturno, atraída por su irresistible voluntad.",
  ui_story_5083_50830801_91_dialog_content = "Ustedes, patéticos Aurorians, apenas sobreviven en la oscuridad del abismo, y aún así se atreven a actuar con tal impunidad.",
  ui_story_5083_50830801_92_dialog_content = "La luz pronto se desvanecerá de este lugar... Y la ciudad de Gannon compartirá un destino similar. La \"verdadera luz de Illumina\" no es más que una farsa...",
  ui_story_5083_50830801_93_dialog_content = "Oye Reinhardt, parece que tenemos un poeta entre nosotros.",
  ui_story_5083_50830801_94_dialog_content = "No importa cuán culto creas que eres... Nunca entenderás, monstruo.",
  ui_story_5083_50830801_95_dialog_content = "Un día, saldremos de estas trincheras y volveremos a un Astra pacífico, ese será nuestro nuevo comienzo y nuestra oportunidad de seguir la luz de nuevo.",
  ui_story_5083_50830801_96_dialog_content = "¡Illumina es el amanecer que atraviesa la noche y anuncia la luz del día! Nuestra fe nos une, ¡y por nuestra fe serás detenido!",
  ui_story_5083_50830801_97_dialog_content = "Todos somos brasas... ¡Las chispas del esplendor de Illumina! Nunca podrías esperar extinguir nuestra luz!",
  ui_story_5083_50830801_98_dialog_content = "¡No podría haberlo dicho mejor! No importa cuántos Eclipsites nos lances, ¡nunca romperás nuestro espíritu!",
  ui_story_5083_50830801_99_dialog_content = "Haré que pagues caro por tu arrogancia, débiles, ¡Ataquen!",
  ui_story_5083_50830801_100_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5083_50830801_101_dialog_content = "<color=#e8d9bb>Un proyectil de artillería conecta repentinamente con el Eclipsite y explota, enviándolo tambaleándose.</color>",
  ui_story_5083_50830801_102_dialog_content = "<color=#e8d9bb>Suena una corneta mientras el sistema de transmisión de emergencia de Subciudad 19 comienza a sonar, señalando la esperada llegada de refuerzos.</color>",
  ui_story_5083_50830801_103_dialog_content = "<color=#e8d9bb>Los soldados vuelven sus rostros empapados de sangre hacia el horizonte. Bañada en luz, aparece una legión entera y comienza a marchar sobre el enemigo.</color>",
  ui_story_5083_50830801_104_dialog_content = "<color=#e8d9bb>La bandera de la segunda legión vuela sobre sus cabezas—Un símbolo del poder de Dawn.</color>",
  ui_story_5083_50830801_105_dialog_content = "Tal impudencia... ¿Cómo te atreves a atacarme, tontos Aurorians! Pagarás con tu sangre—",
  ui_story_5083_50830801_106_dialog_content = "¡Ahora es nuestra oportunidad, Reinhardt! ¡Ataque!",
  ui_story_5083_50830802_1_dialog_content = "¡Fósforo... No! Todos ustedes deben morir aquí! Astra está destinada a un sufrimiento interminable... ¡La noche eterna no se detendrá!",
  ui_story_5083_50830802_2_dialog_content = "Lo siento, pero superar el mal también es el destino de cada héroe en historias como esta.",
  ui_story_5083_50830802_3_dialog_content = "¿He fallado? ¡No! Esto no puede ser—",
  ui_story_5083_50830802_4_dialog_content = "No hay escapatoria a tu destrucción... La campana ha comenzado a sonar... La hora de tu <color=#FFB400>muerte</color> está cerca...",
  ui_story_5083_50830802_5_dialog_content = "Mi hermano... Deberá continuar mi gloriosa obra... ¡Ack! <color=#FFB400>Mamá</color>...",
  ui_story_5083_50830802_6_dialog_content = "¿De qué estaba hablando? Parece que todavía hay otro enemigo difícil esperándonos allá afuera...",
  ui_story_5083_50830802_7_dialog_content = "No estoy completamente seguro... Pero sobrevivimos, y eso es todo lo que importa.",
  ui_story_5083_50830802_8_dialog_content = "Tercera División, ¡pónganse a trabajar en la recuperación de la estación de energía! Restablezcan las comunicaciones y envíen un mensaje de vuelta a Gannon City... No, a cada Subciudad en la Federación!",
  ui_story_5083_50830802_9_dialog_content = "¡Diles que esta ciudad aún puede ser salvada, y que no se rindan con ella!",
  ui_story_5083_50830802_10_dialog_content = "Señor, ¡acabamos de recibir un despacho de emergencia de Subciudad 13! ¡Por favor escúchelo!",
  ui_story_5083_50830802_11_dialog_content = "... Mi Oficial de comunicaciones dice que la Subciudad 19 está a salvo ahora. ¿Fue eso tu obra, Pango?",
  ui_story_5083_50830802_12_dialog_content = "Lo siento, viejo amigo... No pude salvarte yo mismo.",
  ui_story_5083_50830802_13_dialog_content = "Je, guarda tus disculpas. Esta fue la mejor elección posible, ¿no es así? Cuida bien de ese lugar y asegúrate de que no lo perdamos de nuevo.",
  ui_story_5083_50830802_14_dialog_content = "Ese increíble joven oficial... Wrath, si no me equivoco? Ella está liderando a todos fuera del refugio mientras hablamos.",
  ui_story_5083_50830802_15_dialog_content = "¡¿Qué?! Comandante Pango, ¡déjame llevar un equipo allí para ayudarla!",
  ui_story_5083_50830802_16_dialog_content = "¡Él tiene razón! Creo que aún hay esperanza para salvar Subciudad 13—",
  ui_story_5083_50830802_17_dialog_content = "¡Cállense, ustedes dos! ¡Dejen que el hombre termine de hablar!",
  ui_story_5083_50830802_18_dialog_content = "Hemos estado luchando sin descanso durante los últimos quince días... Aparte de mí, el resto de nuestros oficiales ya han caído.",
  ui_story_5083_50830802_19_dialog_content = "Pero escuchar que la Subciudad 19 está segura me tranquiliza el corazón.",
  ui_story_5083_50830802_20_dialog_content = "No estás evacuando, ¿verdad?",
  ui_story_5083_50830802_21_dialog_content = "Subciudad 13 está al borde del colapso y alguien necesita activar la secuencia de autodestrucción... Si se bloquea el camino a Gannon City, también se evitará el colapso.",
  ui_story_5083_50830802_22_dialog_content = "Existe la posibilidad de que esta ciudad sea reconstruida algún día... Así que me quedaré aquí y esperaré hasta que llegue ese día... Sin embargo...",
  ui_story_5083_50830802_23_dialog_content = "... Algunos de tus soldados se niegan a irse, ¿verdad?",
  ui_story_5083_50830802_24_dialog_content = "Je, eso es correcto. Después de todo, entrené a cada uno de ellos para convertirlos en los excelentes soldados que son hoy.",
  ui_story_5083_50830802_25_dialog_content = "Entiendo... Todavía tengo mucho por luchar de mi lado, así que solicito a tus soldados que se unan a mí aquí.",
  ui_story_5083_50830802_26_dialog_content = "Es una orden.",
  ui_story_5083_50830802_27_dialog_content = "Entendido... Ahora están en tus manos, Pango. Promete que los cuidarás bien.",
  ui_story_5083_50830802_28_dialog_content = "Te prometo... Viejo amigo.",
  ui_story_5083_50830802_29_dialog_content = "Este es el adiós, Pango... Recuerda mantenerte muy alejado de esta ciudad.",
  ui_story_5083_50830802_30_dialog_content = "Les daré la orden de evacuar en breve... ¡Esplendor Illumina!",
  ui_story_5083_50830802_31_dialog_content = "Te saludo, camarada... ¡Esplendor Ilumina!",
  ui_story_5083_50830802_32_dialog_content = "¿Qué estás haciendo, Comandante Pango?! Todavía hay gente en la Subciudad 13, ¡lo que significa que todavía hay esperanza para ellos! ¿Por qué le quitarías sus soldados—",
  ui_story_5083_50830802_33_dialog_content = "¡Ahorra tu aliento y ve a descansar un poco! Por la expresión de tu cara, parece que no estás pensando con claridad.",
  ui_story_5083_50830802_34_dialog_content = "Pero...",
  ui_story_5083_50830802_35_dialog_content = "Te di una orden, Barton! Recuerda tu lugar, soldado!",
  ui_story_5083_50830802_36_dialog_content = "... ¡Tch!",
  ui_story_5083_50830802_37_dialog_content = "Quieres salvar a tantos de ellos como puedas, ¿verdad?",
  ui_story_5083_50830802_38_dialog_content = "... Todo lo que siempre quisimos fue construir Illumina. Pero después de todos estos años de lucha, nuestros viejos ojos finalmente están empezando a ponerse un poco borrosos.",
  ui_story_5083_50830802_39_dialog_content = "Jóvenes soldados como tú son los únicos que pueden abrirse camino hasta la luz del amanecer. Tus ojos son más agudos, y también lo son tus mentes...",
  ui_story_5083_50830802_40_dialog_content = "Je, el Gran Mariscal y yo no éramos mucho mayores que tú cuando luchamos en la Guerra de la Zona Oscura.",
  ui_story_5083_50830802_41_dialog_content = "No estoy seguro de cuándo comenzó... Pero de alguna manera, terminamos siendo como las personas que resentíamos en aquel entonces.",
  ui_story_5083_50830802_42_dialog_content = "... ¡Esplendor Ilumina! Te saludo, señor.",
  ui_story_5083_50830802_43_dialog_content = "Ah, solo ve a descansar. Necesito un momento a solas... Para despedir a mi viejo amigo.",
  ui_story_5083_50830802_44_dialog_content = "Bip—Barton... Mis sensores indican que tus ánimos están bajos. Por favor, ven conmigo...",
  ui_story_5083_50830802_45_dialog_content = "¡¿?!",
  ui_story_5083_50830802_46_dialog_content = "¿Todavía vivo, eh? Aunque no pareces exactamente así.",
  ui_story_5083_50830802_47_dialog_content = "¡No te sorprendas tanto! Tu mensajero logró llegar a la ciudad de Gannon, y el Gran Mariscal envió refuerzos inmediatamente una vez que escuchó que la Subciudad 19 estaba asegurada.",
  ui_story_5083_50830802_48_dialog_content = "Solo estamos aquí por nuestras órdenes.",
  ui_story_5083_50830802_49_dialog_content = "... ¿Estás bien?",
  ui_story_5083_50830802_50_dialog_content = "Tú... ¡Idiota! ¿Podrías haber llegado aquí más tarde?!",
  ui_story_5083_50830802_51_dialog_content = "¿Tienes idea de cuánta gente perdimos?! ¡Maldita sea!",
  ui_story_5083_50830802_52_dialog_content = "¿¡Eso es todo lo que tienes que decirme?! Si no hubiera disparado a ese enorme Eclipsite antes, habrías estado acabado, ¡Idiota!",
  ui_story_5083_50830802_53_dialog_content = "¡¡¡Argh-!!!",
  ui_story_5083_50830802_54_dialog_content = "... Entonces, ¿por qué estás tan deprimido, Barton? ¿Es porque... el comandante Barton estaba dispuesto a dejar ir a su amigo así?",
  ui_story_5083_50830802_55_dialog_content = "Subciudad 13 aún podría ser salvada... Podrían estar aquí ahora mismo, ayudándonos a defender este lugar... Pero en cambio, van a hacerla explotar.",
  ui_story_5083_50830802_56_dialog_content = "El anciano incluso tuvo el descaro de llevarse a los soldados más leales de su amigo... Y dejarlo allí para morir solo...",
  ui_story_5083_50830802_57_dialog_content = "¿Preferirías que mueran a su lado?",
  ui_story_5083_50830802_58_dialog_content = "Estoy seguro de que sabes exactamente cómo se sienten... Si estuviéramos en la misma posición, nada nos alejaría del Comandante Pango.",
  ui_story_5083_50830802_59_dialog_content = "Tendrían que rompernos las piernas y encerrarnos en el coche de escape para hacernos salir.",
  ui_story_5083_50830802_60_dialog_content = "...",
  ui_story_5083_50830802_61_dialog_content = "Pero si el Comandante Pango está de acuerdo con su amigo, entonces eso significa que realmente no hay salvación para Subciudad 13.",
  ui_story_5083_50830802_62_dialog_content = "No hay razón para que tantas personas pierdan la vida en la explosión... Al darles una nueva misión, también les está dando una nueva razón para sobrevivir.",
  ui_story_5083_50830802_63_dialog_content = "Ese siempre ha sido uno de los principios rectores de Illumina.",
  ui_story_5083_50830802_64_dialog_content = "Nadie está mintiendo ni dándose la espalda, Barton; Subciudad 19 va a seguir luchando. Piénsalo como... Un acuerdo no expresado entre dos viejos oficiales.",
  ui_story_5083_50830802_65_dialog_content = "Entonces, cuando se les ocurre algo tan ridículo como una \"nueva misión\", es simplemente su forma de proteger a los soldados que entrenaron con todo su corazón.",
  ui_story_5083_50830802_66_dialog_content = "¿Entonces por qué no les preguntas lo que piensan?! Estoy seguro de que ninguno de ellos quiere escuchar a su propio comandante hablar sobre sacrificarse a sí mismo...",
  ui_story_5083_50830802_67_dialog_content = "Es porque son sus niños, Barton. Todos son niños de Illumina.",
  ui_story_5083_50830802_68_dialog_content = "Por eso está dispuesto a llegar tan lejos por ellos...",
  ui_story_5083_50830900_1_dialog_content = "<color=#e8d9bb>Después de varios días de lucha constante, los Eclipsites finalmente comienzan a retirarse de las llanuras, revelando las innumerables cicatrices dejadas en el campo de batalla.</color>",
  ui_story_5083_50830900_2_dialog_content = "<color=#e8d9bb>Subciudad 19 está salvada, pero la 2ª Legión ha perdido más de la mitad de sus tropas.</color>",
  ui_story_5083_50830900_3_dialog_content = "<color=#e8d9bb>Barton se tumba en el suelo junto a sus camaradas caídos, mirando fijamente hacia el sol aparentemente sin calor.</color>",
  ui_story_5083_50830900_4_dialog_content = "Levántate. Es hora de que nos vayamos.",
  ui_story_5083_50830900_5_dialog_content = "¿Comandante Pango?",
  ui_story_5083_50830900_6_dialog_content = "Me gustaría hacer eso... Pero los soldados con los que tomamos esa foto grupal todavía están aquí tumbados, y nunca se van a levantar.",
  ui_story_5083_50830900_7_dialog_content = "Vine aquí para salvar a la gente. No esperaba que tantos de mis camaradas perecieran bajo mi mando...",
  ui_story_5083_50830900_8_dialog_content = "... Aquí.",
  ui_story_5083_50830900_9_dialog_content = "Pesado, ¿no es así? Recuérdalos, Barton; recuerda sus nombres y sus pasados.",
  ui_story_5083_50830900_10_dialog_content = "Como los supervivientes de esta batalla, es nuestro deber seguir adelante.",
  ui_story_5083_50830900_11_dialog_content = "Maldito punk, parece que esta pelea realmente te dejó sin sentido. Pero aún tienes que seguir adelante, incluso si es solo para asegurarte de que sus nombres queden inscritos en ese monumento!",
  ui_story_5083_50830900_12_dialog_content = "¿Crees que no sé eso?! Es solo...",
  ui_story_5083_50830900_13_dialog_content = "¡Sin excusas, Barton! ¡Tenemos la obligación de asegurarnos de que sus sacrificios no fueron en vano! ¿O sus acciones realmente significan tan poco para ti?!",
  ui_story_5083_50830900_14_dialog_content = "... Bien. Ahora que Subciudad 19 está salvada, esta batalla servirá como un mensaje.",
  ui_story_5083_50830900_15_dialog_content = "Este es un mensaje para todas las Subciudades, incluyendo a aquellos que aún están luchando en el frente.",
  ui_story_5083_50830900_16_dialog_content = "Escuchar sobre nuestra victoria aquí hoy fortalecerá la fe de todos... Si Subciudad 19 pudo ser salvada, entonces también pueden serlo cualquiera de las otras Subciudades de Illumina.",
  ui_story_5083_50830900_17_dialog_content = "Algún día, Astra estará libre de los estragos de esta guerra.",
  ui_story_5083_50830900_18_dialog_content = "Pero esa es una conversación para otro momento. Al menos, logramos mantener viva la llama de la esperanza, y eso tiene que significar algo.",
  ui_story_5083_50830900_19_dialog_content = "Incluso si eso significa sacrificar constantemente nuestras almas para avivar sus llamas, todo valdrá la pena al final-",
  ui_story_5083_50830900_20_dialog_content = "Hmph—No tengo la intención de hacer tantos sacrificios una vez que esté a cargo de este barco.",
  ui_story_5083_50830900_21_dialog_content = "Si alguien tiene que arder por el bien de la esperanza, entonces seré yo. Si ese día llega, las llamas van a arder más caliente que nunca antes...",
  ui_story_5083_50830900_22_dialog_content = "<color=#e8d9bb>El mensaje de la salvación de la Subciudad 19 se propaga por Illumina como un incendio. Antes de que los soldados regresen a casa, la ciudad de Gannon ya está llena de noticias sobre su victoria.</color>",
  ui_story_5083_50830900_23_dialog_content = "<color=#e8d9bb>Según el informe oficial, Barton y los demás son aclamados como héroes de élite desplegados por el propio Gran Mariscal.</color>",
  ui_story_5083_50830900_24_dialog_content = "<color=#e8d9bb>A la luz de sus logros sobresalientes, todos los cargos criminales previamente presentados contra ellos se descartan de inmediato—</color>",
  ui_story_5083_50830900_25_dialog_content = "¿Cuál es el credo de Illumina, Pango? ¡Dime ahora mismo!",
  ui_story_5083_50830900_26_dialog_content = "\"Uno para todos, y todos para uno.\"",
  ui_story_5083_50830900_27_dialog_content = "¡No olvides el resto! \"¡Por el bien de Illumina, todas las órdenes deben ser seguidas!\"",
  ui_story_5083_50830900_28_dialog_content = "¡Operas con total desprecio por las órdenes, y enseñas a tus subordinados a hacer lo mismo!",
  ui_story_5083_50830900_29_dialog_content = "¡Si no fuera por la salvación de Subciudad 19, las cosas no habrían terminado casi tan bien para ti o tus soldados!",
  ui_story_5083_50830900_30_dialog_content = "¡Tus subordinados perdieron sus vidas por tu arrogancia!",
  ui_story_5083_50830900_31_dialog_content = "¡No nos consideramos afortunados en absoluto, Gran Mariscal! Sacrificamos tanto para—",
  ui_story_5083_50830900_32_dialog_content = "¡Silencio!",
  ui_story_5083_50830900_33_dialog_content = "¿T-Tu nombre es Barton, verdad? ¿Crees que solo porque eres un héroe puedes hablar fuera de turno?!",
  ui_story_5083_50830900_34_dialog_content = "¡No quiso decir nada con eso, Gran Mariscal! ¡Mi colega aquí es simplemente un idiota!",
  ui_story_5083_50830900_35_dialog_content = "... ¡Y tú! ¿Tienes idea de cuántos problemas has causado al seguir su ejemplo—",
  ui_story_5083_50830900_36_dialog_content = "Perdone la interrupción, Gran Mariscal.",
  ui_story_5083_50830900_37_dialog_content = "¿Un secretario del Comité? ¿Quién te dejó entrar aquí?!",
  ui_story_5083_50830900_38_dialog_content = "Sólo estoy aquí para entregar un mensaje urgente del Comité, señor.",
  ui_story_5083_50830900_39_dialog_content = "Con el éxito de la operación de rescate y la publicidad en torno a sus héroes, la moral dentro de Illumina está en su punto más alto. El Comité está muy satisfecho con las acciones tomadas por estos valientes soldados.",
  ui_story_5083_50830900_40_dialog_content = "¿Contento? ¿Con ellos?! ¡Hah!",
  ui_story_5083_50830900_41_dialog_content = "Particularmente merecedores de elogio son el Teniente Reinhardt... Así como el Capitán Barton. El Comité cree que estos dos soldados deberían ser retratados como modelos a seguir para toda la Federación.",
  ui_story_5083_50830900_42_dialog_content = "Todavía estamos en guerra aquí. ¡Este no es momento para jugar juegos!",
  ui_story_5083_50830900_43_dialog_content = "Es precisamente porque estamos en guerra que el Comité ve la necesidad de tales soldados ejemplares para reforzar el sentimiento público.",
  ui_story_5083_50830900_44_dialog_content = "... ¿Qué es exactamente lo que tu gente tiene en mente?",
  ui_story_5083_50830900_45_dialog_content = "¿Por qué no promover a mi vicecomandante, entonces? Puede que sea un idiota, pero es lo suficientemente hábil para hacerse cargo de toda la División de Infantería Mecanizada.",
  ui_story_5083_50830900_46_dialog_content = "Eso debería ser lo suficientemente fácil de organizar, señor. En cuanto a ti, Teniente Reinhardt, todavía estamos discutiendo una posible recompensa para ti. ¿Serías tan amable de venir conmigo? Ahora mismo, por favor.",
  ui_story_5083_50830900_47_dialog_content = "Lidera el camino.",
  ui_story_5083_50830900_48_dialog_content = "Si no hay nada más, Gran Mariscal, entonces también nos despediremos.",
  ui_story_5083_50830900_49_dialog_content = "... Estás despedido.",
  ui_story_5083_50830900_50_dialog_content = "¡Espera un segundo! Dogg, Comandante Pango... ¿No te pareció que algo estaba mal en esa reunión de ahora mismo?",
  ui_story_5083_50830900_51_dialog_content = "Ese miembro del Comité apenas prestó atención al Gran Mariscal. Fue incluso más grosero con él que yo...",
  ui_story_5083_50830900_52_dialog_content = "¡Diga algo, lo harías? ¡No puedo ser el único que piensa que es extraño! ¡Ni siquiera se molestaron en consultar al Gran Mariscal sobre mi promoción!",
  ui_story_5083_50830900_53_dialog_content = "...",
  ui_story_5083_50830900_54_dialog_content = "Eso no es asunto tuyo, chico.",
  ui_story_5083_50830900_55_dialog_content = "Sé que el Comité tiene mucho poder sobre nosotros, pero—",
  ui_story_5083_50830900_56_dialog_content = "¡Te dije que no es asunto tuyo! No tiene sentido tratar de entender a esas personas, Barton... Ni hablar de ellas, para el caso.",
  ui_story_5083_50830900_57_dialog_content = "Simplemente acepta tu promoción y trabaja duro para entrenar a los nuevos reclutas para la 2ª Legión—",
  ui_story_5083_50830900_58_dialog_content = "Y no permitas que te atrape holgazaneando nunca.",
  ui_story_5083_50831000_1_dialog_content = "¡Oye, Reinhardt! ¿Tienes un segundo para hablar?",
  ui_story_5083_50831000_2_dialog_content = "¿Eres de la 2ª Legión, verdad? ¿Qué te trae aquí en un momento como este? Si estás aquí para buscar una pelea, soy un mejor oponente que Reinhardt.",
  ui_story_5083_50831000_3_dialog_content = "Cálmate Wrath, él no está aquí para empezar nada. El Comandante Barton es un amigo mío.",
  ui_story_5083_50831000_4_dialog_content = "... He estado pensando en ello durante días, pero aún no puedo entenderlo. ¿Por qué te están haciendo esto, Reinhardt? ¡Encima de no promocionarte, tu propio Comandante de la Legión te castigó por salvar Entrañas 19!",
  ui_story_5083_50831000_5_dialog_content = "Hablemos en algún lugar en privado.",
  ui_story_5083_50831000_6_dialog_content = "Voy a ir al grano y preguntar, Reinhardt: ¿cuál es tu conexión con el Comité?",
  ui_story_5083_50831000_7_dialog_content = "No soy estúpido; cualquiera puede ver que estás conectado con ellos de alguna manera, especialmente porque nunca parecen dejarte solo.",
  ui_story_5083_50831000_8_dialog_content = "Cuando ese secretario irrumpió en la sala de reuniones del Gran Mariscal la última vez, en realidad estaba allí por ti, ¿no es así?",
  ui_story_5083_50831000_9_dialog_content = "¿Qué quería él de ti? Y por qué... ¿Por qué no te están protegiendo?",
  ui_story_5083_50831000_10_dialog_content = "Como mi amigo, he estado buscando la oportunidad adecuada para contarte sobre estas cosas, Barton.",
  ui_story_5083_50831000_11_dialog_content = "Para empezar, tienes toda la razón: el Comité me presta una atención especial. En cuanto a la razón... Quizás sea porque me han elegido para algo.",
  ui_story_5083_50831000_12_dialog_content = "No estoy completamente seguro de qué es... Pero parece que tienen un plan de entrenamiento especial en mente para mí, uno que desbloqueará mi potencial de combate completo.",
  ui_story_5083_50831000_13_dialog_content = "Esa podría ser la razón por la que decidieron hacer acto de presencia durante esa reunión.",
  ui_story_5083_50831000_14_dialog_content = "En cuanto a por qué no detuvieron a mi comandante de castigarme... Supongo que probablemente es una advertencia de algún tipo.",
  ui_story_5083_50831000_15_dialog_content = "Una advertencia, ¿eh...? ¿Esto significa que Dogg tenía razón sobre ti? ¿Estás aquí solo porque alguien del comité te está respaldando?",
  ui_story_5083_50831000_16_dialog_content = "¿Eres seriamente ese tipo de persona, Reinhardt?",
  ui_story_5083_50831000_17_dialog_content = "¡Ni siquiera en lo más mínimo! Si acaso, solo soy un peón en el gran esquema de las cosas.",
  ui_story_5083_50831000_18_dialog_content = "Aunque el Comité me está entrenando para ser aún más fuerte... Están igual de preocupados por mantenerme bajo su control.",
  ui_story_5083_50831000_19_dialog_content = "Barton... Si te cuento más de mi historia, acabarás en mi \"barco pirata\" igual que la última vez.",
  ui_story_5083_50831000_20_dialog_content = "¿Estás bien con eso?",
  ui_story_5083_50831000_21_dialog_content = "Confié en ti con mi vida antes, ¿no es así? ¿Por qué diría que no esta vez?",
  ui_story_5083_50831000_22_dialog_content = "A medida que se intensifica la lucha, cada soldado tiene el potencial de convertirse en combustible para las llamas de la victoria... Esto es especialmente cierto para las personas en el Comité.",
  ui_story_5083_50831000_23_dialog_content = "Mi hermana y yo, así como uno de mis amigos, todos somos parte de su plan... Y aunque dicen que solo nos están probando, algo al respecto no se siente bien.",
  ui_story_5083_50831000_24_dialog_content = "No cualquiera puede resistir su entrenamiento especial, especialmente no los niños... Después de pasar por ello yo mismo, sé lo brutal que puede ser.",
  ui_story_5083_50831000_25_dialog_content = "Después de ver todo lo que he visto, no creo que el Gran Mariscal ignore las acciones del Comité... De hecho, creo que las aprueba.",
  ui_story_5083_50831000_26_dialog_content = "No dudo de la convicción del Gran Mariscal hacia la guerra, pero puedo ver el miedo y el agotamiento en sus ojos. La voluntad de seguir luchando no es suficiente para asegurar el futuro, al menos no por sí sola.",
  ui_story_5083_50831000_27_dialog_content = "... Tú una vez me hablaste de tu <color=#FFB400>pequeño sueño</color> de convertirte en el Gran Mariscal algún día.",
  ui_story_5083_50831000_28_dialog_content = "Sigue siendo cierto. ¡Un día, voy a ser el Gran Mariscal más fuerte y decisivo de Illumina!",
  ui_story_5083_50831000_29_dialog_content = "Estoy seguro de que alguien te dijo que no hicieras preguntas sobre el Comité, ¿verdad Barton? Pero la verdad es que Illumina nunca podrá zarpar hasta que nos liberemos de ellos.",
  ui_story_5083_50831000_30_dialog_content = "Je, ¿crees que este barco pirata tuyo es lo suficientemente grande para llevar a todos en Illumina?",
  ui_story_5083_50831000_31_dialog_content = "¿No lo sabías? Incluso un pájaro bebé debe liberarse de su huevo para encontrar su lugar en el mundo. Para dar pasos más grandes hacia adelante, necesitamos liberarnos de nuestras ataduras.",
  ui_story_5083_50831000_32_dialog_content = "Si realmente queremos liberar a todo Astra y comenzar de nuevo... Tenemos que empezar liberando a Illumina de las personas que la controlan desde detrás de escena.",
  ui_story_5083_50831000_33_dialog_content = "Tienes que ser serio si quieres rebelarte contra las fuerzas en el poder.",
  ui_story_5083_50831000_34_dialog_content = "No lograrás nada de eso solo con palabras, Reinhardt. Entonces dime, ¿cómo puedo ayudarte?",
  ui_story_5083_50831000_35_dialog_content = "Al unir fuerzas conmigo y ayudarme a erradicar la corrupción en Illumina.",
  ui_story_5083_50831000_36_dialog_content = "En este momento, los soldados de Illumina están atados por todo tipo de grilletes. Inseguros del significado detrás de sus sacrificios, simplemente viven y luchan, sabiendo que pueden tener que morir por nosotros algún día.",
  ui_story_5083_50831000_37_dialog_content = "Y aquellos que se niegan a luchar son cazados por los <color=#FFB400>Ejecutores</color>. ¿Es esto realmente lo mejor que puede esperar Illumina?",
  ui_story_5083_50831000_38_dialog_content = "No nos dieron una opción cuando llegamos a este mundo, ¡pero nuestra gente debería saber por qué están luchando y muriendo!",
  ui_story_5083_50831000_39_dialog_content = "Y comienza contigo, conmigo y con cada persona que cree en un futuro mejor. Una vez que comencemos por este camino, solo es cuestión de tiempo antes de que Illumina encuentre la verdadera iluminación.",
  ui_story_5083_50831000_40_dialog_content = "Solo entonces podemos esperar salvar todo Astra, y una vez que comencemos de nuevo... Podemos perseguir sueños aún más grandes.",
  ui_story_5083_50831000_41_dialog_content = "Si quieres deshacerte de la corrupción de Illumina, debes estar preparado para el peor resultado posible: otra guerra.",
  ui_story_5083_50831000_42_dialog_content = "Nunca tuve ninguna intención de obedecer a esos viejos indecisos.",
  ui_story_5083_50831000_43_dialog_content = "Dejaré que mi alma se encienda si eso es lo que se necesita para deshacerme de su vil engaño. Mientras ilumine el camino a seguir para todos en Illumina, no tendré arrepentimientos.",
  ui_story_5083_50831000_44_dialog_content = "Casi está garantizado que tendré que enfrentarlos como un <color=#FFB400>traidor</color>, lo que significa que necesitaré todos los aliados que pueda conseguir!",
  ui_story_5083_50831000_45_dialog_content = "¡Ese es el espíritu, Reinhardt! Mientras nunca pierdas de vista esa luz, mi vida siempre estará en tus manos!",
  ui_story_5083_50831000_46_dialog_content = "Ya sea yo o mis soldados, ten la seguridad de que seguiremos cualquier orden que nos des.",
  ui_story_5083_50831000_47_dialog_content = "es solo...",
  ui_story_5083_50831000_48_dialog_content = "¿Sólo qué?",
  ui_story_5083_50831000_49_dialog_content = "Je... ¡Jajajaja! Es solo que después de ser degradado tanto, tienes un largo camino por delante si quieres convertirte en Gran Mariscal!",
  ui_story_5083_50831000_50_dialog_content = "¡Así que más vale que tengas cuidado, o podría adelantarme y hacerlo yo!",
  ui_story_5083_50831000_51_dialog_content = "Seguro que te felicitaré de todo corazón si te conviertes en Gran Mariscal primero.",
  ui_story_5083_50831000_52_dialog_content = "Aunque supongo que la posición en sí no es lo que es importante.",
  ui_story_5083_50831000_53_dialog_content = "Si, tienes razón.",
  ui_story_5083_50831000_54_dialog_content = "Hay otra cosa: realmente no quiero ocultar nada de esto al Comandante Pango, dado que prácticamente me crió.",
  ui_story_5083_50831000_55_dialog_content = "Necesitamos todos los amigos que podamos conseguir, ¿verdad? Además... Lo último que quiero es hacer un enemigo de él.",
  ui_story_5083_50831000_56_dialog_content = "No te preocupes, puedes contarle todo lo que hablamos aquí.",
  ui_story_5083_50831000_57_dialog_content = "Confías en mí con tu vida; solo es justo que haga lo mismo por ti.",
  ui_story_5083_50831000_58_dialog_content = "Creo en tu juicio, así como en las personas en las que más confías.",
  ui_story_5083_50831000_59_dialog_content = "¿Entonces qué estamos esperando? ¿Por qué no reunimos a todos y hablamos las cosas?",
  ui_story_5083_50831000_60_dialog_content = "Escucho que el comedor está ofreciendo una nueva comida sabrosa. Llamemos a todos al Área de Asignación y hablemos.",
  ui_story_5083_50831000_61_dialog_content = "<size=45>¡Me parece bien!</size>",
  ui_story_5083_50831100_1_dialog_content = "Pedí a mis amigos que llamaran a algunas personas que podrían simpatizar con nuestra causa. Ayudaría si pudiéramos conseguir que Denier se uniera a nosotros también... Pero por ahora, simplemente vayamos allí.",
  ui_story_5083_50831100_2_dialog_content = "¿Quizás debería regresar primero al campamento? De esa manera, puedo hacer que Dogg y el anciano también vengan.",
  ui_story_5083_50831100_3_dialog_content = "No te preocupes, mis amigos pasarán el mensaje a Dogg si lo ven. En cuanto al Comandante Pango, podría sentirse un poco incómodo en una sala llena de soldados jóvenes y potencialmente rebeldes.",
  ui_story_5083_50831100_4_dialog_content = "Y después de ponerme en su contra tantas veces, creo que debería estar más preparado antes de acercarme a él sobre esto.",
  ui_story_5083_50831100_5_dialog_content = "¡Ja! Entonces, ¿también le temes al anciano, eh?",
  ui_story_5083_50831100_6_dialog_content = "¡S-Solo mantén tu voz baja y sígueme!",
  ui_story_5083_50831100_7_dialog_content = "Por cierto, ¿hay algo que te gustaría comer? ¿O tal vez un pasatiempo o interés?",
  ui_story_5083_50831100_8_dialog_content = "Puedes pasar el rato hasta que todos se encuentren. Iré a buscarnos una mesa en la cafetería.",
  ui_story_5083_50831100_9_dialog_content = "No. ¿Por qué correría si no hay guerra?",
  ui_story_5083_50831100_10_dialog_content = "Entonces, ¿qué haces en tu tiempo libre en la base?",
  ui_story_5083_50831100_11_dialog_content = "Quedarse en el cuartel o hacer mis propios ejercicios.",
  ui_story_5083_50831100_12_dialog_content = "¿Qué? Eso es bastante patético.",
  ui_story_5083_50831100_13_dialog_content = "¡No, no lo es! De todos modos, no tenemos nada mejor que hacer mientras tanto.",
  ui_story_5083_50831100_14_dialog_content = "Por no mencionar que es un desastre a donde quiera que vayas con la guerra en curso.",
  ui_story_5083_50831100_15_dialog_content = "Al menos pasaría el rato con las chicas en mi tiempo libre, pero pareces ser un casero como Gronru.",
  ui_story_5083_50831100_16_dialog_content = "Eso no es 100% cierto. También me mantengo al día con la última tendencia.",
  ui_story_5083_50831100_17_dialog_content = "Incluso sé dónde está el patio de juegos secreto cercano.",
  ui_story_5083_50831100_18_dialog_content = "Está bien, tú ve a pasar el rato mientras yo voy a agarrar una mesa y recoger a Helios y a los demás en el camino.",
  ui_story_5083_50831100_19_dialog_content = "Oh, por cierto, Helios es mi amigo de la infancia. Él es muy agradable, y tú dos definitivamente se llevarán bien.",
  ui_story_5083_50831100_20_dialog_content = "No tengo idea de a dónde ir, mucho menos dónde pasar el rato...",
  ui_story_5083_50831100_21_dialog_content = "Habría vuelto a la base y habría avisado a Dogg si lo hubiera sabido.",
  ui_story_5083_50831100_22_dialog_content = "Beep—Por favor, intenta disfrutar de tu tiempo libre, Barton.",
  ui_story_5083_50831100_23_dialog_content = "Ni siquiera sé a dónde voy, así que supongo que el \"patio de juegos secreto\" de Gronru es mi única opción.",
  ui_story_5083_50831100_24_dialog_content = "¿Alguien como Gronru estaría interesado en algo así, sin embargo?",
  ui_story_5083_50831100_25_dialog_content = "Ella es del tipo que diría: \"Vaya, el futuro de Illumina. Qué aburrido. Me voy a casa a jugar juegos.\"",
  ui_story_5083_50831100_26_dialog_content = "¿Qué haces vagando fuera de mi arcade secreto? ¿Buscas pelear con el Rey Naval de nuevo?",
  ui_story_5083_50831100_27_dialog_content = "Eso salió de la nada... Hey, ¿dónde fue mi dron? ¿Huyó de nuevo? ¿Qué tan tímido puede ser?",
  ui_story_5083_50831100_28_dialog_content = "Tengo una fiesta a la que invitarte. ¿No te lo dijo Reinhardt? Nos reuniremos en la cafetería para discutir algunas cosas.",
  ui_story_5083_50831100_29_dialog_content = "¿Fiesta? No he oído hablar de ella... Suena divertido y quiero ir!",
  ui_story_5083_50831100_30_dialog_content = "Ten cuidado de no ser engañado de nuevo. Puede que no salgas de ello.",
  ui_story_5083_50831100_31_dialog_content = "Casi estamos allí. ¿Hay algo que te gustaría comer?",
  ui_story_5083_50831100_32_dialog_content = "Es obvio que no tienes idea de lo que es sabroso o no, Barton.",
  ui_story_5083_50831100_33_dialog_content = "No tengo tiempo para ser exigente. Illumina estaría en grandes problemas si nosotros, los soldados, comenzamos a odiar las raciones militares.",
  ui_story_5083_50831100_34_dialog_content = "Nos esforzamos por mejorar la comida aquí, solo para complacer las papilas gustativas en el frente.",
  ui_story_5083_50831100_35_dialog_content = "Como el Pescado a la Parrilla Deshidratado de Umbraton y las barras de energía de chocolate. ¡Lo sabrás cuando lo pruebes!",
  ui_story_5083_50831100_36_dialog_content = "Es sabroso, pero te lo devoraste, Barton. ¿Vas a tener espacio para más tarde?",
  ui_story_5083_50831100_37_dialog_content = "*Munch, munch* Mi apetito es más grande de lo normal. Eso es un requisito para ser un buen soldado.",
  ui_story_5083_50831100_38_dialog_content = "Supongo que si ganas la próxima vez, te enviaré a probar los nuevos productos por mí y me ahorraré un viaje.",
  ui_story_5083_50831100_39_dialog_content = "Oye, ¿qué estás haciendo allí, Barton?",
  ui_story_5083_50831100_40_dialog_content = "Fui enviado a buscarte... ¿Qué está pasando? ¡Te estás atiborrando!",
  ui_story_5083_50831100_41_dialog_content = "¡No importa eso y prueba esta galleta de cereza deshidratada!",
  ui_story_5083_50831100_42_dialog_content = "¿Qué? No, gracias. Creo que podría llenarme con solo un bocado.",
  ui_story_5083_50831100_43_dialog_content = "Vamos, pruébalo. Es realmente bueno.",
  ui_story_5083_50831100_44_dialog_content = "Estoy aquí por negocios, así que quita eso... ¡No puedo creer que no lo estés tomando en serio!",
  ui_story_5083_50831100_45_dialog_content = "En realidad no está mal.",
  ui_story_5083_50831100_46_dialog_content = "Dame otro.",
  ui_story_5083_50831100_47_dialog_content = "¡Tómalo con calma o estarás demasiado lleno para más tarde! Ven, vamos a ver a Reinhardt.",
  ui_story_5083_50831100_48_dialog_content = "¿Qué están haciendo chicos...?",
  ui_story_5083_50831100_49_dialog_content = "¡Algo divertido! Y tú estás en ello. No intentes escapar después de comer.",
  ui_story_5083_50831100_50_dialog_content = "¡Aquí! Encontré un lugar en el rincón. ¡Ven rápido!",
  ui_story_5083_50831100_51_dialog_content = "Oh, aprendí muchas cosas nuevas, así que estaremos entrenando pronto.",
  ui_story_5083_50831100_52_dialog_content = "¿En serio?",
  ui_story_5083_50831100_53_dialog_content = "Hola, mi nombre es Helios. Gracias por llevar a Reinhardt a casa de manera segura.",
  ui_story_5083_50831100_54_dialog_content = "Soy Barton. Este aquí es Dogg. Puedes cortar las formalidades. Después de todo, somos Illumina.",
  ui_story_5083_50831100_55_dialog_content = "Por no mencionar que Reinhardt también me ayudó bastante.",
  ui_story_5083_50831100_56_dialog_content = "¡Tenemos un problema! El negador está atrapado en la multitud luchando por comida y no puede salir. ¡Necesito que dos personas vengan conmigo!",
  ui_story_5083_50831100_57_dialog_content = "¿Qué pasa con el alboroto?",
  ui_story_5083_50831100_58_dialog_content = "No estabas bromeando acerca de no prestar atención a la comida, veo. Las nuevas ofertas son una prioridad para el frente, por lo que Gannon solo recibe el exceso.",
  ui_story_5083_50831100_59_dialog_content = "Se dice que son extremadamente deliciosos, por lo que las peleas no son raras.",
  ui_story_5083_50831100_60_dialog_content = "¡Tengo que ir a ayudarla!",
  ui_story_5083_50831100_61_dialog_content = "De verdad, Reinhardt, ¿reuniste a todos solo para luchar por comida en la cafetería?",
  ui_story_5083_50831100_62_dialog_content = "¡Es una gran mancha en el honor de la Legión si ni siquiera podemos asegurar una comida! ¡Todos, síganme a la batalla! Excepto por Reinhardt.",
  ui_story_5083_50831100_63_dialog_content = "¡Ah, joven y entusiasta, veo!",
  ui_story_5083_50831100_64_dialog_content = "Entonces, ¿simplemente esperamos aquí?",
  ui_story_5083_50831100_65_dialog_content = "No creo que debamos involucrarnos.",
  ui_story_5083_50831100_66_dialog_content = "¡Negador te consiguió tu pudín favorito, Gronru!",
  ui_story_5083_50831100_67_dialog_content = "¿En serio? Bien, déjame prepararme para una incursión!",
  ui_story_5083_50831100_68_dialog_content = "Calor, calor... Había tanta gente que ni siquiera pude conseguir una bandeja.",
  ui_story_5083_50831100_69_dialog_content = "Déjame ayudarte... ¡Ay!",
  ui_story_5083_50831100_70_dialog_content = "Te dije que hace calor.",
  ui_story_5083_50831100_71_dialog_content = "¡Fuera de mi camino! Mira, Barton, conseguí el doble de lo que tú conseguiste.",
  ui_story_5083_50831100_72_dialog_content = "¿De dónde sacaste esa bandeja?",
  ui_story_5083_50831100_73_dialog_content = "Esto es lo que significa ser la élite de la élite y el comandante de comandos.",
  ui_story_5083_50831100_74_dialog_content = "Todavía no pude sacar a Negador de allí, pero conseguí suficiente para todos nosotros.",
  ui_story_5083_50831100_75_dialog_content = "¡Aquí vienen las bebidas! ¡Un imprescindible para esta ocasión!",
  ui_story_5083_50831100_76_dialog_content = "¿Qué tal un concurso?",
  ui_story_5083_50831100_77_dialog_content = "¡Acepto!",
  ui_story_5083_50831100_78_dialog_content = "¿Olvidaste algo, Reinhardt?",
  ui_story_5083_50831100_79_dialog_content = "Oh, Negador, Gronru y Vaughn todavía están forcejeando junto a los dulces.",
  ui_story_5083_50831100_80_dialog_content = "Hay una gran multitud para esos, así que vamos a tener una ronda mientras esperamos.",
  ui_story_5083_50831100_81_dialog_content = "Debería ver cómo están.",
  ui_story_5083_50831100_82_dialog_content = "No tengas tanta prisa. Reinhardt dijo que tenemos tiempo para una ronda.",
  ui_story_5083_50831100_83_dialog_content = "Supongo que está bien. Tenemos el tiempo.",
  ui_story_5083_50831100_84_dialog_content = "Bueno entonces, ¿salud?",
  ui_story_5083_50831100_85_dialog_content = "¡Salud!",
  ui_story_5083_50831100_86_dialog_content = "<color=#e8d9bb>La Generación más Brillante de Illumina realiza su primera reunión en un rincón con risas.</color>",
  ui_story_5083_50831100_87_dialog_content = "<color=#e8d9bb>Simplemente no puedo apartar mis ojos de la festividad. Quiero capturar este momento, incluso si es efímero.</color>",
  ui_story_5083_50831100_88_dialog_content = "¿Qué tal una canción? Muestra la canción de pelea que escribiste, Perro.",
  ui_story_5083_50831100_89_dialog_content = "¡Suéltame, tonto, y cántalo tú mismo!",
  ui_story_5083_50831100_90_dialog_content = "Seguro que se están tomando su tiempo...",
  ui_story_5083_50831100_91_dialog_content = "No te preocupes por tu hermana. Ella es lo suficientemente mayor como para no perderse.",
  ui_story_5083_50831100_92_dialog_content = "¡Entonces brindemos otra vez por nuestra increíble asociación!",
  ui_story_5083_50831100_93_dialog_content = "¿De qué increíble asociación estás hablando?",
  ui_story_5083_50831100_94_dialog_content = "No tiene sentido apartarse, ¡porque aquí viene!",
  ui_story_5083_50831100_95_dialog_content = "<size=45>¡Salud!</size>",
  ui_story_5083_50831200_1_dialog_content = "...",
  ui_story_5083_50831200_2_dialog_content = "Para ser honesto, no pensé que podrías engañarnos.",
  ui_story_5083_50831200_3_dialog_content = "Tonto, Barton. ¿Te das cuenta de lo que estás diciendo?",
  ui_story_5083_50831200_4_dialog_content = "Creo que me he explicado muy claramente... ¡Y tengo fe en Reinhardt!",
  ui_story_5083_50831200_5_dialog_content = "Se ha vuelto loca.",
  ui_story_5083_50831200_6_dialog_content = "Cálmate, Barton. Ella ha sido relegada al rango más bajo.",
  ui_story_5083_50831200_7_dialog_content = "Entonces, tal vez ella te está utilizando, o incluso a nosotros, la segunda legión.",
  ui_story_5083_50831200_8_dialog_content = "Defendí Subciudad 19 durante días con ella.",
  ui_story_5083_50831200_9_dialog_content = "Ella moriría por ellos, ¿entonces cómo podría ser mala?",
  ui_story_5083_50831200_10_dialog_content = "Ella lo haría, ¿verdad?",
  ui_story_5083_50831200_11_dialog_content = "Quizás el Illumina actual no sea para tanto, y muchos de los problemas no se puedan resolver fácilmente, pero...",
  ui_story_5083_50831200_12_dialog_content = "Cumplir tus objetivos significa que debes enfrentarte al Gran Mariscal y a tus amigos.",
  ui_story_5083_50831200_13_dialog_content = "No estoy de acuerdo, no mientras aún estemos luchando contra los Eclipsites.",
  ui_story_5083_50831200_14_dialog_content = "¡Nunca daré mi consentimiento a eso!",
  ui_story_5083_50831200_15_dialog_content = "He luchado por Illumina toda mi vida. Veo a todos como mi propia sangre.",
  ui_story_5083_50831200_16_dialog_content = "¡No toleraré ninguna traición y nunca te ayudaré!",
  ui_story_5083_50831200_17_dialog_content = "Ya veo. Pensé que no lo verías así.",
  ui_story_5083_50831200_18_dialog_content = "Pero creo que puedes entender de dónde vengo.",
  ui_story_5083_50831200_19_dialog_content = "No aspiramos a ser otro Lumopolis. Solo queremos ser el pilar que sostiene a Illumina.",
  ui_story_5083_50831200_20_dialog_content = "Los cambios solo vienen después de eso...",
  ui_story_5083_50831200_21_dialog_content = "¡Basta! ¡No quiero oír más!",
  ui_story_5083_50831200_22_dialog_content = "...",
  ui_story_5083_50831200_23_dialog_content = "Te entrené y creo en mi juicio.",
  ui_story_5083_50831200_24_dialog_content = "Creo que puedes confiar en Reinhardt con tu vida.",
  ui_story_5083_50831200_25_dialog_content = "Pero incluso si sucede lo peor, no quiero pelear con viejos camaradas... y no quiero tener que matarte, Barton.",
  ui_story_5083_50831200_26_dialog_content = "No te entrené para luchar contra Illumina, ni contra ningún Aurorian, para el caso.",
  ui_story_5083_50831200_27_dialog_content = "¡Eso tampoco es lo que queremos! Solo creemos en la justicia y en luchar por el futuro...",
  ui_story_5083_50831200_28_dialog_content = "Sigue hablando y te encerraré en una celda yo mismo.",
  ui_story_5083_50831200_29_dialog_content = "Tómalo con calma, Barton. Aún no estás seguro de qué hacer.",
  ui_story_5083_50831200_30_dialog_content = "Tómate tu tiempo y piénsalo bien.",
  ui_story_5083_50831200_31_dialog_content = "¿Tómate tu tiempo y piénsalo? ¿Realmente quieres decir que siga aguantando esta tontería, verdad?",
  ui_story_5083_50831200_32_dialog_content = "He sido promovido a teniente coronel y soy un comandante de batallón. No pensé que todavía tendría que entrenar a novatos.",
  ui_story_5083_50831200_33_dialog_content = "Cualquier sargento instructor podría hacer eso. ¡Donde debería estar es en el frente!",
  ui_story_5083_50831200_34_dialog_content = "Y las sesiones de fotos para el Comité... No soy ningún supermodelo.",
  ui_story_5083_50831200_35_dialog_content = "¿Por qué no pueden prestar atención a los verdaderos héroes allá adelante? ¡Estoy perdiendo mi tiempo hablando de lo seguro que es aquí atrás!",
  ui_story_5083_50831200_36_dialog_content = "Todavía es demasiado temprano para ti.",
  ui_story_5083_50831200_37_dialog_content = "¿Qué quieres decir?",
  ui_story_5083_50831200_38_dialog_content = "Solo cuando los aliados te ayuden en el futuro puedes llegar a ser...",
  ui_story_5083_50831200_39_dialog_content = "Bip—Al menos Barton no ha sido castigado.",
  ui_story_5083_50831200_40_dialog_content = "Oh, ¿cómo se me pudo olvidar eso?",
  ui_story_5083_50831200_41_dialog_content = "Debería hablar con mis amigos en lugar de divagar solo.",
  ui_story_5083_50831200_42_dialog_content = "Lástima que Dogg no viera las cosas desde mi punto de vista.",
  ui_story_5083_50831200_43_dialog_content = "No importa, pude ver a Reinhardt. ¿Sabes dónde está ella?",
  ui_story_5083_50831200_44_dialog_content = "Bip—Sígueme, Barton.",
  ui_story_5083_50831200_45_dialog_content = "Esta es la tienda de Gronru... Pero ella es cercana con esos dos, así que debería saber dónde está Reinhardt.",
  ui_story_5083_50831200_46_dialog_content = "¿A quién estás hablando? Ella no está. Estoy a cargo mientras ella no está, así que dime tu negocio.",
  ui_story_5083_50831200_47_dialog_content = "Dime, ¿no se supone que debes estar en la base, Propaganda para Illumina?",
  ui_story_5083_50831200_48_dialog_content = "Me escabullí.",
  ui_story_5083_50831200_49_dialog_content = "Pero no importa eso. ¿Dónde está Reinhardt? ¿A dónde fue ella?",
  ui_story_5083_50831200_50_dialog_content = "Haciendo sus ejercicios especiales y soñando con ser la Gran Mariscal.",
  ui_story_5083_50831200_51_dialog_content = "¿No estás en buenos términos? ¿Cómo es que desapruebas tanto de ella?",
  ui_story_5083_50831200_52_dialog_content = "¿Quién sabe?",
  ui_story_5083_50831200_53_dialog_content = "Quizás mi hermana mayor ya no puede relacionarse conmigo...",
  ui_story_5083_50831200_54_dialog_content = "Aunque me hayas vencido en una simulación, tengo un consejo para ti.",
  ui_story_5083_50831200_55_dialog_content = "Nunca puedes ser Reinhardt. No eres el mismo.",
  ui_story_5083_50831200_56_dialog_content = "Cualquier cosa con la que no te sientas cómodo, deberías dejárselo claro a tu querida hermana.",
  ui_story_5083_50831200_57_dialog_content = "Siempre ha cuidado de ti... No guardes las cosas adentro o nadie lo sabrá.",
  ui_story_5083_50831200_58_dialog_content = "Entonces, ¿qué quieres con ella?",
  ui_story_5083_50831200_59_dialog_content = "No te preocupes por eso. No puedo hablar con ella si no está cerca. Solo déjale saber que pasé.",
  ui_story_5083_50831200_60_dialog_content = "Seguro.",
  ui_story_5083_50831200_61_dialog_content = "<color=#e8d9bb>Las palabras del negador tranquilizaron a Barton. Regresó a la base y reanudó sus tareas para el Comité después de la acción disciplinaria.</color>",
  ui_story_5083_50831200_62_dialog_content = "<color=#e8d9bb>Pero él nunca recibió una respuesta...</color>",
  ui_story_5083_50831200_63_dialog_content = "<color=#e8d9bb>La ciudad de Gannon anunció una grave explosión de laboratorio con Reinhardt, su equipo, y Gronru desaparecidos en acción.</color>",
  ui_story_5083_50831301_1_dialog_content = "<color=#e8d9bb>Es primavera de nuevo, pero la Crisis de Darkover continúa. Nadie sabe de dónde vienen los Eclipsites y por qué siguen aumentando en número.</color>",
  ui_story_5083_50831301_2_dialog_content = "<color=#e8d9bb>Todavía corren desenfrenados en Astra y matan vidas, lo cual es suficiente para hacer que todos luchen hasta el final.</color>",
  ui_story_5083_50831301_3_dialog_content = "<color=#e8d9bb>En la guerra en escalada, un mensaje urgente llega a Gannon, indicando avistamientos de Eclipsites cerca de la defensa de la ciudad.</color>",
  ui_story_5083_50831301_4_dialog_content = "¿Qué está pasando? Subciudad 13 se ha autodestruido y hemos sellado todos los accesos a la superficie desde allí.",
  ui_story_5083_50831301_5_dialog_content = "Subciudad 19 sigue operativa. No solicitaron asistencia, así que probablemente mantuvieron el paso.",
  ui_story_5083_50831301_6_dialog_content = "Todas las subciudades a lo largo de la línea siguen operativas. No se informó de ninguna brecha.",
  ui_story_5083_50831301_7_dialog_content = "Quizás solo sean Eclipsites sueltos que vienen por las montañas o que surgen de ruinas subterráneas como antes.",
  ui_story_5083_50831301_8_dialog_content = "Sí, pero asegúrate de que todos sean exterminados con extremo prejuicio, sin embargo.",
  ui_story_5083_50831301_9_dialog_content = "Envía un equipo más para rastrear la fuente.",
  ui_story_5083_50831301_10_dialog_content = "La guerra es intensa en este momento. Probablemente la 1ra Legión en defensa perimetral no tiene soldados para ahorrar.",
  ui_story_5083_50831301_11_dialog_content = "Los Eclipsites no aparecen de la nada. ¡La complacencia solo nos matará!",
  ui_story_5083_50831301_12_dialog_content = "Si la Legión no puede enviar a nadie, lo manejaremos nosotros mismos.",
  ui_story_5083_50831301_13_dialog_content = "Todavía tengo dos batallones enteros bajo mi mando. Esta será su oportunidad para demostrar su fuerza.",
  ui_story_5083_50831301_14_dialog_content = "Tienes razón. No podemos permitirnos perder nada en la guerra.",
  ui_story_5083_50831301_15_dialog_content = "Lo siento, pero parece que has olvidado que estoy aquí. El Comandante Barton y sus hombres deben seguir las asignaciones del comité. Esa es una prioridad.",
  ui_story_5083_50831301_16_dialog_content = "Estoy haciendo una solicitud al Gran Mariscal. No tiene nada que ver contigo.",
  ui_story_5083_50831301_17_dialog_content = "Perdóneme, pero es mi trabajo entregar el mensaje e informar todo de vuelta al Comité, incluyendo sus reuniones.",
  ui_story_5083_50831301_18_dialog_content = "¡Escucha tú, somos los que defendemos a Gannon aquí, así que cálmate!",
  ui_story_5083_50831301_19_dialog_content = "Dado que Barton y Dogg todavía tienen que hacer propaganda para el Comité, quizás no deberían abandonar la ciudad.",
  ui_story_5083_50831301_20_dialog_content = "Quizás puedas tomar este, Pango, con tu equipo y uno de los batallones.",
  ui_story_5083_50831301_21_dialog_content = "Claro, pero no tiene sentido que mi segundo al mando muriera en combate mientras estos dos buenos y jóvenes soldados están aquí haciendo trabajo de oficina!",
  ui_story_5083_50831301_22_dialog_content = "Ya te di una charla sobre las consecuencias, Pango.",
  ui_story_5083_50831301_23_dialog_content = "Lleva a Dogg contigo. Aprobé su solicitud de alistamiento personalmente, así que asumiré toda la responsabilidad.",
  ui_story_5083_50831301_24_dialog_content = "Es mi orden y puedes citarme, Secretario del Comité.",
  ui_story_5083_50831301_25_dialog_content = "Es lo que es. Simplemente no puedo soportar no averiguar de dónde vienen los Eclipsites.",
  ui_story_5083_50831301_26_dialog_content = "Mantente atrás y entrena a los soldados esta vez, Barton.",
  ui_story_5083_50831301_27_dialog_content = "De ninguna manera, tengo un mal presentimiento sobre esto.",
  ui_story_5083_50831301_28_dialog_content = "Como los Escudos Gemelos, las dos subciudades cumplieron su propósito, entonces, ¿por qué los Eclipsites están apareciendo alrededor de Gannon ahora?",
  ui_story_5083_50831301_29_dialog_content = "Eso era común antes, y ahora están más cerca solo porque la 1ra Legión está demasiado extendida debido a la intensa campaña.",
  ui_story_5083_50831301_30_dialog_content = "¿Estás seguro de que no es un problema?",
  ui_story_5083_50831301_31_dialog_content = "No me han dejado salir de Gannon ni participar en ninguna operación durante mucho tiempo, sin embargo, te envían a la feroz batalla.",
  ui_story_5083_50831301_32_dialog_content = "Incluso estoy empezando a dudar del Gran Mariscal...",
  ui_story_5083_50831301_33_dialog_content = "¡Cállate! ¿Tu cerebro ha dejado de funcionar por estar encerrado, e incluso has olvidado nuestro principio?",
  ui_story_5083_50831301_34_dialog_content = "¡Tus ojos están llenos de ira y desafío! ¿Han apagado hasta el último hilo de honor en ti?!",
  ui_story_5083_50831301_35_dialog_content = "¡Ven aquí, punk!",
  ui_story_5083_50831301_36_dialog_content = "¡Mira esa luz allá! La Torre Central nunca ha disminuido. Creciste bajo esa luz, ¡así que la vigilas con tu vida!",
  ui_story_5083_50831301_37_dialog_content = "No me importa qué problemas tengas con los superiores, pero recuerda esto: siempre eres Illumina.",
  ui_story_5083_50831301_38_dialog_content = "Solo estaba preocupado por ti...",
  ui_story_5083_50831301_39_dialog_content = "Entonces dedícate a la causa y no proyectes tus problemas personales en Illumina.",
  ui_story_5083_50831301_40_dialog_content = "El Gran Mariscal puede parecer agitado o incluso débil, pero no es del tipo que traiciona a sus aliados.",
  ui_story_5083_50831301_41_dialog_content = "¡No toleraré otra ofensa a nuestros soldados de tu parte otra vez!",
  ui_story_5083_50831301_42_dialog_content = "¡Pero al menos llévame contigo! Simplemente no puedo soltarme, así que déjame...",
  ui_story_5083_50831301_43_dialog_content = "Olvídalo, Barton. Estoy seguro de que eso ya se ha intentado.",
  ui_story_5083_50831301_44_dialog_content = "No te preocupes, te cubro la espalda. Si ocurre una pelea, pediré refuerzos de inmediato y te llamaré por tu nombre.",
  ui_story_5083_50831301_45_dialog_content = "De esa manera, ya no podrán retenerte más.",
  ui_story_5083_50831301_46_dialog_content = "...",
  ui_story_5083_50831301_47_dialog_content = "Soy igual de bueno, así que no hay razón para no confiar en mí, ¿verdad?",
  ui_story_5083_50831301_48_dialog_content = "Solo espera, Barton. Nunca seré un segundo violín. Será mejor que cambies tus formas arrogantes.",
  ui_story_5083_50831301_49_dialog_content = "¡Maldiciones! Realmente me molesta, como si algo terrible estuviera a punto de suceder.",
  ui_story_5083_50831301_50_dialog_content = "¿Por qué me estoy poniendo tan inquieto...",
  ui_story_5083_50831301_51_dialog_content = "Beep—Tú tienes un nuevo mensaje, Barton.",
  ui_story_5083_50831301_52_dialog_content = "Remitente desconocido: \"Reinhardt quedó inconsciente intentando salvar a las personas en el accidente de laboratorio.\"",
  ui_story_5083_50831301_53_dialog_content = "¿...?",
  ui_story_5083_50831301_54_dialog_content = "\"Lo siento, me confié demasiado... no sospeché fallos en los datos... □□... Peligro...\"",
  ui_story_5083_50831301_55_dialog_content = "\"Tomaré la responsabilidad de esto... mientras me recupero... □□... No te preocupes, el negador está con Reinhardt...\"",
  ui_story_5083_50831301_56_dialog_content = "Error: Escucha detectada. Señal interrumpida.",
  ui_story_5083_50831301_57_dialog_content = "Eso sonó como Gronru. Pero ¿por qué, y qué pasó?",
  ui_story_5083_50831301_58_dialog_content = "El mensaje tiene demasiados cifrados como para rastrear el origen.",
  ui_story_5083_50831301_59_dialog_content = "Esto es malo. Se está volviendo cada vez más enredado para mí.",
  ui_story_5083_50831301_60_dialog_content = "¿Por qué estaba involucrado Reinhardt? ¿Qué le pasó a Gronru? ¿Y por qué se monitoreó el mensaje?",
  ui_story_5083_50831301_61_dialog_content = "¿Qué pasó sin que yo lo supiera? Maldita sea, esto me está matando...",
  ui_story_5083_50831301_62_dialog_content = "Bip—Se recomienda descanso inmediato y desestresarse, Barton.",
  ui_story_5083_50831301_63_dialog_content = "¡No, no puedo tomar ningún descanso ahora!",
  ui_story_5083_50831301_64_dialog_content = "No puedo simplemente quedarme de brazos cruzados y no hacer nada.",
  ui_story_5083_50831301_65_dialog_content = "Barton...",
  ui_story_5083_50831301_66_dialog_content = "Debo ir y alcanzar a Dogg y a los demás.",
  ui_story_5083_50831301_67_dialog_content = "Pero tú no recibiste ninguna orden, Barton.",
  ui_story_5083_50831301_68_dialog_content = "¡No me importa!",
  ui_story_5083_50831301_69_dialog_content = "¡Incluso cometer errores es mejor que no hacer nada en absoluto!",
  ui_story_5083_50831301_70_dialog_content = "¡Es todo por esa luz, anciano! ¡Es por ella que debemos seguir adelante!",
  ui_story_5083_50831301_71_dialog_content = "¡No me importa lo que vaya a pasar de ahora en adelante! ¡No puedo dejar que les pase nada malo a ninguno de ellos!",
  ui_story_5083_50831301_72_dialog_content = "¡2ª Legión, reúnanse!",
  ui_story_5083_50831301_73_dialog_content = "Encontramos rastros de batalla, Comandante Barton. Es probable que el Comandante luchara contra los Eclipsites aquí antes de que la legión desapareciera.",
  ui_story_5083_50831301_74_dialog_content = "Dada la escala de la batalla, probablemente no sean Eclipsites sueltos. Creo que el Comandante se retiró.",
  ui_story_5083_50831301_75_dialog_content = "¡Rápido, sigue las huellas, explora el terreno y abre camino para el convoy!",
  ui_story_5083_50831301_76_dialog_content = "No es demasiado tarde. Estoy seguro de que lo lograremos...",
  ui_story_5083_50831302_1_dialog_content = "¿Cómo es?",
  ui_story_5083_50831302_2_dialog_content = "La comunicación sigue bloqueada. Esto es extraño porque los Eclipsites no tienen la tecnología.",
  ui_story_5083_50831302_3_dialog_content = "Creo que estamos rodeados.",
  ui_story_5083_50831302_4_dialog_content = "¿Cuál es nuestro estado?",
  ui_story_5083_50831302_5_dialog_content = "Solo veinte de los doscientos que cubrían la retaguardia sobrevivieron. También perdimos un tercio de nuestros comandos.",
  ui_story_5083_50831302_6_dialog_content = "Los Eclipsites nos superaron en número más de lo que esperábamos. Hemos perdido el control de la situación.",
  ui_story_5083_50831302_7_dialog_content = "Quizás una subciudad a lo largo de la línea de defensa ha sido violada para que esto suceda.",
  ui_story_5083_50831302_8_dialog_content = "O podría haber un traidor. Independientemente, lideraré un equipo para romper el asedio y permitirte salir.",
  ui_story_5083_50831302_9_dialog_content = "Debes llevar las noticias de vuelta a Gannon para evitar pérdidas mayores.",
  ui_story_5083_50831302_10_dialog_content = "No, muchas instalaciones no se han recuperado adecuadamente y el puesto avanzado de la 1ra Legión aún está intacto. No puedo simplemente irme.",
  ui_story_5083_50831302_11_dialog_content = "Pero...",
  ui_story_5083_50831302_12_dialog_content = "<color=#e8d9bb>¡BOOM!</color>",
  ui_story_5083_50831302_13_dialog_content = "¿Qué está pasando? ¿Estamos bajo ataque de Eclipsite?",
  ui_story_5083_50831302_14_dialog_content = "¿Estás bien? ¿Dónde está el Comandante Pango?",
  ui_story_5083_50831302_15_dialog_content = "¿Qué estás haciendo aquí, mocoso?",
  ui_story_5083_50831302_16_dialog_content = "¡Me alegra ver que estás bien, pero no creo que este sea el momento de preguntarme eso!",
  ui_story_5083_50831302_17_dialog_content = "Llegas justo a tiempo. ¿Viste algún Eclipsite?",
  ui_story_5083_50831302_18_dialog_content = "Mi equipo de mechas ha roto su línea. Me encontré con exploradores de la 1ra Legión en el camino y ya les informé.",
  ui_story_5083_50831302_19_dialog_content = "Tenemos instalaciones que necesitamos recuperar. ¿Cuántos transportes puedes prescindir, Barton? ¡Tenemos que hacer esto lo antes posible!",
  ui_story_5083_50831302_20_dialog_content = "Eso no será un problema. Pero, ¿qué está pasando aquí? No puedo recibir ninguna señal.",
  ui_story_5083_50831302_21_dialog_content = "Ya intentamos enviar bengalas de SOS.",
  ui_story_5083_50831302_22_dialog_content = "Solo la atalaya podía ver las bengalas, y no estoy seguro de que tengan la señal para retransmitirla a Gannon.",
  ui_story_5083_50831302_23_dialog_content = "Está bien. Si ya avisaste a los exploradores, la ayuda debería llegar pronto.",
  ui_story_5083_50831302_24_dialog_content = "Malas noticias, los Eclipsites están intentando superar nuestro bombardeo con pura cantidad!",
  ui_story_5083_50831302_25_dialog_content = "También vimos un <color=#FFB400>Eclipsite gigantesco</color> acercándose que debe ser disuadido!",
  ui_story_5083_50831302_26_dialog_content = "¿<color=#FFB400>Eclipse Gargantua</color>? ¿El legendario <color=#FFB400>Eclipsite de Asedio</color>?",
  ui_story_5083_50831302_27_dialog_content = "Sería difícil matar a ese bastardo sin algo de potencia de fuego seria...",
  ui_story_5083_50831302_28_dialog_content = "Divide la división de tanques en dos, una para cubrir nuestra retirada y otra para defender el frente!",
  ui_story_5083_50831302_29_dialog_content = "Obtenga diez transportadores con cuatro comandos cada uno para recuperar las instalaciones superficiales alrededor de Gannon.",
  ui_story_5083_50831302_30_dialog_content = "¡Copiado!",
  ui_story_5083_50831302_31_dialog_content = "<color=#e8d9bb>El bombardeo señala el inicio de la guerra. Sin embargo, los ecos de un timbre inusual ahogan todos los ruidos.</color>",
  ui_story_5083_50831302_32_dialog_content = "¡Ven a montar conmigo, Dogg! ¡Vamos a deshacernos de ese Eclipsite súper grande!",
  ui_story_5083_50831302_33_dialog_content = "¡Mi unidad todavía tiene las torretas rescatadas de Subciudad 19, y esos chupones causan un daño masivo!",
  ui_story_5083_50831302_34_dialog_content = "¡No!",
  ui_story_5083_50831302_35_dialog_content = "Ustedes dos vayan y déjenme a mí y a mi equipo atrás.",
  ui_story_5083_50831302_36_dialog_content = "Este es un asalto planeado pero nosotros no somos el objetivo... Gannon lo es.",
  ui_story_5083_50831302_37_dialog_content = "No es una operación que solo ustedes dos idiotas puedan manejar.",
  ui_story_5083_50831302_38_dialog_content = "¡Sal ahora y notifica a Gannon! ¡Cuanto antes, mejor!",
  ui_story_5083_50831302_39_dialog_content = "¿Qué estás diciendo? ¡No podemos abandonarte en un momento como este!",
  ui_story_5083_50831302_40_dialog_content = "Nos superan en número, pero eso es más razón para permanecer unidos.",
  ui_story_5083_50831302_41_dialog_content = "¿Oyes el <color=#FFB400>sonido</color>? Eso es la Abominación de la Zona Oscura que aniquiló Subciudad 13.",
  ui_story_5083_50831302_42_dialog_content = "En la Batalla de la Zona Oscura, esa campana anunció nuestra derrota.",
  ui_story_5083_50831302_43_dialog_content = "¡Si no te vas ahora, ninguno de nosotros saldrá vivo!",
  ui_story_5083_50831302_44_dialog_content = "Pero...",
  ui_story_5083_50831302_45_dialog_content = "¡Ahora!",
  ui_story_5083_50831302_46_dialog_content = "No puedo dejarte atrás, porque eres más que un superior para mí... Al menos déjame quedarme contigo.",
  ui_story_5083_50831302_47_dialog_content = "Entiendo.",
  ui_story_5083_50831302_48_dialog_content = "Pero ningún niño debería morir antes que sus padres.",
  ui_story_5083_50831302_49_dialog_content = "Ya perdí a un niño, Dogg. No puedo permitirme perderte a ti también.",
  ui_story_5083_50831302_50_dialog_content = "¡Oh...!",
  ui_story_5083_50831302_51_dialog_content = "Tú viejo...",
  ui_story_5083_50831302_52_dialog_content = "Yo... lo entiendo.",
  ui_story_5083_50831302_53_dialog_content = "Sal de aquí si lo entiendes. ¡Fuera de mi vista para que estés fuera de mi mente!",
  ui_story_5083_50831302_54_dialog_content = "¡Tengo una batalla que luchar!",
  ui_story_5083_50831302_55_dialog_content = "¿Qué estás haciendo, Perrito?!",
  ui_story_5083_50831302_56_dialog_content = "Lleva al Comandante Pango... eh, Pops. Los comandos abrirán un camino para ti.",
  ui_story_5083_50831302_57_dialog_content = "¡Este no es el momento para que tú juegues al héroe!",
  ui_story_5083_50831302_58_dialog_content = "Siempre te he envidiado, Barton...",
  ui_story_5083_50831302_59_dialog_content = "Como un élite como tú, siempre estoy un paso atrás, siempre el segundo violín.",
  ui_story_5083_50831302_60_dialog_content = "¡Este no es el momento para eso, tonto!",
  ui_story_5083_50831302_61_dialog_content = "Déjame terminar. Siempre estoy celoso de que seas mejor que yo, puedas ir más lejos que yo y te traten mejor que a mí...",
  ui_story_5083_50831302_62_dialog_content = "Siempre avanzabas, con todos siguiéndote voluntariamente...",
  ui_story_5083_50831302_63_dialog_content = "En ti, veo el poder para conquistar la oscuridad digno de un élite.",
  ui_story_5083_50831302_64_dialog_content = "Eres más decisivo que yo, así que siempre seré un segundo para ti.",
  ui_story_5083_50831302_65_dialog_content = "Me alegra saber, sin embargo, que trabajé lo suficiente para estar solo un escalón por debajo de ti.",
  ui_story_5083_50831302_66_dialog_content = "Así que quiero detenerme en los Eclipsites igual que tú para que puedas llegar a casa.",
  ui_story_5083_50831302_67_dialog_content = "<color=#e8d9bb>Los sonidos de los anillos se acercan a medida que los blasters se vuelven cada vez más silenciosos. La línea de defensa retrocede para dar paso a una retirada.</color>",
  ui_story_5083_50831302_68_dialog_content = "¡Esto solo significa que más personas serán sacrificadas! ¡Tengo que quedarme y ayudar!",
  ui_story_5083_50831302_69_dialog_content = "Todos mueren a veces. ¿No estábamos todos preparados para eso la primera vez que tomamos un arma?",
  ui_story_5083_50831302_70_dialog_content = "Pero por el futuro de la legión e Illumina, este no es el lugar para eso, para alguien como tú.",
  ui_story_5083_50831302_71_dialog_content = "Permíteme darte la mejor asistencia que jamás hayas tenido. Haz tu cosa después de que haga una apertura.",
  ui_story_5083_50831302_72_dialog_content = "El futuro de Illumina depende de ti.",
  ui_story_5083_50831302_73_dialog_content = "Detén esa tontería. Todavía tenemos tanques...",
  ui_story_5083_50831302_74_dialog_content = "¿Recuerdas la historia que te conté? Pango sacrificó a su esposa e hijo por mí.",
  ui_story_5083_50831302_75_dialog_content = "He estado pensando, ¿quién soy yo para merecer tal honor?",
  ui_story_5083_50831302_76_dialog_content = "He estado viviendo con culpa. Muchas veces, estaba muerto en mi mente.",
  ui_story_5083_50831302_77_dialog_content = "¡Idiota! Si no hubieras sobrevivido, ¿quién habría estado allí para empujarme y hacerme ir más allá?",
  ui_story_5083_50831302_78_dialog_content = "Sí, pude sentirlo cuando me hablaste sobre el sueño. Me conmovió hasta la médula.",
  ui_story_5083_50831302_79_dialog_content = "Aunque quería replicar por instinto, no lo hice porque sabía que estaba dispuesto a morir por esa causa.",
  ui_story_5083_50831302_80_dialog_content = "Por favor danos la oportunidad, Barton. No estamos muriendo por nada, sino por la gloria y las esperanzas de un Illumina más grande.",
  ui_story_5083_50831302_81_dialog_content = "¡La unidad de tanques ha logrado quebrar a la oposición con éxito!",
  ui_story_5083_50831302_82_dialog_content = "¡Pero el gigantesco Eclipsite está haciendo imposible que nos retiremos de manera segura!",
  ui_story_5083_50831302_83_dialog_content = "¡Transmite mi orden para que todos los comandos se queden atrás y cubran a nuestros compañeros soldados!",
  ui_story_5083_50831302_84_dialog_content = "¡Informa a las unidades mecanizadas para darles tanta munición como sea posible, luego tomamos el resto y nos retiramos a Gannon!",
  ui_story_5083_50831302_85_dialog_content = "Barton, tú eres mi hermano, mi enemigo, mi pesadilla, la razón por la que soy un segundo violín.",
  ui_story_5083_50831302_86_dialog_content = "¡Y soy la razón por la que eres el mejor!",
  ui_story_5083_50831302_87_dialog_content = "Toma esto y vete.",
  ui_story_5083_50831302_88_dialog_content = "¡Tú mantente vivo hasta que traiga refuerzos!",
  ui_story_5083_50831302_89_dialog_content = "¡Fuera de mi camino, insignificantes insectos de Illumina!",
  ui_story_5083_50831302_90_dialog_content = "Camaradas, ¡esto es para lo que se hacen los comandos! ¡Luchemos el uno por el otro! <size=45>¡Cargad!</size>",
  ui_story_5083_50831302_91_dialog_content = "<color=#e8d9bb>Dogg gritó la canción de lucha a todo pulmón y avanzó a grandes zancadas. Todos los comandos lo siguieron y cargaron contra la horda.</color>",
  ui_story_5083_50831302_92_dialog_content = "<size=45>Vete al infierno.</size>",
  ui_story_5083_50831302_93_dialog_content = "¡Vuela duro y fuerte, no pares hasta que el sueño se haga realidad!",
  ui_story_5083_50831302_94_dialog_content = "Ve, Barton... Avanza siempre hacia un futuro brillante...",
  ui_story_5083_50831400_1_dialog_content = "<color=#e8d9bb>Los exploradores de la 1ra Legión trajeron noticias de que todos los comandos fueron asesinados en acción. Rechazaron al ejército de Darkover a costa de sus vidas.</color>",
  ui_story_5083_50831400_2_dialog_content = "<color=#e8d9bb>Las alarmas sonaron en todo Gannon cuando se declaró la movilización total. Todos estaban en cubierta contra los inminentes Eclipsites.</color>",
  ui_story_5083_50831400_3_dialog_content = "Es demasiado tarde para hacer enmiendas. ¡Un batallón entero sacrificado por nada!",
  ui_story_5083_50831400_4_dialog_content = "Esta es una reunión clasificada, Coronel Barton. Por favor, no proceda más allá.",
  ui_story_5083_50831400_5_dialog_content = "La Gran Mariscal aún está formulando un plan. Deja de interferir o enfrenta las consecuencias.",
  ui_story_5083_50831400_6_dialog_content = "Dispara, te reto.",
  ui_story_5083_50831400_7_dialog_content = "¡Por favor, retroceda, Coronel Barton!",
  ui_story_5083_50831400_8_dialog_content = "Si no tienes el valor para apretar el gatillo, no apuntes esa cosa hacia mí.",
  ui_story_5083_50831400_9_dialog_content = "¿Por qué estás gritando sobre esto esta vez, mocoso?!",
  ui_story_5083_50831400_10_dialog_content = "¡Vuelve aquí antes de que te avergüences frente al Gran Mariscal!",
  ui_story_5083_50831400_11_dialog_content = "Estás consciente, señor...",
  ui_story_5083_50831400_12_dialog_content = "¡Saludos, Gran Mariscal!",
  ui_story_5083_50831400_13_dialog_content = "...",
  ui_story_5083_50831400_14_dialog_content = "¡Oye, deja de detenerme! ¡Quiero respuestas de él!",
  ui_story_5083_50831400_15_dialog_content = "¿Por qué te negaste a enviar incluso solo dos batallones? ¿Por qué no desplegaste la unidad mecanizada en primer lugar?",
  ui_story_5083_50831400_16_dialog_content = "No estarían atrapados si tuvieran transporte...",
  ui_story_5083_50831400_17_dialog_content = "¡Cálmate!",
  ui_story_5083_50831400_18_dialog_content = "Dogg y todos los demás, están muertos. ¡Cómo puedo estar tranquilo!",
  ui_story_5083_50831400_19_dialog_content = "¡Confías en las personas equivocadas! ¡Esos tipos no tienen estrategias más que el subterfugio de que hablar, por eso Dogg y otros murieron en vano!",
  ui_story_5083_50831400_20_dialog_content = "Nos están apuntando... pero, ¿por qué no vienen directamente a por mí?",
  ui_story_5083_50831400_21_dialog_content = "¡Maldita sea, por qué no vienen hacia mí!",
  ui_story_5083_50831400_22_dialog_content = "Detén esto antes de que también avergüences a la 2da Legión. ¿Cómo se sentiría Dogg al respecto?",
  ui_story_5083_50831400_23_dialog_content = "¡Esta es la segunda vez que dejas a Gannon con la unidad mecanizada! ¡Eres afortunado de que el Gran Mariscal no te haya castigado!",
  ui_story_5083_50831400_24_dialog_content = "¡Él es responsable de la muerte de Dogg!",
  ui_story_5083_50831400_25_dialog_content = "Es obvio que él es el culpable...",
  ui_story_5083_50831400_26_dialog_content = "Dogg es el único hijo del Gran Mariscal.",
  ui_story_5083_50831400_27_dialog_content = "¡Deja de venderme mentiras, anciano!",
  ui_story_5083_50831400_28_dialog_content = "Sígueme.",
  ui_story_5083_50831400_29_dialog_content = "Roog y yo somos viejos compañeros de guerra. Justo antes de que fuera nombrado Gran Mariscal, su esposa embarazada quedó atrapada en una entrañas.",
  ui_story_5083_50831400_30_dialog_content = "Dirigí un ejército de rescate pero era demasiado tarde. La Subciudad cayó. Según los registros, no hubo supervivientes.",
  ui_story_5083_50831400_31_dialog_content = "Pero cuando encontré el cuerpo de su esposa, noté a Dogg acostado en los brazos de su madre. Estaba tranquilo y nunca lloró.",
  ui_story_5083_50831400_32_dialog_content = "No tengo idea de cómo dio a luz a un niño en un ambiente tan adverso y lo ayudó a sobrevivir... Es un milagro.",
  ui_story_5083_50831400_33_dialog_content = "Todavía recuerdo lo triste que estaba Roog cuando traje a Dogg de vuelta. Amaba mucho a su esposa, pero tenía que cumplir con su deber como soldado.",
  ui_story_5083_50831400_34_dialog_content = "Nadie sabía sobre ese niño, así que me confió al niño. Tenía algo en mente en ese momento y quería concentrarse en la guerra.",
  ui_story_5083_50831400_35_dialog_content = "Imposible.",
  ui_story_5083_50831400_36_dialog_content = "Esa es la realidad. La ciudad subterránea que estaba defendiendo fue invadida hace seis años. El Comité descubrió la verdadera historia de Dogg cuando siguieron el procedimiento habitual.",
  ui_story_5083_50831400_37_dialog_content = "No sé si eso tuvo algo que ver con ello, pero Roog se volvió indeciso y se alejó de mí después de eso.",
  ui_story_5083_50831400_38_dialog_content = "Como Gran Mariscal, aunque se volvía más y más fuerte, actuaba de manera cada vez más conservadora.",
  ui_story_5083_50831400_39_dialog_content = "No lo entiendo, pero apostaría mi vida a que él tiene el mejor interés de Illumina en su corazón.",
  ui_story_5083_50831400_40_dialog_content = "Incluso si su objetivo puede estar un poco desviado, nunca lastimaría a su propio niño.",
  ui_story_5083_50831400_41_dialog_content = "¿Le dijiste a ese tonto quién es su padre?",
  ui_story_5083_50831400_42_dialog_content = "Por supuesto.",
  ui_story_5083_50831400_43_dialog_content = "His sacrificed his wife to evacuate me and the other noncombatants.",
  ui_story_5083_50831400_44_dialog_content = "He estado pensando, ¿quién soy yo para merecer tal honor?",
  ui_story_5083_50831400_45_dialog_content = "Ese tonto ha estado cargando con la culpa de quién es realmente todos estos años...",
  ui_story_5083_50831400_46_dialog_content = "Así que lamento mucho habérselo dicho.",
  ui_story_5083_50831400_47_dialog_content = "...",
  ui_story_5083_50831400_48_dialog_content = "Rápido, toma todo lo que puedas y llena todas las bolsas de arena... Alto, tú ahí. ¡Este es el escuadrón de la 1ra Legión dirigiéndose al frente!",
  ui_story_5083_50831400_49_dialog_content = "¿Reinhardt?",
  ui_story_5083_50831400_50_dialog_content = "Veo que te han dado de alta del hospital.",
  ui_story_5083_50831400_51_dialog_content = "Eso fue hace mucho tiempo. ¿Qué haces aquí cuando Illumina está enfrentando una crisis?",
  ui_story_5083_50831400_52_dialog_content = "Los vehículos están cargados, Coronel Reinhardt. Nos iremos ahora.",
  ui_story_5083_50831400_53_dialog_content = "¡Ten un viaje seguro!",
  ui_story_5083_50831400_54_dialog_content = "Hmm, no hay suficientes personas. Esto solo puede significar problemas para el comandante...",
  ui_story_5083_50831400_55_dialog_content = "Me pareces un poco diferente...",
  ui_story_5083_50831400_56_dialog_content = "¿Lo hago? Estoy ocupado con la movilización, así que no tengo tiempo para charlas.",
  ui_story_5083_50831400_57_dialog_content = "Oye, espera un minuto, Reinhardt...",
  ui_story_5083_50831400_58_dialog_content = "¿Todavía recuerdas de lo que hablamos antes?",
  ui_story_5083_50831400_59_dialog_content = "¿Qué te hizo el Comité?",
  ui_story_5083_50831400_60_dialog_content = "¿Quieres decir que me promoverás a coronel?",
  ui_story_5083_50831400_61_dialog_content = "¡No! ¿Por qué tú...",
  ui_story_5083_50831400_62_dialog_content = "Sé lo que quieres decir. En cuanto al Comité, tengo que soportarlo por ahora. La guerra es la verdadera preocupación.",
  ui_story_5083_50831400_63_dialog_content = "Tengo que informar al comandante. Probablemente estés un poco confundido, pero espero que te animes. Después de todo, eres un héroe de Illumina.",
  ui_story_5083_50831400_64_dialog_content = "Je, ¿\"Héroe de Illumina\"? ¿Cómo deberíamos llamar entonces a Dogg y los demás que no volverán?",
  ui_story_5083_50831400_65_dialog_content = "¡El Comité no tiene derecho a decidir quién es el héroe y quién no!",
  ui_story_5083_50831400_66_dialog_content = "Reinhardt...",
  ui_story_5083_50831400_67_dialog_content = "Beep—Por favor sígueme, Barton.",
  ui_story_5083_50831400_68_dialog_content = "Bueno, al menos tú no has cambiado nada, mi... navegante.",
  ui_story_5083_50831400_69_dialog_content = "Vamos. Donde sea que me lleves no puede ser peor que esto.",
  ui_story_5083_50831400_70_dialog_content = "El monumento... ¿Se ha añadido el nombre de Dogg?",
  ui_story_5083_50831400_71_dialog_content = "Beep—Mira, Barton.",
  ui_story_5083_50831400_72_dialog_content = "<color=#e8d9bb>Bajo el imponente monumento, una figura encorvada miraba los nombres sin ninguna expresión.</color>",
  ui_story_5083_50831400_73_dialog_content = "Ese es el Gran Mariscal.",
  ui_story_5083_50831400_74_dialog_content = "El verdadero <color=#FFB400>padre</color> de Dogg...",
  ui_story_5083_50831400_75_dialog_content = "<color=#e8d9bb>Barton se detuvo. Quería avanzar pero cambió de opinión y permaneció donde estaba.</color>",
  ui_story_5083_50831400_76_dialog_content = "Perrit...",
  ui_story_5083_50831400_77_dialog_content = "<color=#e8d9bb>El hombre demacrado en la distancia derramó una lágrima silenciosa. No era un Gran Mariscal, sino un padre con el corazón roto.</color>",
  ui_story_5083_50831400_78_dialog_content = "<color=#e8d9bb>Finalmente se fue con pasos pesados para ceder el camino a Barton.</color>",
  ui_story_5083_50831400_79_dialog_content = "Se ha añadido el nombre de cada soldado. Este es el lugar de descanso final para todos los niños de Illumina.",
  ui_story_5083_50831400_80_dialog_content = "Beep—Barton...",
  ui_story_5083_50831400_81_dialog_content = "¿En quién puedo confiar ahora aparte de ti? Todos tienen un secreto, con capas interminables también...",
  ui_story_5083_50831400_82_dialog_content = "Aunque el Gran Mariscal y los demás sean inocentes, ¿cómo puedo confiar en ellos...?",
  ui_story_5083_50831400_83_dialog_content = "Echa un vistazo, Barton.",
  ui_story_5083_50831400_84_dialog_content = "¿Es esta una foto de todos nosotros juntos?",
  ui_story_5083_50831400_85_dialog_content = "¿Tomaste esta foto para nosotros? Gracias.",
  ui_story_5083_50831400_86_dialog_content = "Dogg se ha ido, Reinhardt no es el mismo, y quién sabe dónde fue el resto.",
  ui_story_5083_50831400_87_dialog_content = "Todos en esta imagen se han dispersado...",
  ui_story_5083_50831400_88_dialog_content = "Pero tengo que llevar la carga y seguir adelante, ¿verdad?",
  ui_story_5083_50831400_89_dialog_content = "Incluso si solo quedo yo, aún tomaré el timón.",
  ui_story_5083_50831500_1_dialog_content = "<color=#e8d9bb>A medida que la batalla por Gannon se intensificaba, el Comité finalmente cedió para que Barton llevara un ejército reabastecido de vuelta al frente.</color>",
  ui_story_5083_50831500_2_dialog_content = "<color=#e8d9bb>Sin embargo, la situación no mejoró con el Darkover amenazando las fronteras de Gannon. Para evitar un asedio, el Gran Mariscal ordenó una evacuación.</color>",
  ui_story_5083_50831500_3_dialog_content = "Comandante Barton, el Darkover se ha retirado. ¿Cuál es su orden?",
  ui_story_5083_50831500_4_dialog_content = "Empuja la línea de defensa pero despacio. No, olvida eso. No hay movimientos arriesgados. Estamos en una mejor posición para los transportes logísticos en este momento.",
  ui_story_5083_50831500_5_dialog_content = "Las unidades de tanques están solicitando un contraataque, Comandante Barton.",
  ui_story_5083_50831500_6_dialog_content = "¡Absolutamente no! Deja de pensar en matar al enemigo cuando estamos luchando una batalla defensiva. Solo necesitamos hacerlos retroceder.",
  ui_story_5083_50831500_7_dialog_content = "Pero la 1ra Legión todavía está en una lucha amarga... ¿No deberíamos ayudar?",
  ui_story_5083_50831500_8_dialog_content = "No podemos hacer nada al respecto. Podemos correr cualquier riesgo. No puedo dejarte salir a ciegas...",
  ui_story_5083_50831500_9_dialog_content = "¿Qué haces aquí atascado como una tortuga? ¡Hay muchos Eclipsites allí fuera para que los persigas!",
  ui_story_5083_50831500_10_dialog_content = "Pero alguien morirá...",
  ui_story_5083_50831500_11_dialog_content = "¿Cómo puedes luchar en una guerra sin que nadie muera? ¡Lo importante es por qué estás luchando!",
  ui_story_5083_50831500_12_dialog_content = "¿No solías saber mejor, mocoso? ¡No te ablandes conmigo ahora!",
  ui_story_5083_50831500_13_dialog_content = "Ya no veo la luz...",
  ui_story_5083_50831500_14_dialog_content = "¡¿?!",
  ui_story_5083_50831500_15_dialog_content = "Con la siempre creciente Torre Central adelante, he estado avanzando hacia Illumina.",
  ui_story_5083_50831500_16_dialog_content = "Crecí persiguiéndolo, tratando de alcanzarlo... Pero ahora no lo veo.",
  ui_story_5083_50831500_17_dialog_content = "No puedo encontrar una razón por la cual mis soldados deberían luchar por mí. No quiero que mueran por mis órdenes.",
  ui_story_5083_50831500_18_dialog_content = "Sé que debería estar liderándolos, pero ahora ni siquiera puedo encontrar mi propio equilibrio...",
  ui_story_5083_50831500_19_dialog_content = "¿Cuándo te volviste tan insípido también, mocoso?",
  ui_story_5083_50831500_20_dialog_content = "Tomas decisiones y das órdenes basadas en el informe que recibiste para completar objetivos. ¿No es suficiente?",
  ui_story_5083_50831500_21_dialog_content = "Los soldados de Illumina no son tontos. ¡Saben por qué están luchando!",
  ui_story_5083_50831500_22_dialog_content = "Incluso si no pueden explicarlo bien, solo pregunta, ¡y cada uno de ellos te dirá la causa por la cual morirían!",
  ui_story_5083_50831500_23_dialog_content = "¡Fuera de la sede ahora y hacia las trincheras! ¡Verás la dirección que su resolución te está indicando seguir!",
  ui_story_5083_50831500_24_dialog_content = "Cada uno de nuestros soldados de Illumina creció bajo la luz. ¿Cómo podrías olvidar eso?",
  ui_story_5083_50831500_25_dialog_content = "Crecieron bajo la luz...",
  ui_story_5083_50831500_26_dialog_content = "¡Elabore un mejor plan si cree que las bajas van a ser altas! ¡Pero nunca dejes a tus hombres colgados!",
  ui_story_5083_50831500_27_dialog_content = "¡Quejarse solo no resuelve nada! ¿Es así como recompensas a los muertos por su sacrificio?",
  ui_story_5083_50831500_28_dialog_content = "¿Los soldados seguirían siguiéndote si te vieran así?",
  ui_story_5083_50831500_29_dialog_content = "¿Acaso no sigues teniendo muchas personas que confían en ti? ¿Por qué te menosprecias tanto?!",
  ui_story_5083_50831500_30_dialog_content = "¿Qué te hizo pensar que tienes el derecho de hablar por todos? ¡No eres el único héroe por aquí! ¡Dales una oportunidad!",
  ui_story_5083_50831500_31_dialog_content = "Tienes razón. Estaba débil y confundido.",
  ui_story_5083_50831500_32_dialog_content = "¡No hay futuro si te quedas quieto, y no hay recompensa sin riesgo!",
  ui_story_5083_50831500_33_dialog_content = "Todos quieren servir a la luz. Como aún están contigo, debes asegurarte de que el brillo no esté borroso.",
  ui_story_5083_50831500_34_dialog_content = "Puedes comandar a los soldados, pero ellos te eligieron para liderarlos.",
  ui_story_5083_50831500_35_dialog_content = "Recuerda esto, Barton, encontrarás lo que sea que esté detrás del llamado al deber en el campo de batalla.",
  ui_story_5083_50831500_36_dialog_content = "Si no sabes en quién confiar, confía en tus camaradas. No importa qué tipo de líder te conviertas, ellos te seguirán.",
  ui_story_5083_50831500_37_dialog_content = "¡La 1ra Legión podría mantener la línea! ¡El gigantesco Eclipsite abrió un camino para que su especie invadiera el Ascensor Gannon!",
  ui_story_5083_50831500_38_dialog_content = "La Gran Mariscal dio la orden de <color=#FFB400>abandonar la ciudad</color>!",
  ui_story_5083_50831500_39_dialog_content = "¿Qué? ¿Abandonar nuestra casa?",
  ui_story_5083_50831500_40_dialog_content = "¿Está loco? ¡Este es el corazón de Illumina y nuestro hogar! ¡Se supone que es el faro que nunca se apaga!",
  ui_story_5083_50831500_41_dialog_content = "Mis disculpas, pero esa es la orden. El Gran Mariscal quisiera que algunas tropas se queden y cubran la evacuación de los civiles.",
  ui_story_5083_50831500_42_dialog_content = "Entonces, las otras tropas volverán, se reforzarán y asediarán el Darkover.",
  ui_story_5083_50831500_43_dialog_content = "Transmite mi orden. ¡Todo el personal, retroceda! ¡La 2ª Legión cubrirá la retirada!",
  ui_story_5083_50831500_44_dialog_content = "¡Vamos a buscar una pelea, señor!",
  ui_story_5083_50831500_45_dialog_content = "<color=#e8d9bb>La 2da Legión se volteó y corrió hacia Gannon contra la multitud en fuga.</color>",
  ui_story_5083_50831500_46_dialog_content = "<color=#e8d9bb>Lo que siguió fueron días de batalla sin parar. La legión sufrió grandes pérdidas pero defendió la escalera mecánica valientemente.</color>",
  ui_story_5083_50831500_47_dialog_content = "<color=#e8d9bb>Al final, sin embargo, innumerables Eclipsites lograron penetrar en la instalación—</color><color=#FFB400>Gannon ha caído, oficialmente.</color>",
  ui_story_5083_50831500_48_dialog_content = "El último grupo de personal se ha ido. Es tu turno de ir ahora, Barton.",
  ui_story_5083_50831500_49_dialog_content = "Nuestros transportistas han sufrido demasiado daño para evacuar a todos.",
  ui_story_5083_50831500_50_dialog_content = "Ahí vas de nuevo, anciano.",
  ui_story_5083_50831500_51_dialog_content = "Voy a llevar gente allí. Todos son veteranos, a diferencia de los novatos que tienes.",
  ui_story_5083_50831500_52_dialog_content = "¿De qué estás balbuceando? Es una causa perdida...",
  ui_story_5083_50831500_53_dialog_content = "¡Voy a defender la Torre Central pase lo que pase! ¡Preservar el centro de energía es preservar el corazón de Gannon!",
  ui_story_5083_50831500_54_dialog_content = "Si se destruye como Entrañas 13, la luz se apagará en Gannon y ningún habitante de Illumina podrá encontrar su propósito.",
  ui_story_5083_50831500_55_dialog_content = "¡No puedo permitir que eso les suceda a aquellos que aún luchan duro!",
  ui_story_5083_50831500_56_dialog_content = "¡Entonces llévame contigo!",
  ui_story_5083_50831500_57_dialog_content = "Me alegra que no seas melodramático como Dogg, Barton. No repetiré nada sentimental dos veces.",
  ui_story_5083_50831500_58_dialog_content = "Siempre he creído en ti, mi élite personalmente perfeccionada.",
  ui_story_5083_50831500_59_dialog_content = "Entonces esta es la lección final.",
  ui_story_5083_50831500_60_dialog_content = "¡Cuando sea necesario, incluso un general debe allanar el camino para la generación futura!",
  ui_story_5083_50831500_61_dialog_content = "Sé que serás el mejor líder para la 2ª Legión, Barton. Está en tus manos. ¡Ahora lárgate de aquí!",
  ui_story_5083_50831500_62_dialog_content = "No puedes hacerme irme, Comandante Pango. No me hagas noquearte también.",
  ui_story_5083_50831500_63_dialog_content = "Guardias, llévenlo al transportador de evacuación... ¡incluso si eso significa romperle las piernas!",
  ui_story_5083_50831500_64_dialog_content = "¿Qué? ¡Déjame ir!",
  ui_story_5083_50831500_65_dialog_content = "¡No puedes hacerme esto, anciano!",
  ui_story_5083_50831500_66_dialog_content = "Despedida, mi niño problemático...",
  ui_story_5083_50831601_1_dialog_content = "Lamento que tengan que quedarse, chicos.",
  ui_story_5083_50831601_2_dialog_content = "Mayor, quiero que sus hombres abran un camino hacia la fuente de energía a toda costa. ¿Puede hacer eso?",
  ui_story_5083_50831601_3_dialog_content = "¡Sí señor!",
  ui_story_5083_50831601_4_dialog_content = "¿Cuáles son las pérdidas estimadas para ti?",
  ui_story_5083_50831601_5_dialog_content = "¡Todos pereceremos, señor!",
  ui_story_5083_50831601_6_dialog_content = "...",
  ui_story_5083_50831601_7_dialog_content = "¡Pero lo haremos, señor!",
  ui_story_5083_50831601_8_dialog_content = "Está bien... Cuando lleguemos allí, seguiré tus órdenes!",
  ui_story_5083_50831601_9_dialog_content = "¡Hola, señor!",
  ui_story_5083_50831601_10_dialog_content = "¡Primer batallón, prepárense para contraatacar!",
  ui_story_5083_50831601_11_dialog_content = "No tengas miedo. Solo tenemos que resistir hasta el amanecer. El Gran Mariscal volverá por nosotros una vez que haya lidiado con sus Eclipsites.",
  ui_story_5083_50831601_12_dialog_content = "Todavía tengo un Lumamber, suficiente para enviar un SOS.",
  ui_story_5083_50831601_13_dialog_content = "El resto depende de nosotros, solo tenemos que resistir hasta el amanecer.",
  ui_story_5083_50831601_14_dialog_content = "¿Así que esto es el final? ¿Nosotros huyendo mientras Gannon arde?",
  ui_story_5083_50831601_15_dialog_content = "Beep—Barton...",
  ui_story_5083_50831601_16_dialog_content = "¡Emboscada! ¡Emboscada!",
  ui_story_5083_50831601_17_dialog_content = "¿Qué? Déjame pelear...",
  ui_story_5083_50831601_18_dialog_content = "Despierta, Barton.",
  ui_story_5083_50831601_19_dialog_content = "Qué está sucediendo...?",
  ui_story_5083_50831601_20_dialog_content = "El convoy está bajo ataque. Levántate y lucha.",
  ui_story_5083_50831601_21_dialog_content = "<size=45>¡Maldición!</size>",
  ui_story_5083_50831601_22_dialog_content = "Mis manos pueden estar atadas, pero estoy de mal humor, ¡así que no me enfades!",
  ui_story_5083_50831601_23_dialog_content = "¡Rugido!",
  ui_story_5083_50831601_24_dialog_content = "Me golpeó en la mandíbula de nuevo.",
  ui_story_5083_50831601_25_dialog_content = "Maldiciones... ¡Alguien quíteme estas esposas!",
  ui_story_5083_50831601_26_dialog_content = "Espera un minuto... ¿Me golpearon en la mandíbula y no me dolió nada?",
  ui_story_5083_50831601_27_dialog_content = "¡No te quedes ahí parado, sigue luchando!",
  ui_story_5083_50831601_28_dialog_content = "¡Sobre mi cadáver!",
  ui_story_5083_50831601_29_dialog_content = "Debe ser un sueño. No tenía una mandíbula de hierro cuando era joven.",
  ui_story_5083_50831601_30_dialog_content = "Lo entiendo ahora... Esta es la pesadilla en la que estaba atrapado.",
  ui_story_5083_50831601_31_dialog_content = "Beep—¿Por fin te has acordado, Barton?",
  ui_story_5083_50831601_32_dialog_content = "¿Qué es lo que te está atrapando?",
  ui_story_5083_50831601_33_dialog_content = "Perdí mi camino... Pero siempre creí que mientras siguiera luchando, la luz brillaría ante mí.",
  ui_story_5083_50831601_34_dialog_content = "Aún así, sigues atrapado aquí.",
  ui_story_5083_50831601_35_dialog_content = "No lo sé. No recuerdo nada... No creo que huyera, pero no recuerdo lo que hice después de eso...",
  ui_story_5083_50831601_36_dialog_content = "Solo recuerdo al comandante en esa batalla...",
  ui_story_5083_50831601_37_dialog_content = "Entonces estaba en el enfrentamiento, luchando con todo lo que tenía pero me hirieron gravemente, y así fue como me equiparon con la \"mandíbula de hierro\".",
  ui_story_5083_50831601_38_dialog_content = "Muchos de los soldados no entendieron eso y me vieron como un cobarde que abandonó a su comandante. Era un extraño para ellos.",
  ui_story_5083_50831601_39_dialog_content = "Quería luchar hasta la muerte junto a la Comandante Pango... Olvídalo, no me importa si solo fue un sueño.",
  ui_story_5083_50831601_40_dialog_content = "Las pesadillas no me afectan. ¡Siempre hay una próxima vez! No me importa cuántas veces intente, lo cambiaré...",
  ui_story_5083_50831601_41_dialog_content = "Acepta el resultado y espera hasta la próxima vez.. ¿Es así como te perdonas a ti mismo, Barton?",
  ui_story_5083_50831601_42_dialog_content = "Si puedes dejarlo atrás, ¿por qué siempre vuelves aquí?",
  ui_story_5083_50831601_43_dialog_content = "¿Sabes cuántas veces has pasado por esto? ¿Y cuántas \"próximas veces\" tuviste?",
  ui_story_5083_50831601_44_dialog_content = "Acaso...",
  ui_story_5083_50831601_45_dialog_content = "¿Cuándo será la \"próxima vez\"?",
  ui_story_5083_50831601_46_dialog_content = "¿Quién eres?",
  ui_story_5083_50831601_47_dialog_content = "Se te ha dejado claro desde el principio. Siempre seré tu navegador, Barton.",
  ui_story_5083_50831601_48_dialog_content = "Para mí, que puedo ver la luz pero no tocarla, ese camino ha estado bajo tus pies todo el tiempo desde que te conocí.",
  ui_story_5083_50831601_49_dialog_content = "Espera, ¿quieres decir que tú eres...",
  ui_story_5083_50831601_50_dialog_content = "Tenemos que irnos, coronel Barton.",
  ui_story_5083_50831601_51_dialog_content = "¿A dónde podemos ir? ¿Subciudad 19?",
  ui_story_5083_50831601_52_dialog_content = "Gannon ha caído... ¿Alguna vez lo recuperaremos?",
  ui_story_5083_50831601_53_dialog_content = "<size=45>Damn it!</size>",
  ui_story_5083_50831601_54_dialog_content = "<color=#e8d9bb>Con un grito, Barton rompe el grillete.</color>",
  ui_story_5083_50831601_55_dialog_content = "¡Así es, soy una oveja negra, un \"élite\" desafiante!",
  ui_story_5083_50831601_56_dialog_content = "¿Por qué debería tolerar esto?",
  ui_story_5083_50831601_57_dialog_content = "¡Estoy iniciando una revolución y el tiempo es ahora!",
  ui_story_5083_50831601_58_dialog_content = "¡Todos vosotros en la 2ª Legión!",
  ui_story_5083_50831601_59_dialog_content = "¿Coronel Barton? Nuestra misión es llevarte a un lugar seguro. Por favor, no nos lo pongas difícil.",
  ui_story_5083_50831601_60_dialog_content = "¡No, no tenemos seguridad de la que hablar!",
  ui_story_5083_50831601_61_dialog_content = "En un Astra devastado por Eclipsites, solo hay un hogar al que podemos volver.",
  ui_story_5083_50831601_62_dialog_content = "Todos ustedes entrenaron allí, ¡así que deberían recordar aún cuán brillante es esa luz!",
  ui_story_5083_50831601_63_dialog_content = "¡No nacimos para vagar! ¿A dónde podemos regresar si no vamos a Gannon?",
  ui_story_5083_50831601_64_dialog_content = "¡Nuestro superior está luchando por su vida y necesita ayuda! ¿Escuchaste la corneta? ¡Gannon nos está llamando!",
  ui_story_5083_50831601_65_dialog_content = "¡Si estamos destinados a morir en batalla, quiero morir con todos ustedes bajo mi mando, morir en la lucha por Gannon!",
  ui_story_5083_50831601_66_dialog_content = "Te llevaré a casa. Incluso si termina con solo tus nombres en una placa...",
  ui_story_5083_50831601_67_dialog_content = "¡Mientras la luz del faro permanezca, aquellos que nos siguen tendrán la voluntad de seguir adelante!",
  ui_story_5083_50831601_68_dialog_content = "Estoy dispuesto a seguirte, Coronel Barton. La orden del Gran Mariscal fue que defendiéramos a Gannon. Nunca la desobedeceremos.",
  ui_story_5083_50831601_69_dialog_content = "¡Yo también! He estado siguiendo a Barton desde el principio. Creo en ese mismo Barton que cargó con nosotros.",
  ui_story_5083_50831601_70_dialog_content = "Mis líderes de pelotón y compañeros reclutas murieron protegiéndome. No me importa sacrificarme para proteger Gannon.",
  ui_story_5083_50831601_71_dialog_content = "Cuenta conmigo. Cualquiera que quiera llegar al Coronel Barton tiene que pasar por nosotros primero.",
  ui_story_5083_50831601_72_dialog_content = "Ustedes...",
  ui_story_5083_50831601_73_dialog_content = "Es el amanecer, Barton.",
  ui_story_5083_50831601_74_dialog_content = "Sí, veo el camino... Todas tus luces me señalaron el camino.",
  ui_story_5083_50831601_75_dialog_content = "¡Compañía, media vuelta! Terminemos esta noche... ¡Recuperemos Gannon!",
  ui_story_5083_50831601_76_dialog_content = "<color=#e8d9bb>Entonces los soldados se dieron la vuelta y marcharon hacia Gannon.</color>",
  ui_story_5083_50831601_77_dialog_content = "<color=#e8d9bb>Todos se dieron cuenta de que morirían allí, pero nadie redujo la velocidad.</color>",
  ui_story_5083_50831601_78_dialog_content = "<color=#e8d9bb>Sin su brillo, no habría amanecer en Astra.</color>",
  ui_story_5083_50831601_79_dialog_content = "<color=#e8d9bb>La crisis de Darkover que atormentó la tierra durante ocho años podría haber terminado gracias a los resistentes baluartes que vinieron antes. Como sus sucesores, es mi deber continuar hasta el final.</color>",
  ui_story_5083_50831601_80_dialog_content = "Tus hombres están diezmados, insignificante Auroriano. Todas las vidas perecerán ante mí, la <color=#FFB400>Campana del Juicio Final</color>.",
  ui_story_5083_50831601_81_dialog_content = "¡Escupir!",
  ui_story_5083_50831601_82_dialog_content = "<color=#e8d9bb>El enorme enemigo se acercó a la Torre Central. Cubriendo su piel de piedra surcada de llamas había un collage de feas chatarras metálicas para armadura.</color>",
  ui_story_5083_50831601_83_dialog_content = "<color=#e8d9bb>Cualquiera que examine los sellos en los fragmentos podría reconocer que provienen de diferentes subciudades. Representaban las victorias del monstruo como insignias de honor.</color>",
  ui_story_5083_50831601_84_dialog_content = "<color=#e8d9bb>Fue inquietantemente espeluznante e irritante al mismo tiempo.</color>",
  ui_story_5083_50831601_85_dialog_content = "<color=#e8d9bb>Mientras avanzaba pesadamente, los fragmentos chocaban con sonidos metálicos apagados como si estuvieran tocando un requiem rencoroso.</color>",
  ui_story_5083_50831601_86_dialog_content = "Ah, estás temblando, Tiny One. Sí, puedo oler tu miedo. Incluso la bandera en tu mano está temblando.",
  ui_story_5083_50831601_87_dialog_content = "Todos las plagas son iguales. Todos temen al fuerte. Eso es su instinto. Arrodíllate para que te aplaste con deleite.",
  ui_story_5083_50831601_88_dialog_content = "Sí, estoy temblando... No pensé que tendría tanto miedo a mi edad.",
  ui_story_5083_50831601_89_dialog_content = "Tal vez es instinto, como dijiste.",
  ui_story_5083_50831601_90_dialog_content = "¿Así que lo admites? ¡Entonces arrodíllate y ruega por piedad! Esta es mi mayor alegría.",
  ui_story_5083_50831601_91_dialog_content = "¿Estás bromeando, tonto feo? ¿Crees que te enfrentas a un grupo de cobardes?",
  ui_story_5083_50831601_92_dialog_content = "¡No tienes idea de lo diferente que eres de nosotros!",
  ui_story_5083_50831601_93_dialog_content = "No habrá ninguna alegría para ti. ¡Todo lo que verás es cuán inquebrantables son las columnas vertebrales de la gente de Illumina!",
  ui_story_5083_50831601_94_dialog_content = "Los Aurorianos tienen miedo, pero los Eclipsites también, y nunca aprenderás a lidiar con él como nosotros lo hacemos.",
  ui_story_5083_50831601_95_dialog_content = "Yo digo no... ¡No hay ninguna posibilidad de que cruces nuestra línea!",
  ui_story_5083_50831601_96_dialog_content = "Entonces pondré eso a prueba.",
  ui_story_5083_50831601_97_dialog_content = "Lo siento, señor, esto es lo mejor que podemos hacer... ¿Por qué aún no ha llegado ayuda...?",
  ui_story_5083_50831601_98_dialog_content = "Veo que es hora de engañar a tus soldados. Adelante, muestra el Lumamber y diles que la ayuda está en camino.",
  ui_story_5083_50831601_99_dialog_content = "Esa es la mentira que cada oficial contó en cada Subciudad que destruí...",
  ui_story_5083_50831601_100_dialog_content = "No llegó ayuda incluso cuando les saqué el último aliento. Es la hipocresía más ridícula para Illumina.",
  ui_story_5083_50831601_101_dialog_content = "Lo siento, mis camaradas. Confíasteis en mí con vuestras vidas, sin embargo, no pude prometer nada a cambio.",
  ui_story_5083_50831601_102_dialog_content = "¡Pero por favor créeme cuando digo que Illumina nunca abandonaría a sus defensores!",
  ui_story_5083_50831601_103_dialog_content = "<color=#e8d9bb>Pango liberó el Lumamber y tiró de la palanca en oración. La luz se arqueó a través de la oscuridad sobre el caído Gannon y hacia el cielo.</color>",
  ui_story_5083_50831601_104_dialog_content = "<color=#e8d9bb>Los soldados luchando duramente en Gannon miraron al destello al unísono, con reflejos de </color><color=#FFB400>esperanza</color><color=#e8d9bb> brillando en sus ojos.</color>",
  ui_story_5083_50831601_105_dialog_content = "Estás solo, pero aún te mientes a ti mismo y lo llamas fe. Bueno, ¡aplastar a los guerreros fieles es mucho más divertido que aplastar a las plagas ordinarias!",
  ui_story_5083_50831601_106_dialog_content = "Maldito seas, Eclipsite, por esto nunca lo conseguirás... ¡Nosotros, los soldados de Illumina, somos llamados los \"Defensores de Astra\" por una razón!",
  ui_story_5083_50831601_107_dialog_content = "Soy Syurton. ¡Recuerda este nombre, el nombre de tu destructor!",
  ui_story_5083_50831601_108_dialog_content = "Mátalos a todos. Destruye la Torre Central. Quiero que Gannon sea arrasado hasta el olvido.",
  ui_story_5083_50831601_109_dialog_content = "¡La 2ª Legión nunca se echa atrás!",
  ui_story_5083_50831601_110_dialog_content = "<color=#e8d9bb>La señal en el cielo se atenuó y finalmente cayó. Todos las esperanzas parecían estar perdidas en la oscuridad.</color>",
  ui_story_5083_50831601_111_dialog_content = "¿2da Legión? Escuché eso hace unos días. Incluso me cortó en la cabeza y la espalda.",
  ui_story_5083_50831601_112_dialog_content = "Lástima que él y sus soldados fueran patéticos. Sin embargo, conservé su espada. ¿Ves esto aquí? No es un mal recuerdo.",
  ui_story_5083_50831601_113_dialog_content = "¡Perro! Lo siento mucho...",
  ui_story_5083_50831601_114_dialog_content = "<color=#e8d9bb>Llenos de desesperación, los veteranos agarraron sus armas y se prepararon para atacar a la entidad gigantesca.</color>",
  ui_story_5083_50831601_115_dialog_content = "<color=#e8d9bb>Sin embargo, las estrellas siempre brillan más en la noche más oscura.</color>",
  ui_story_5083_50831601_116_dialog_content = "<size=45>¡Eso es suficientemente lejos!</size>",
  ui_story_5083_50831601_117_dialog_content = "<size=45>¡Pruébalo a ver cómo te queda!</size>",
  ui_story_5083_50831601_118_dialog_content = "¡Eres tú el que está cavando su tumba, estúpido idiota!",
  ui_story_5083_50831601_119_dialog_content = "<color=#e8d9bb>Un vehículo blindado descendió y se estrelló contra la espalda del gigantesco Eclipsite, con la torreta causando el máximo daño a tan corta distancia.</color>",
  ui_story_5083_50831601_120_dialog_content = "¡Ahhhh!",
  ui_story_5083_50831601_121_dialog_content = "Te atrapé... ¡Ay!",
  ui_story_5083_50831601_122_dialog_content = "¡Gracias, amigo!",
  ui_story_5083_50831601_123_dialog_content = "¡Esto es ridículo, explotando el vehículo! Y tú casi...",
  ui_story_5083_50831601_124_dialog_content = "No soy yo sin lo loco, ¿verdad?",
  ui_story_5083_50831601_125_dialog_content = "¡Este es mi verdadero yo, lo ves!",
  ui_story_5083_50831601_126_dialog_content = "¿Qué estás haciendo aquí atrás, tú tonto?!",
  ui_story_5083_50831601_127_dialog_content = "¿No enviaste el SOS? ¿No cuento como un respaldo legítimo?",
  ui_story_5083_50831601_128_dialog_content = "La ventaja ha caído. Llegué en un vehículo y ahora no tengo forma de volver, incluso si no me quieres aquí.",
  ui_story_5083_50831601_129_dialog_content = "¡Por qué tú...!",
  ui_story_5083_50831601_130_dialog_content = "¡Esta es la tercera vez ya! ¡No sigas diciéndome que me vaya, anciano!",
  ui_story_5083_50831601_131_dialog_content = "¡Tengo un mensaje para los Eclipsites: Incluso en el subsuelo donde no ven el sol, ¡aún no son dueños del lugar!",
  ui_story_5083_50831601_132_dialog_content = "¡Gannon volverá a brillar, seguro!",
  ui_story_5083_50831601_133_dialog_content = "¡Tonto, probablemente estaremos muertos antes de que llegue la ayuda!",
  ui_story_5083_50831601_134_dialog_content = "En ese caso, espero que la luz del faro brille sobre nuestros cuerpos.",
  ui_story_5083_50831601_135_dialog_content = "La explosión casi me tira del borde, plaga.",
  ui_story_5083_50831601_136_dialog_content = "¿Qué? ¿Todavía vivo en dos piezas?",
  ui_story_5083_50831601_137_dialog_content = "¿Crees que podría ser asesinado por simples explosiones después de destruir tantas subciudades? ¡Soy el <color=#FFB400>nemesis de todo lo que vive</color>!",
  ui_story_5083_50831601_138_dialog_content = "Es gracioso, te llamas a ti mismo la némesis de todo lo que vive, solo para haber estado vivo todo el tiempo.",
  ui_story_5083_50831601_139_dialog_content = "¡Cállate y hagámoslo!",
  ui_story_5083_50831601_140_dialog_content = "¡Solo espera hasta que yo y los chicos te enviemos al infierno!",
  ui_story_5083_50831602_1_dialog_content = "¡No puedes matarme!",
  ui_story_5083_50831602_2_dialog_content = "Je, todo ese hablar de columnas vertebrales irrompibles... No te veo levantarte.",
  ui_story_5083_50831602_3_dialog_content = "¡Maldito seas! ¡Vete al infierno!",
  ui_story_5083_50831602_4_dialog_content = "¡Tú también puedes ir allí con él!",
  ui_story_5083_50831602_5_dialog_content = "<color=#e8d9bb>Barton esquivó un golpe de puño y corrió por el brazo de la criatura.</color>",
  ui_story_5083_50831602_6_dialog_content = "<color=#e8d9bb>Antes de que Syurton pudiera reaccionar, arrancó el trofeo, el cuchillo de Dogg.</color>",
  ui_story_5083_50831602_7_dialog_content = "<color=#e8d9bb>Las dos cuchillas se funden en una en el agarre de Barton y se convierten en suyas. Esquivó y atacó a Syurton sin descanso.</color>",
  ui_story_5083_50831602_8_dialog_content = "<color=#e8d9bb>En un instante, el cuello de Syurton fue cortado, provocando que se agitara y lanzara llamas.</color>",
  ui_story_5083_50831602_9_dialog_content = "<color=#e8d9bb>Pero Barton simplemente continuó cortando mientras las llamas brotaban. El asalto impecable fue el resultado de innumerables </color><color=#FFB400> prácticas </color><color=#e8d9bb> en la base.</color>",
  ui_story_5083_50831602_10_dialog_content = "<color=#e8d9bb>Y lo que era más aterrador era la mirada asesina en los ojos de Barton.</color>",
  ui_story_5083_50831602_11_dialog_content = "<color=#e8d9bb>Se lanzó a través del fuego, dividió la oscuridad y hundió la espada profundamente en el cuello de Syurton.</color>",
  ui_story_5083_50831602_12_dialog_content = "¡Fuera de mí!",
  ui_story_5083_50831602_13_dialog_content = "¡Ni siquiera pienses en lastimar al Coronel Barton! ¡Apunta a los ojos!",
  ui_story_5083_50831602_14_dialog_content = "Este es el fin... ¡Y así es como uso las armas, señor!",
  ui_story_5083_50831602_15_dialog_content = "<color=#e8d9bb>Barton sacó y disparó un arma. La bala golpeó la doble cuchilla y la enterró completamente dentro de Syurton.</color>",
  ui_story_5083_50831602_16_dialog_content = "<color=#e8d9bb>Luego presionó un control remoto para denotar los explosivos que había plantado dentro de su espada.</color>",
  ui_story_5083_50831602_17_dialog_content = "<color=#e8d9bb>Nadie podría haber adivinado que Barton sacrificaría sus armas y las de su amigo cercano por la victoria.</color>",
  ui_story_5083_50831602_18_dialog_content = "¡No! <color=#FFB400>Madre</color>...",
  ui_story_5083_50831602_19_dialog_content = "Disfruta de tu humillación en el abismo, estúpido idiota.",
  ui_story_5083_50831602_20_dialog_content = "¿Estás seguro de que esto está bien?",
  ui_story_5083_50831602_21_dialog_content = "Dogg estará para siempre en nuestros corazones y en el memorial.",
  ui_story_5083_50831602_22_dialog_content = "Su voluntad es suficiente para llevarnos adelante. Nada más es necesario.",
  ui_story_5083_50831602_23_dialog_content = "Oh, ¿está bien, Comandante Pango?",
  ui_story_5083_50831602_24_dialog_content = "No lo toques. Ese golpe le rompió la columna.",
  ui_story_5083_50831602_25_dialog_content = "¡Cuidado, Coronel Barton, los Eclipsites más pequeños aún están en movimiento!",
  ui_story_5083_50831602_26_dialog_content = "Cuida... del estandarte de la 2ª Legión... Ahora eres el comandante, Barton... Lidera a los hombres... y lucha hasta el último aliento...",
  ui_story_5083_50831602_27_dialog_content = "Confía... en tus compañeros de Illumina... la ayuda vendrá...",
  ui_story_5083_50831602_28_dialog_content = "¡Ha salido!",
  ui_story_5083_50831602_29_dialog_content = "¡Maldito seas, maldito seas!",
  ui_story_5083_50831602_30_dialog_content = "¡La segunda legión nunca hará concesiones!",
  ui_story_5083_50831602_31_dialog_content = "The 2nd Legion will never compromise!",
  ui_story_5083_50831602_32_dialog_content = "<color=#e8d9bb>El gigantesco Eclipsite está muerto, pero la batalla continúa. Más pequeños Eclipsites inundaron la única entrada y lucharon contra los soldados.</color>",
  ui_story_5083_50831602_33_dialog_content = "<color=#e8d9bb>Con la bandera en mano, Barton luchó junto a los guerreros hasta que sus espaldas estaban hacia la central eléctrica.</color>",
  ui_story_5083_50831602_34_dialog_content = "<color=#e8d9bb>Cuando miró a su alrededor, quedaban muy pocos hombres.</color>",
  ui_story_5083_50831602_35_dialog_content = "¡Esto está lo suficientemente lejos!",
  ui_story_5083_50831602_36_dialog_content = "Incluso si solo quedamos nosotros, nunca nos comprometeremos... nunca nos comprometeremos...",
  ui_story_5083_50831602_37_dialog_content = "Lucharé contigo hasta el momento final, Barton.",
  ui_story_5083_50831602_38_dialog_content = "Seguiremos al Coronel Barton hasta nuestro último aliento.",
  ui_story_5083_50831602_39_dialog_content = "¡Moriremos defendiendo este pasaje!",
  ui_story_5083_50831602_40_dialog_content = "¿Qué estoy haciendo? ¡Qué tonto soy! ¿Por qué lo pienso justo ahora?",
  ui_story_5083_50831602_41_dialog_content = "Ya sabía cómo iba a terminar esto.",
  ui_story_5083_50831602_42_dialog_content = "En aquel entonces, nos vimos obligados a retirarnos después de vencer por poco a ese gran tonto, pero Pango se quedó y luchó.",
  ui_story_5083_50831602_43_dialog_content = "Todos con él murieron, y él cayó en coma por las lesiones durante más de una década.",
  ui_story_5083_50831602_44_dialog_content = "...",
  ui_story_5083_50831602_45_dialog_content = "No tengo ojos como los tuyos, PlayerName, así que envidio cómo siempre puedes ver la luz.",
  ui_story_5083_50831602_46_dialog_content = "Pero no estoy perdido, porque realmente creo que habrá luz si luchamos hasta el final.",
  ui_story_5083_50831602_47_dialog_content = "Cuando te conocí por primera vez, efectivamente estabas en un camino de esperanza.",
  ui_story_5083_50831602_48_dialog_content = "Me siento honrado de conocerte. Fuiste tú quien nos salvó a ambos innumerables veces.",
  ui_story_5083_50831602_49_dialog_content = "Eres un héroe, pero atormentado por pesadillas... Quería guiarte...",
  ui_story_5083_50831602_50_dialog_content = "No tengo miedo de perderme contigo a mi lado, y las pesadillas no son nada para mí.",
  ui_story_5083_50831602_51_dialog_content = "Pero simplemente no puedo dejarlo ir...",
  ui_story_5083_50831602_52_dialog_content = "¿Alguna vez llegaron refuerzos para el Comandante Pango?",
  ui_story_5083_50831602_53_dialog_content = "Cierto, ¿cómo podría olvidarlo...?",
  ui_story_5083_50831602_54_dialog_content = "Comandante Pango, el verdadero \"pesadilla\" para mí...",
  ui_story_5083_50831602_55_dialog_content = "El futuro de Illumina está lleno de esperanza, pero ¿realmente abandonamos a los veteranos en el pasado?",
  ui_story_5083_50831602_56_dialog_content = "Me altero solo de pensarlo. No deseo que mueran con arrepentimiento y desesperación.",
  ui_story_5083_50831602_57_dialog_content = "No, Barton, Illumina nunca abandonaría a sus defensores.",
  ui_story_5083_50831602_58_dialog_content = "Afortunadamente, finalmente estás aquí. Por favor, mira.",
  ui_story_5083_50831602_59_dialog_content = "Ven conmigo, vanguardias. ¡Rápido y no hagan esperar a los veteranos!",
  ui_story_5083_50831602_60_dialog_content = "Los no combatientes están a salvo. ¡Ahora recuperemos Gannon!",
  ui_story_5083_50831602_61_dialog_content = "<color=#e8d9bb>Reinhardt apareció, blandiendo una lanza ardiente y rompiendo la línea de los Eclipsites. El incendio iluminó la ciudad como el sol de la mañana.</color>",
  ui_story_5083_50831602_62_dialog_content = "Veo luz...",
  ui_story_5083_50831602_63_dialog_content = "¡Mira, Comandante Pango, luz! ¡La ayuda está aquí! ¡Han regresado!",
  ui_story_5083_50831602_64_dialog_content = "No estamos abandonados. ¡Despierta y mira!",
  ui_story_5083_50831602_65_dialog_content = "<color=#e8d9bb>Las campanas sonaron en Gannon, anunciando la llegada del refuerzo, declarando el regreso de los legítimos ocupantes de la ciudad.</color>",
  ui_story_5083_50831602_66_dialog_content = "<size=45>Comandante Pango...!</size>",
  ui_story_5083_50831602_67_dialog_content = "Deja de llorar, mocoso... Aún no estoy muerto...",
  ui_story_5083_50831602_68_dialog_content = "No soy sordo... Por supuesto que escuché...",
  ui_story_5083_50831602_69_dialog_content = "Aparecieron justo a tiempo... Pensé que nunca los vería...",
  ui_story_5083_50831602_70_dialog_content = "¡Es increíble... Realmente, tan increíble...",
  ui_story_5083_50831602_71_dialog_content = "La legión y el futuro de Illumina están ahora en tus manos, mocoso... Controla tu temperamento y sé más serio...",
  ui_story_5083_50831602_72_dialog_content = "Lo haré, Comandante Pango. No te defraudaré.",
  ui_story_5083_50831602_73_dialog_content = "Dejen que se encarguen del comandante, Barton. Deberíamos irnos ahora.",
  ui_story_5083_50831602_74_dialog_content = "Sigue esa luz en tu corazón... Esa es tu fe.",
  ui_story_5083_50831602_75_dialog_content = "Este es el último <color=#FFB400>viaje</color>. Es hora de dejar atrás la pesadilla.",
  ui_story_5083_50831602_76_dialog_content = "Oh, por supuesto. ¡Nada volverá a sujetarme!",
  ui_story_5083_50831602_77_dialog_content = "Adiós, Comandante Pango.",
  ui_story_5083_50831602_78_dialog_content = "¡¿?!",
  ui_story_5083_50831602_79_dialog_content = "El sueño se está convirtiendo de nuevo en realidad... ¿Es esa tu memoria?",
  ui_story_5083_50831602_80_dialog_content = "El comandante Pango y los veteranos nunca se rindieron e incluso no permitieron que la bandera cayera.",
  ui_story_5083_50831602_81_dialog_content = "Sostuvieron a Gannon y defendieron nuestra luz.",
  ui_story_5083_50831602_82_dialog_content = "Duerme, Barton... Es un nuevo día, y descansar es fácil para ti cuando estás en casa.",
  ui_story_5083_50831602_83_dialog_content = "Comandante Pango... PlayerName... Todos... Gracias a todos... por dejarnos seguir el camino sin duda...",
  ui_story_5083_50831602_84_dialog_content = "<color=#e8d9bb>Presencié cuán resilientes eran las estrellas, elevándose e iluminando el cielo nocturno.</color>",
  ui_story_5083_50831602_85_dialog_content = "<color=#e8d9bb>Así como el coraje de los Aurorianos, que emiten el brillo de la vida incluso frente a la muerte.</color>",
  ui_story_5083_50831602_86_dialog_content = "<color=#e8d9bb>Los héroes preservaron las brasas que se convirtieron en un incendio, incinerando el Darkover para dar la bienvenida al amanecer.</color>",
  ui_story_5083_50831602_87_dialog_content = "<color=#e8d9bb>Aunque una estrella perdiera su brillo y cayera, aquellos sobre los que brilló permanecerían firmes en el camino, seguirían buscando su camino hasta el amanecer.</color>",
  ui_story_5083_50831602_88_dialog_content = "<color=#e8d9bb>Y eso sería suficiente...</color>",
  ui_story_5083_50831602_89_dialog_content = "<color=#e8d9bb>Gracias a todos, viejas estrellas.</color>"
}
return config
